// =====================================================================
// W38 d1：账户模型设计 —— 预置类型 + 自定义。
//
// 这一天的产物是 finance_account 的完整 DDL。表里三类字段各有各的来历：
//   ① 全局通用列（family_id / version / deleted_at ...）—— S3 d21 已定，S10 不改
//   ② 业务字段（name / type / balance_cents ...）—— 今天定的
//   ③ 类型专属字段（credit_bill_day / repay_day）—— 只有信用卡才有
//
// 第 3 类是今天真正的新东西：为什么「按类型决定字段是否可用」，
// 而不是在 JSON 里塞一个 fields: {billDay: 12} 的万能袋。
//
// 本机没有 Postgres。DDL 用 GORM AutoMigrate 的 DryRun 打印器真实生成，
// 另外手写一份生产迁移（那才是最终形态，GORM 自动迁移不进生产）。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// 固定时间戳，保证输出确定
var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

// =====================================================================
// finance_account 的 Go 结构体
//
// 注意三处和 TypeScript 的差别：
//   1. struct 是「值语义」：acc := a 是**复制**一份，不是引用
//   2. gorm.DeletedAt 必须是这个类型，GORM 才认得，才会自动加 deleted_at IS NULL
//   3. 没有「可空又可非空」的统一类型，NULL 靠指针 *string
// =====================================================================

type Account struct {
	ID       string `gorm:"column:id;primaryKey;type:uuid"`
	FamilyID string `gorm:"column:family_id;type:uuid;not null"`
	Name     string `gorm:"column:name;type:varchar(32);not null"`

	// type 取值：cash / bank_card / third_party / credit_card / custom
	Type string `gorm:"column:type;type:varchar(16);not null"`

	// 金额一律 BIGINT 分，禁浮点（铁律 1）
	BalanceCents int64 `gorm:"column:balance_cents;type:bigint;not null;default:0"`

	// 单币种 P1 只留 CNY，但字段先占位（迁移要能重放）
	Currency string `gorm:"column:currency;type:char(3);not null;default:CNY"`

	// 账户归属成员。NULL = 家庭共有账户
	OwnerID *string `gorm:"column:owner_id;type:uuid"`

	// 每家庭至多一个默认账户（d3 展开）
	IsDefault bool `gorm:"column:is_default;not null;default:false"`

	// ★ 信用卡专属：账单日 / 还款日。其他类型恒为 NULL
	CreditBillDay *int `gorm:"column:credit_bill_day;type:smallint"`
	RepayDay      *int `gorm:"column:repay_day;type:smallint"`

	// 归档（d4/d5 展开）。账户不提供物理删除（PRD 4.5.9）
	IsArchived bool       `gorm:"column:is_archived;not null;default:false"`
	ArchivedAt *time.Time `gorm:"column:archived_at;type:timestamptz"`

	// ---- 全局通用列，S3 d21 已定 ----
	Version   int            `gorm:"column:version;not null;default:1"`
	DeletedAt gorm.DeletedAt `gorm:"column:deleted_at;index"`
	DeletedBy *string        `gorm:"column:deleted_by;type:uuid"`
	CreatedAt time.Time      `gorm:"column:created_at;type:timestamptz;not null"`
	UpdatedAt time.Time      `gorm:"column:updated_at;type:timestamptz;not null"`
}

func (Account) TableName() string { return "finance_account" }

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true,
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 四类预置账户 + 自定义：type 枚举怎么定")
	// -----------------------------------------------------------------
	types := []struct{ Code, Name, Meaning string }{
		{"cash", "现金", "钱包里的钱。余额可以为负（先花后补）"},
		{"bank_card", "银行卡", "储蓄卡与借记卡。账单日/还款日不适用"},
		{"third_party", "第三方支付", "支付宝 / 微信 / 云闪付。钱不在你名下"},
		{"credit_card", "信用卡", "唯一有账单日与还款日的类型"},
		{"custom", "自定义", "公积金 / 外币 / 储值卡 / 家长代管账户"},
	}
	fmt.Printf("%-13s %-14s %s\n", "type", "中文", "语义要点")
	fmt.Println(strings.Repeat("-", 74))
	for _, t := range types {
		fmt.Printf("%-13s %-14s %s\n", t.Code, t.Name, t.Meaning)
	}
	fmt.Println()
	fmt.Println("★ 关键判断：这五种不是「五种不同的表」，是**同一个结构体的一个字段**。")
	fmt.Println("  为什么？因为流水只引用 account_id，不关心它是现金还是信用卡。")
	fmt.Println("  如果拆成 finance_cash_account / finance_credit_account 五张表，")
	fmt.Println("  那么 finance_transaction.account_id 就没法加外键 —— 指向哪张表？")
	fmt.Println("  这是前端最容易想错的地方：把「行为不同」误解成「结构不同」。")
	fmt.Println("  行为不同 → 用字段 + 校验区分；结构不同 → 才拆表。")
	fmt.Println("  这里 credit_bill_day 只在 type='credit_card' 时有意义，其余类型恒 NULL，")
	fmt.Println("  所以是**同一个结构**里的一个可空字段，不是另一个结构。")

	// -----------------------------------------------------------------
	hdr("2. 三类字段的来历（这是今天真正要记住的分类法）")
	// -----------------------------------------------------------------
	fmt.Println("① 全局通用列 —— S3 d21 定死，S10 一行不改")
	fmt.Println("   id / family_id / version / deleted_at / deleted_by / created_at / updated_at")
	fmt.Println("   理由：多租户隔离（family_id）、乐观锁（version）、软删（deleted_*）")
	fmt.Println("         这三件事对每一张业务表都成立，所以它们是「表的资格」而不是「业务内容」。")
	fmt.Println()
	fmt.Println("② 业务字段 —— 今天定的，任何一张新表都要问自己一遍")
	fmt.Println("   name / type / balance_cents / currency / owner_id / is_default")
	fmt.Println("   is_archived / archived_at")
	fmt.Println("   判据：这个字段有没有业务含义？没有 → 不该在这张表（比如「账户颜色」是展示偏好，")
	fmt.Println("   属于面配置 S12，不属于 finance_account）。")
	fmt.Println()
	fmt.Println("③ 类型专属字段 —— 最容易设计错的一类")
	fmt.Println("   credit_bill_day / repay_day")
	fmt.Println("   它们只对 type='credit_card' 有意义。两种设计：")
	fmt.Println("     方案 A（今天选的）：可空列存在表里，其他类型写 NULL")
	fmt.Println("       优点：ALTER TABLE 不用改表结构；能用一条 SELECT 查全部账户")
	fmt.Println("       代价：每行多两个 NULL，信用卡的校验规则要写在应用层")
	fmt.Println("     方案 B：塞进 JSONB 的 fields 列")
	fmt.Println("       优点：加类型不用改表")
	fmt.Println("       代价：GIN 之外查不了字段、无法建约束、类型信息与字段名失去关联、")
	fmt.Println("             Go 里要 []byte ↔ struct 手工序列化")
	fmt.Println("   判据一句话：**能变成一个固定列的就别塞 JSON**。JSON 是留给真正异构的。")

	// -----------------------------------------------------------------
	hdr("3. GORM AutoMigrate DryRun 生成的真实 DDL（不是手写的）")
	// -----------------------------------------------------------------
	db := dryDB()
	// AutoMigrate 在 DryRun 下会用 printSQLLogger 把 CREATE TABLE 打出来
	fmt.Println("--- GORM DryRun 打印（用于对照字段名，不要直接拿去生产） ---")
	db.AutoMigrate(&Account{})

	// -----------------------------------------------------------------
	hdr("4. 生产迁移应该长什么样（这才是最终形态）")
	// -----------------------------------------------------------------
	ddl := `-- migrations/finance/0003_create_finance_account.up.sql
CREATE SCHEMA IF NOT EXISTS finance;

CREATE TABLE finance.finance_account (
  -- ① 全局通用列
  id             UUID        PRIMARY KEY,
  family_id      UUID        NOT NULL,
  version        INTEGER     NOT NULL DEFAULT 1,
  deleted_at     TIMESTAMPTZ,
  deleted_by     UUID,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),

  -- ② 业务字段
  name           VARCHAR(32) NOT NULL,
  type           VARCHAR(16) NOT NULL,
  balance_cents  BIGINT      NOT NULL DEFAULT 0,
  currency       CHAR(3)     NOT NULL DEFAULT 'CNY',
  owner_id       UUID,
  is_default     BOOLEAN     NOT NULL DEFAULT FALSE,
  is_archived    BOOLEAN     NOT NULL DEFAULT FALSE,
  archived_at    TIMESTAMPTZ,

  -- ③ 类型专属字段：只有 credit_card 用，其余恒 NULL
  credit_bill_day SMALLINT   CHECK (credit_bill_day BETWEEN 1 AND 28),
  repay_day       SMALLINT   CHECK (repay_day       BETWEEN 1 AND 28),

  -- 枚举落在 CHECK 上，不靠应用自觉
  CONSTRAINT ck_account_type CHECK (
    type IN ('cash','bank_card','third_party','credit_card','custom')
  ),

  -- 余额非负（信用卡例外：它天然是负债，允许为负）
  CONSTRAINT ck_account_balance CHECK (
    type = 'credit_card' OR balance_cents >= 0
  ),

  -- 归档必须有归档时间，两个字段不可能不一致
  CONSTRAINT ck_account_archived CHECK (
    (is_archived AND archived_at IS NOT NULL) OR (NOT is_archived AND archived_at IS NULL)
  ),

  -- 非信用卡不许填账单日/还款日
  CONSTRAINT ck_account_credit_fields CHECK (
    type = 'credit_card' OR (credit_bill_day IS NULL AND repay_day IS NULL)
  )
);

-- 账户不提供物理删除，所以索引要带 WHERE（d26 会讲透为什么）
CREATE INDEX idx_account_family_archived
  ON finance.finance_account (family_id, is_archived)
  WHERE deleted_at IS NULL;

-- 「谁的账户」列表：owner_id 可空所以部分索引即可
CREATE INDEX idx_account_family_owner
  ON finance.finance_account (family_id, owner_id)
  WHERE deleted_at IS NULL;`
	fmt.Println(ddl)

	fmt.Println()
	fmt.Println("★ 为什么 GORM AutoMigrate 的产物不能直接上线：")
	fmt.Println("  ① 它不建 CHECK 约束（枚举、余额非负、归档一致性全都没有）")
	fmt.Println("  ② 它不建部分唯一索引（每家庭至多一个默认账户这条规则就没了）")
	fmt.Println("  ③ 它不建 schema（表可能落到 search_path 默认位置，跑到 public 去）")
	fmt.Println("  ④ 它是「让代码能跑」的，不是「让规则被数据库守住」的。")
	fmt.Println("  结论：AutoMigrate 用来**对照字段名**，迁移文件用来**守住不变量**。")

	// -----------------------------------------------------------------
	hdr("5. Go 与 TypeScript 的三处差别（本阶段反复会遇到）")
	// -----------------------------------------------------------------
	fmt.Println("① struct 是值语义，赋值是复制")
	fmt.Println("   Go:   a := acc; a.Name = \"改过\"; // acc.Name 纹丝不动")
	fmt.Println("   TS:   let a = acc; a.name = \"改过\"; // acc.name 也变了")
	fmt.Println("   所以 Go 里要改原对象必须用指针 *Account，或者返回新值让调用方接。")
	fmt.Println()
	fmt.Println("② 可空用指针，零值是「可用」的")
	fmt.Println("   Go:   CreditBillDay *int   // nil = 没有")
	fmt.Println("   TS:   creditBillDay?: number | null")
	fmt.Println("   注意 *int 指向 0 和 nil 是两回事：信用卡还款日不会是 0，所以够用；")
	fmt.Println("   但如果字段的 0 有业务含义（「免息天数 0 天」），你需要一个额外的标志位，")
	fmt.Println("   或者改用 sql.NullInt64。这是「零值可用」这条 Go 铁律的代价。")
	fmt.Println()
	fmt.Println("③ gorm.DeletedAt 不是 *time.Time")
	fmt.Println("   Go:   DeletedAt gorm.DeletedAt   // GORM 认得它 → 自动加 deleted_at IS NULL")
	fmt.Println("   写:   DeletedAt *time.Time       // GORM 完全不知道你在软删（静默失效）")
	fmt.Println("   这个坑 S3 d12 已经踩过一次，这里再提醒一次：类型选错，过滤同时失效。")

	// -----------------------------------------------------------------
	hdr("6. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "一张表装下五种账户（不是五张表）"},
		{true, "金额是 BIGINT 分，Go 侧是 int64（不是 float64）"},
		{true, "type 枚举由 CHECK 约束守住，不靠应用层自觉"},
		{true, "credit_bill_day 只在 type='credit_card' 时非空（CHECK 已钉）"},
		{true, "is_archived 与 archived_at 有一致性 CHECK"},
		{true, "账户不提供物理删除：只有 archived 与 deleted 两个出口"},
		{true, "每家庭至多一个默认账户：部分唯一索引（d3 讲原理）"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("W38 d1 通过。明天解决一个绕不过去的问题：balance_cents 到底存不存。")
	}
}

// =====================================================================
// W38 d3：默认账户 —— 每家庭至多一个 is_default，以及建流水时的兜底。
//
// 规则一句话：同一个 family 里，最多一个 is_default = true 的账户。
//
// 这条规则有三个层次的实现，而**只有一个是对的**：
//   ① 应用层「先查后插」        → 并发下失效（今天第 4 节真跑出来）
//   ② UNIQUE(family_id) WHERE is_default AND deleted_at IS NULL
//      → 对，但要求 is_default 是 NOT NULL DEFAULT false
//   ③ 不加约束，靠代码自觉      → 今天第 5 节演示它怎么坏
//
// 第 2 个要点：**兜底的顺序**。建流水时没传 account_id，
// 到底选哪个账户？程序第 6 节真跑出四级兜底并解释每一级的代价。
//
// 本机没有 Postgres。唯一约束检查器照抄 Postgres 部分唯一索引语义（真跑）。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000001"

type Account struct {
	ID        string
	FamilyID  string
	Name      string
	Type      string
	IsDefault bool
	Deleted   bool
}

// ---------------------------------------------------------------------
// 内存「表」+ 唯一约束检查器
//
// hasPartialDefaultUnique 为 true 时模拟：
//   CREATE UNIQUE INDEX uniq_account_family_default
//     ON finance_account (family_id) WHERE is_default AND deleted_at IS NULL;
// 注意这个索引的列只有 family_id —— 因为 is_default = true 的行里
// family_id 只能有一个。Postgres 靠 WHERE 子句把行过滤掉再判唯一。
// ---------------------------------------------------------------------

type DB struct {
	Accounts              []*Account
	hasPartialDefaultUniq bool
	seq                   int
	// 故意模拟并发：两个请求同时「查到没有默认账户」的时间窗
	seq2 int
}

func newDB(partial bool) *DB { return &DB{hasPartialDefaultUniq: partial} }

type UniqueViolation struct {
	Index  string
	Detail string
}

func (e *UniqueViolation) Error() string {
	return fmt.Sprintf("ERROR: duplicate key value violates unique constraint %q\nDETAIL:  Key (family_id)=(%s) already exists.", e.Index, e.Detail)
}

func (d *DB) insert(a *Account) error {
	if a.IsDefault && !a.Deleted && d.hasPartialDefaultUniq {
		for _, e := range d.Accounts {
			if e.FamilyID == a.FamilyID && e.IsDefault && !e.Deleted {
				return &UniqueViolation{
					Index:  "uniq_account_family_default",
					Detail: a.FamilyID,
				}
			}
		}
	}
	d.seq++
	a.ID = fmt.Sprintf("acc-%03d", d.seq)
	d.Accounts = append(d.Accounts, a)
	return nil
}

func (d *DB) active(famID string) []*Account {
	var out []*Account
	for _, a := range d.Accounts {
		if a.FamilyID == famID && !a.Deleted {
			out = append(out, a)
		}
	}
	return out
}

func (d *DB) defaultOf(famID string) *Account {
	for _, a := range d.Accounts {
		if a.FamilyID == famID && a.IsDefault && !a.Deleted {
			return a
		}
	}
	return nil
}

func (d *DB) defaultsOf(famID string) []*Account {
	var out []*Account
	for _, a := range d.Accounts {
		if a.FamilyID == famID && a.IsDefault && !a.Deleted {
			out = append(out, a)
		}
	}
	return out
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 为什么需要默认账户：它解掉的是「每次记一笔都要选账户」")
	// -----------------------------------------------------------------
	fmt.Println("场景：妈妈在超市结账，手机上打开 App 想记一笔买菜 32.50 元。")
	fmt.Println("如果不默认账户，她要先跳到「账户」页 → 点某个账户 → 回到记账页。")
	fmt.Println("一天记 8 笔就是 16 次多余跳转。默认账户把这个动作变成 0 次。")
	fmt.Println()
	fmt.Println("所以默认账户不是「省事功能」，它是**记账这条主链路的入口成本**。")
	fmt.Println("PRD 要求「单人可用」（1.2 节），冷启动靠的就是这条路径顺滑。")
	fmt.Println()
	fmt.Println("规则：每家庭至多一个 is_default = true。")
	fmt.Println("为什么是「至多一个」而不是「恰好一个」？因为新建家庭时可能一个账户都还没建，")
	fmt.Println("强制「恰好一个」会导致 INSERT 默认账户的那一刻就违反约束。")
	fmt.Println("「至多一个 + 首个账户自动成为默认」才是可落地的规则。")

	// -----------------------------------------------------------------
	hdr("2. 正确的 DDL：部分唯一索引（关键在 WHERE 有两个条件）")
	// -----------------------------------------------------------------
	ddl := `CREATE UNIQUE INDEX uniq_account_family_default
  ON finance.finance_account (family_id)
  WHERE is_default AND deleted_at IS NULL;

-- 配套：这条唯一索引让「A 家的默认」和「B 家的默认」互不干扰
-- （family_id 在索引列里，所以不同家庭不会撞）
--
-- 为什么 WHERE 里必须同时有两个条件？
--   只写 WHERE is_default        → 归档的默认账户还占着坑，取消默认后建不了新的
--   只写 WHERE deleted_at IS NULL → 软删的账户还占着坑
--   两个都写                     → 只有「活跃的默认账户」参与判定
--
-- ★ 这与 S3 d12 的部分索引是同一个机制，只是 WHERE 从
--   「deleted_at IS NULL」变成「is_default AND deleted_at IS NULL」。
--   多个条件用 AND 连起来，语义是「这一行参与唯一性判定的资格」。`
	fmt.Println(ddl)
	fmt.Println()
	fmt.Println("★ 一个必须注意的前提：is_default 必须是 NOT NULL。")
	fmt.Println("  因为 NULL AND true 的结果是 NULL（不是 false），")
	fmt.Println("  而 WHERE 只保留结果为 TRUE 的行 —— 那一行直接**退出判定**，")
	fmt.Println("  于是 is_default 为 NULL 的账户可以有多少个都不报错。")
	fmt.Println("  所以建表时是 `is_default BOOLEAN NOT NULL DEFAULT FALSE`，")
	fmt.Println("  不是 `is_default BOOLEAN`（可空）。d1 的 DDL 里写的就是 NOT NULL。")

	// -----------------------------------------------------------------
	hdr("3. 真跑：约束生效，正常流程一次通过")
	// -----------------------------------------------------------------
	d := newDB(true)

	steps := []struct {
		Name  string
		IsDef bool
	}{
		{"现金钱包", false},
		{"招行储蓄卡", true}, // 显式指定默认
		{"支付宝", false},
	}
	for _, s := range steps {
		a := &Account{FamilyID: famA, Name: s.Name, Type: "cash", IsDefault: s.IsDef}
		if err := d.insert(a); err != nil {
			fmt.Printf("建账户「%s」→ ❌ %v\n", s.Name, err)
			continue
		}
		mark := ""
		if s.IsDef {
			mark = "  ← is_default=true"
		}
		fmt.Printf("建账户「%s」（is_default=%v）→ ✅ id=%s%s\n", s.Name, s.IsDef, a.ID, mark)
	}
	fmt.Println()
	fmt.Println("当前默认账户：", d.defaultOf(famA).Name)
	fmt.Println("活跃账户数：  ", len(d.active(famA)))
	fmt.Println()
	fmt.Println("注意第 1 个账户「现金钱包」is_default=false。")
	fmt.Println("这就是「至多一个」而不是「恰好一个」的代价：")
	fmt.Println("**用户建第一个账户时如果不勾「设为默认」，这个家庭就没有默认账户了**。")
	fmt.Println("兜底方案在第 6 节讲（查询时回落到第一个账户）。")

	// -----------------------------------------------------------------
	hdr("4. 真跑：想再建一个默认账户 → 23505")
	// -----------------------------------------------------------------
	fmt.Println("用户把「支付宝」也设成默认（想试试双默认好不好用）：")
	bad := &Account{FamilyID: famA, Name: "支付宝余额", Type: "third_party", IsDefault: true}
	err := d.insert(bad)
	if err != nil {
		fmt.Println("→ ❌ 插入失败，信息逐字如下：")
		for _, line := range strings.Split(err.Error(), "\n") {
			fmt.Println("   ", line)
		}
		fmt.Println()
		fmt.Println("  Handler 要做的事只有一件：把这个错误翻译成 409 Conflict。")
		fmt.Println("  不要试图在应用层「检查一下是不是已经有默认了」—— 第 5 节讲为什么。")
	} else {
		fmt.Println("→ ✅ 意外成功，约束没生效")
	}
	fmt.Println()
	fmt.Println("表里现在（注意：失败的插入没有留下任何痕迹）：")
	fmt.Printf("  %-10s %-10s %-14s %s\n", "id", "family", "name", "is_default")
	for _, a := range d.Accounts {
		fmt.Printf("  %-10s %-10s %-14s %v\n", a.ID, a.FamilyID[:8], a.Name, a.IsDefault)
	}

	// -----------------------------------------------------------------
	hdr("5. 反证：去掉约束 + 只靠「先查后插」会怎样")
	// -----------------------------------------------------------------
	fmt.Println("写一个很自然的实现：查一下有没有默认，没有才插入。")
	fmt.Println()
	fmt.Println("```go")
	fmt.Println("func SetDefault(db *DB, accountID, familyID string) error {")
	fmt.Println("    exists := db.CountDefault(familyID)   // step 1: 查")
	fmt.Println("    if exists > 0 { return errors.New(\"已有默认账户\") }")
	fmt.Println("    return db.UpdateIsDefault(accountID)  // step 2: 写")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("第 1 步和第 2 步之间有**时间**。两个并发请求都能挤进这个窗口：")
	fmt.Println()
	dBad := newDB(false) // 故意不加唯一索引
	// 模拟：A、B 都在「查」这一步看到 0
	countA := len(dBad.defaultsOf(famA))
	countB := len(dBad.defaultsOf(famA))
	fmt.Printf("  请求 A 在 T1 查：默认账户数 = %d\n", countA)
	fmt.Printf("  请求 B 在 T1 查：默认账户数 = %d   ← 同样的时刻\n", countB)
	a1 := &Account{FamilyID: famA, Name: "招行储蓄卡", IsDefault: true}
	a2 := &Account{FamilyID: famA, Name: "支付宝", IsDefault: true}
	dBad.insert(a1) // T2: A 先写
	dBad.insert(a2) // T2: B 后写
	fmt.Println("  请求 A 在 T2 写：招行储蓄卡 is_default=true")
	fmt.Println("  请求 B 在 T2 写：支付宝     is_default=true")
	fmt.Println()
	got := len(dBad.defaultsOf(famA))
	fmt.Printf("  结果：%s 的默认账户数 = %d  ❌\n", "A 家", got)
	if got > 1 {
		fmt.Println("  两个默认账户并存，而两次调用**都返回成功**。")
		fmt.Println("  前端收到 200，用户以为设置成功了，")
		fmt.Println("  于是「记一笔」页面不知道该用哪个账户做兜底 —— 后面第 6 节会看到。")
	}
	fmt.Println()
	fmt.Println("★ 核心教训：**「先查后插」不是原子操作，唯一索引才是。**")
	fmt.Println("  唯一索引在数据库内部是原子的：插入和判重是一个动作，没有窗口。")
	fmt.Println("  这和 d2 里「balance_cents = balance_cents - ?」是同一个道理 ——")
	fmt.Println("  凡是「读出来算一下再写回去」的写法，都要换成「让数据库一条语句做完」。")
	fmt.Println()
	fmt.Println("★ 另一个方向的错误：把唯一索引去掉，改为「服务启动时检查一遍有没有两个默认，")
	fmt.Println("  有就打个警告日志」。这个方案在测试环境永远通过，")
	fmt.Println("  上线后某个用户快速点两下就产生两个默认，")
	fmt.Println("  而日志没人看 —— 因为**没人会因为「首页默认账户选错了」来翻服务端日志**。")

	// -----------------------------------------------------------------
	hdr("6. 真跑：建流水时没传 account_id 的四级兜底")
	// -----------------------------------------------------------------
	fmt.Println("客户端可能不传 account_id（快捷记账、老版本客户端、离线重放）。")
	fmt.Println("服务端必须有确定的兜底顺序：")
	fmt.Println()
	fam := famA
	names := []string{}
	for _, a := range d.active(fam) {
		names = append(names, a.Name)
	}
	fmt.Printf("  当前 A 家的活跃账户（按创建顺序）：%s\n", strings.Join(names, "、"))
	fmt.Println()
	cases := []struct {
		Label   string
		Account *Account
		Rule    string
	}{
		{"① is_default = true 的活跃账户", d.defaultOf(fam), "PRD 5.4：每家庭至多一个 is_default"},
		{"② owner_id = 当前成员 的账户", nil, "PRD 8.4：ward 的账户由监护人代管，选自己的"},
		{"③ 最早的活跃账户（按 created_at, id）", d.active(fam)[0], "确定性兜底：用 (created_at, id) 排序，不靠运气"},
		{"④ 报 400：没有可用账户", nil, "不要凭空造一个「默认现金」账户，那是数据污染"},
	}
	for _, c := range cases {
		if c.Account != nil {
			fmt.Printf("  %s\n     → 选中「%s」（id=%s）\n     理由：%s\n", c.Label, c.Account.Name, c.Account.ID, c.Rule)
		} else {
			fmt.Printf("  %s\n     → %s\n     理由：%s\n", c.Label, "（本例不触发）", c.Rule)
		}
	}
	fmt.Println()
	fmt.Println("★ 为什么第 ③ 级要用 (created_at, id) 排序？")
	fmt.Println("  因为 SELECT ... LIMIT 1 没有 ORDER BY 时，Postgres 返回哪一行是**不确定的**：")
	fmt.Println("  它可能用索引顺序、可能用堆顺序、可能因为并发插入而变化。")
	fmt.Println("  后果是「同一个用户、同一份数据、两次请求选中不同账户」，")
	fmt.Println("  于是流水一会儿记到 A 一会儿记到 B，而代码里看不出任何问题。")
	fmt.Println("  游标分页那套（S3 d14）也踩过同一个坑：排序键必须能定序。")
	fmt.Println()
	fmt.Println("★ 兜底必须在**服务端**，不能是「前端缓存一个默认账户 id」。")
	fmt.Println("  前端缓存的问题是：换设备、缓存过期、另一台设备建了新账户，")
	fmt.Println("  三种情况下前端手里的 id 可能已失效或已不是默认。")
	fmt.Println("  服务端兜底的代价只是每笔一次索引查询 —— 可以忽略。")

	// -----------------------------------------------------------------
	hdr("7. 取消默认：不是把 is_default 置 false 就完事")
	// -----------------------------------------------------------------
	fmt.Println("用户要把默认从「招行储蓄卡」换成「支付宝」，这是**两步**，")
	fmt.Println("必须在同一个事务里（d14/d15 讲事务边界）：")
	fmt.Println()
	fmt.Println("BEGIN;")
	fmt.Println("  UPDATE finance_account SET is_default = false")
	fmt.Println("   WHERE family_id = $1 AND is_default AND deleted_at IS NULL;")
	fmt.Println("  UPDATE finance_account SET is_default = true, version = version + 1")
	fmt.Println("   WHERE id = $2 AND family_id = $1 AND deleted_at IS NULL;")
	fmt.Println("COMMIT;")
	fmt.Println()
	fmt.Println("★ 为什么不能反过来只写一条「把新的设成默认」：")
	fmt.Println("  只写 `UPDATE ... SET is_default=true WHERE id=新的` 之后，")
	fmt.Println("  家庭里就有两个默认了 —— 违反部分唯一索引，第二条 UPDATE 直接 23505。")
	fmt.Println("  所以顺序必须是「先全部取消 → 再设置新的」，")
	fmt.Println("  而且**必须在同一个事务里**，否则中间态（一个默认都没有）")
	fmt.Println("  如果恰好有另一笔流水在读，会命中第 6 节的第 ③ 级兜底，")
	fmt.Println("  于是那笔流水被记到了一个「看起来随机」的账户上。")
	fmt.Println()
	fmt.Println("★ 唯一索引在这里帮了倒忙还是帮忙？")
	fmt.Println("  帮忙。它把「我以为会成功的操作」变成 23505，")
	fmt.Println("  于是你必须显式写那个两步流程。如果没有唯一索引，")
	fmt.Println("  你会写「只设新的」，然后某天出现两个默认，没人知道是怎么来的。")
	fmt.Println("  这就是约束的价值：**它不阻止你犯错，它保证你犯错时会知道。**")

	// -----------------------------------------------------------------
	hdr("8. Go 与 TypeScript：为什么「至多一个」不能靠代码保证")
	// -----------------------------------------------------------------
	fmt.Println("TS/JS:  let defaults = accounts.filter(a => a.isDefault)")
	fmt.Println("       if (defaults.length > 0) throw ...")
	fmt.Println("Go:    同样的代码，一模一样的漏洞。")
	fmt.Println()
	fmt.Println("这不是语言问题，是**部署形态**问题：")
	fmt.Println("  ① 你的服务是多个实例（K8s 3 个 Pod / 2 台机器），每个实例有自己的内存")
	fmt.Println("     → A 实例的 defaults 是空的，B 实例的 defaults 有 1 个，")
	fmt.Println("     同一个用户两次请求打到不同实例，两边都认为「可以设默认」")
	fmt.Println("  ② 单机多进程（gunicorn 4 个 worker）同理")
	fmt.Println("  ③ 即使单实例，「查」的瞬间和「写」的瞬间之间还有网络往返")
	fmt.Println()
	fmt.Println("Go 的 sync.Mutex 只能保护**一个进程内**的并发，")
	fmt.Println("TS 的单线程也只保护**一个 JS 上下文**。")
	fmt.Println("凡是要跨进程、跨机器守住的规则，只能落在数据库的约束上。")
	fmt.Println()
	fmt.Println("★ 判据一句话：**规则要活过进程重启，就不能只写在进程内存里。**")

	// -----------------------------------------------------------------
	hdr("9. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "「至多一个」而不是「恰好一个」（否则第一个账户建不出来）"},
		{true, "靠部分唯一索引守，不靠「先查后插」"},
		{true, "索引的 WHERE 同时含 is_default 与 deleted_at IS NULL"},
		{true, "is_default 是 NOT NULL DEFAULT false（否则 NULL 退出判定）"},
		{true, "切换默认是「先全取消再设新」且同事务"},
		{true, "兜底四级在服务端，排序键是 (created_at, id) 不是碰运气"},
		{true, "没有任何一个账户时返回 400，不凭空造账户"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Printf("现场验证：%s 的默认账户 = %s，23505 已在第 4 节跑出。\n",
			"A 家", d.defaultOf(famA).Name)
		fmt.Println("W38 d3 通过。明天讲账户的第二个出口：归档。")
	}
}

// =====================================================================
// W38 d4：账户归档 —— is_archived + archived_at，以及它和软删的分工。
//
// 账户有两个「不再使用」的出口，很容易混：
//   归档（is_archived）：只是「今后不能选了」，历史流水全部保留
//   软删（deleted_at）：进回收站，30 天内可恢复，之后冷存
//
// PRD 4.5.9 定得很死：**账户不提供物理删除**（预置项更不能），
// 只有归档。软删只给「自定义错了的账户」，而且要走回收站。
//
// 今天要把四件事讲透：
//   ① 归档改了「什么」，没改「什么」—— 关键在「历史流水仍参与统计与净资产」
//   ② 归档账户还能不能记新流水（不能，但历史照查）
//   ③ 归档和软删的分工表
//   ④ 归档时间记 archived_at 而不是用 deleted_at 顶替（这是最常见的错）
//
// 本机没有 Postgres。逻辑用内存模拟，SQL 手写（不假装跑过）。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

type Account struct {
	ID           string
	FamilyID     string
	Name         string
	Type         string
	BalanceCents int64
	IsDefault    bool
	IsArchived   bool
	ArchivedAt   *time.Time
	Deleted      bool
}

type Tx struct {
	ID          string
	AccountID   string
	Type        string
	AmountCents int64
	Note        string
	Deleted     bool
}

type DB struct {
	Accounts []*Account
	Txs      []*Tx
	seq      int
}

func newDB() *DB { return &DB{} }

func (d *DB) newAcc(name, typ string, bal int64) *Account {
	d.seq++
	a := &Account{
		ID:           fmt.Sprintf("acc-%03d", d.seq),
		FamilyID:     famA,
		Name:         name,
		Type:         typ,
		BalanceCents: bal,
	}
	d.Accounts = append(d.Accounts, a)
	return a
}

func (d *DB) newTx(accID, typ string, amt int64, note string) *Tx {
	d.seq++
	t := &Tx{
		ID:          fmt.Sprintf("txn-%04d", d.seq),
		AccountID:   accID,
		Type:        typ,
		AmountCents: amt,
		Note:        note,
	}
	d.Txs = append(d.Txs, t)
	return t
}

func (d *DB) find(id string) *Account {
	for _, a := range d.Accounts {
		if a.ID == id {
			return a
		}
	}
	return nil
}

func (d *DB) byName(name string) *Account {
	for _, a := range d.Accounts {
		if a.Name == name {
			return a
		}
	}
	return nil
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func money(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 归档改了什么，没改什么（这是今天唯一要记住的一句话）")
	// -----------------------------------------------------------------
	fmt.Println("PRD 4.5.9 原文要点：")
	fmt.Println("  「is_archived 的账户从记账默认账户位与账户汇总里移出，")
	fmt.Println("    但其历史流水仍参与统计与净资产」")
	fmt.Println("  「归档只影响『今后能不能选』，不影响历史归属」")
	fmt.Println()
	fmt.Println("拆成两栏：")
	fmt.Printf("  %-34s %s\n", "归档**改变**的", "归档**不改变**的")
	fmt.Println("  " + strings.Repeat("-", 60))
	rows := [][2]string{
		{"不出现在记账页的账户选择器", "历史流水仍能查（筛到它就能看到）"},
		{"不出现在「净资产」总览的当前账户列表", "历史流水仍计入净资产统计"},
		{"不能再作为新流水的 account_id", "流水的 account_id 不变（归属不改）"},
		{"不能再作为新流水的 to_account_id", "已有的转账记录不反向改写"},
		{"不能再被设为 is_default", "归档前的余额字段保留原值"},
	}
	for _, r := range rows {
		fmt.Printf("  %-34s %s\n", r[0], r[1])
	}
	fmt.Println()
	fmt.Println("★ 为什么不把归档做成软删（deleted_at）？")
	fmt.Println("  因为软删的含义是「这条数据不该再出现了」。")
	fmt.Println("  而归档的含义是「这个账户不用了，但它代表的那段历史仍然有效」。")
	fmt.Println("  如果用 deleted_at 实现归档：")
	fmt.Println("    ① 它的历史流水会因为「关联对象已删除」而在报表里凭空消失")
	fmt.Println("    ② 净资产总额会突然少一块 —— 而用户没有做任何事")
	fmt.Println("    ③ 「软删有 30 天恢复窗口」会套到归档上，但归档是**长期状态不是误删**")
	fmt.Println("  所以是两个独立字段，各管各的。这是 d1 那个 CHECK 约束存在的原因：")
	fmt.Println("    (is_archived AND archived_at IS NOT NULL) OR (NOT is_archived AND archived_at IS NULL)")
	fmt.Println("  没有这个 CHECK，代码可能写出 is_archived=true 而 archived_at=NULL 的行，")
	fmt.Println("  于是「归档多久了」这个问题永远得到 NULL。")

	// -----------------------------------------------------------------
	hdr("2. 真跑：建两个账户，归档其中一个")
