// =====================================================================
// W38 d5：归档的硬约束 —— 余额非 0 拒绝归档。
//
// 这是 S10 判据第 3 条：**账户余额非 0 时归档被拒绝，返回业务错误码**。
//
// 为什么这条规则存在（PRD 4.5.9）：
//   「归档前若该账户余额非 0，必须先做一笔转账到存续账户或显式确认为 0，
//     避免净资产与账户合计长期不一致」
//
// 直觉解释：归档只是隐藏账户，不影响钱。那为什么还要拦？
// 因为如果允许余额非 0 就归档，会出现一个**没人能解释的界面**：
//   首页净资产 = 687（因为归档账户也算）
//   但用户在「账户」页看到的所有余额加起来 = 452
//   差 235 元无处可查，用户会以为系统算错了。
//
// 今天真跑出四种情况：
//   ① 余额 = 0     → 允许归档（200）
//   ② 余额 ≠ 0     → 拒绝（409 + code 4001）
//   ③ 余额 = 0 但有流水 → 允许，并说明为什么（余额才是判据，不是流水数）
//   ④ 信用卡余额 < 0  → **允许**，这条特例必须讲（负债账户例外）
//
// 本机没有 Postgres。逻辑内存模拟，错误码与响应体逐字给出。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

type Account struct {
	ID           string
	FamilyID     string
	Name         string
	Type         string
	BalanceCents int64
	IsDefault    bool
	IsArchived   bool
	ArchivedAt   *time.Time
	Version      int
	Deleted      bool
}

type DB struct {
	Accounts []*Account
	seq      int
}

func newDB() *DB { return &DB{} }

func (d *DB) newAcc(name, typ string, bal int64) *Account {
	d.seq++
	a := &Account{
		ID:           fmt.Sprintf("acc-%03d", d.seq),
		FamilyID:     famA,
		Name:         name,
		Type:         typ,
		BalanceCents: bal,
		Version:      1,
	}
	d.Accounts = append(d.Accounts, a)
	return a
}

// ---------------------------------------------------------------------
// 统一响应体（PRD tech-plan 6.2）
// ---------------------------------------------------------------------

type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

// 业务错误：code 段 4001-4002 是「业务规则」
type BizError struct {
	HTTPStatus int
	Code       int
	Message    string
	Hint       string // 额外返回的引导字段
}

func (e *BizError) Error() string {
	return fmt.Sprintf("%d %s", e.HTTPStatus, e.Message)
}

// ---------------------------------------------------------------------
// 核心：归档校验
// ---------------------------------------------------------------------

// ErrBalanceNotZero 是「余额非 0 不能归档」
func ErrBalanceNotZero(acc *Account) *BizError {
	return &BizError{
		HTTPStatus: 409,  // Conflict：请求合法但与当前状态冲突
		Code:       4001, // tech-plan 6.2：4001 余额非 0 不能归档
		Message:    fmt.Sprintf("账户「%s」余额不为 %s，无法归档", acc.Name, yuan(acc.BalanceCents)),
		Hint:       "请先转账转出全部余额，或确认余额为 0 后再归档",
	}
}

// 越权：返 404 不返 403（S5 硬约定）
func ErrNotFound() *BizError {
	return &BizError{
		HTTPStatus: 404,
		Code:       3001,
		Message:    "账户不存在",
	}
}

// 乐观锁冲突（W41 展开，这里只放占位以便看全貌）
func ErrVersionConflict(cur, got int) *BizError {
	return &BizError{
		HTTPStatus: 409,
		Code:       40901,
		Message:    "数据已被他人修改，请刷新后重试",
		Hint:       fmt.Sprintf("服务端当前版本 = %d，你的请求基于版本 = %d", cur, got),
	}
}

func Archive(d *DB, accID, familyID string, version int) (*Envelope, *BizError) {
	// 1. 找账户。**必须带 family_id**，且查不到返 404 不返 403
	var acc *Account
	for _, a := range d.Accounts {
		if a.ID == accID && a.FamilyID == familyID && !a.Deleted {
			acc = a
			break
		}
	}
	if acc == nil {
		return nil, ErrNotFound()
	}

	// 2. ★ 幂等检查放在 version 检查**之前**。
	//    原因：用户双击归档按钮时，两个请求带的是**同一个 version**。
	//    第一个请求成功（version 1 → 2），第二个请求带着 version=1 来，
	//    如果先查 version 就会返回 409，用户看到「数据已被他人修改」——
	//    而实际上根本没有人改，是他自己点了两下。
	//    所以「已经处于目标状态」要先判定，命中就直接返 200。
	if acc.IsArchived {
		return &Envelope{Code: 0, Message: "ok", Data: map[string]any{
			"id": acc.ID, "is_archived": true,
			"archived_at": acc.ArchivedAt.Format(time.RFC3339), "version": acc.Version,
		}}, nil
	}

	// 3. 乐观锁：带上客户端读到的 version
	if acc.Version != version {
		return nil, ErrVersionConflict(acc.Version, version)
	}

	// 4. ★ 今天的核心校验
	//    判据是 **balance_cents != 0**，不是「有没有流水」
	//    例外：信用卡（type='credit_card'）余额天然为负（欠款），
	//    欠 2350 元不能叫「还有钱没处理完」—— 欠款是账户的固有状态。
	//    所以负债型账户跳过这条校验，否则信用卡永远无法归档。
	if acc.Type != "credit_card" && acc.BalanceCents != 0 {
		return nil, ErrBalanceNotZero(acc)
	}

	// 5. 通过。顺带取消默认身份（d4 第 3 节 ④ 的口径）
	at := fixedNow
	acc.IsArchived = true
	acc.ArchivedAt = &at
	acc.Version++

	return &Envelope{Code: 0, Message: "ok", Data: map[string]any{
		"id": acc.ID, "is_archived": true,
		"archived_at": at.Format(time.RFC3339), "version": acc.Version,
		"cleared_default": true,
	}}, nil
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func show(label string, env *Envelope, biz *BizError) {
	fmt.Printf("  %s\n", label)
	if biz != nil {
		fmt.Printf("    HTTP %d\n", biz.HTTPStatus)
		fmt.Printf("    {\n")
		fmt.Printf("      \"code\": %d,\n", biz.Code)
		fmt.Printf("      \"message\": %q,\n", biz.Message)
		fmt.Printf("      \"data\": { \"hint\": %q },\n", biz.Hint)
		fmt.Printf("      \"request_id\": \"req-7f3a9c12\"\n")
		fmt.Printf("    }\n")
		return
	}
	fmt.Println("    HTTP 200")
	fmt.Printf("    code=%d message=%q\n", env.Code, env.Message)
	if m, ok := env.Data.(map[string]any); ok {
		fmt.Printf("    data=%v\n", m)
	}
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 为什么「余额非 0 就拒绝归档」这条规则值得存在")
	// -----------------------------------------------------------------
	fmt.Println("反例：允许余额 235 元的账户直接归档，会得到这样的界面。")
	fmt.Println()
	d0 := newDB()
	old := d0.newAcc("招行储蓄卡(旧)", "bank_card", 23500)
	d0.newAcc("招行储蓄卡(新)", "bank_card", 45200)
	old.IsArchived = true
	at := time.Date(2026, 10, 1, 8, 30, 0, 0, time.UTC)
	old.ArchivedAt = &at

	// 净资产 = 含归档账户的全部余额
	var net int64
	for _, a := range d0.Accounts {
		net += a.BalanceCents
	}
	// 账户页用户能看到的合计 = 只有未归档的
	var visible int64
	for _, a := range d0.Accounts {
		if !a.IsArchived {
			visible += a.BalanceCents
		}
	}

	fmt.Printf("  首页「净资产」卡片显示：%s 元   ← 它把归档账户也算进去了\n", yuan(net))
	fmt.Printf("  「账户」页用户能看到的余额合计：%s 元  ← 归档的不在列表里\n", yuan(visible))
	fmt.Printf("  差额：%s 元\n", yuan(net-visible))
	fmt.Println()
	fmt.Println("  用户会怎么想？「这个 App 算错了，丢了 235 块」。")
	fmt.Println("  他会去哪里找？找遍所有页面，找不到 —— 因为那 235 在一个")
	fmt.Println("  **他看不到的账户**里，而账户页连「已归档」这个筛选器都没有。")
	fmt.Println()
	fmt.Println("★ 这就是 PRD 说的「避免净资产与账户合计长期不一致」。")
	fmt.Println("  不是数据不一致（数据是对的），是**用户眼里的不一致**。")
	fmt.Println("  而用户眼里的不一致，最终都会变成工单。")
	fmt.Println()
	fmt.Println("  本项目的解法不是「把归档账户也显示在账户页」（那要额外设计筛选器），")
	fmt.Println("  而是**在归档这一步就把状态推到一个用户能解释的态**：")
	fmt.Println("  要么余额归零（钱转到别的账户了），要么账户没归档。")
	fmt.Println("  「推到一个能解释的态」比「提供更多解释」更省事。")

	// -----------------------------------------------------------------
