package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000001"

type Account struct {
	ID           string     `json:"id"`
	FamilyID     string     `json:"family_id"`
	Name         string     `json:"name"`
	Type         string     `json:"type"`
	BalanceCents int64      `json:"balance_cents"`
	IsDefault    bool       `json:"is_default"`
	IsArchived   bool       `json:"is_archived"`
	ArchivedAt   *time.Time `json:"archived_at"`
	Version      int        `json:"version"`
	Deleted      bool       `json:"-"`
	seq          int64      `json:"-"`
}

type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

// ---------------------------------------------------------------------

type BizError struct {
	HTTPStatus int
	Code       int
	Message    string
	Hint       string
}

type ctxKey string

const keyFamily ctxKey = "family_id"

// ---------------------------------------------------------------------
// 内存 store：这里已经把 W38 六天的结论全部落进去了
// ---------------------------------------------------------------------

type Store struct {
	accs []*Account
	seq  int
	// 模拟 client_request_id 幂等（W41 展开，这里先占位）
	idem map[string]string
}

func newStore() *Store { return &Store{idem: map[string]string{}} }

func (s *Store) add(fam, name, typ string, bal int64) *Account {
	s.seq++
	a := &Account{
		ID:           fmt.Sprintf("acc-%03d", s.seq),
		FamilyID:     fam,
		Name:         name,
		Type:         typ,
		BalanceCents: bal,
		Version:      1,
		seq:          int64(s.seq),
	}
	s.accs = append(s.accs, a)
	return a
}

func (s *Store) find(id, fam string) *Account {
	for _, a := range s.accs {
		if a.ID == id && a.FamilyID == fam && !a.Deleted {
			return a
		}
	}
	return nil
}

// 部分唯一索引：每家庭至多一个 is_default（d3）
func (s *Store) hasDefault(fam string) bool {
	for _, a := range s.accs {
		if a.FamilyID == fam && a.IsDefault && !a.Deleted {
			return true
		}
	}
	return false
}

var errVio = &BizError{HTTPStatus: 409, Code: 23505, Message: "该家庭已有默认账户"}

// ---------------------------------------------------------------------
// Service 层：W38 的全部业务规则收在这里
// ---------------------------------------------------------------------

type Svc struct{ s *Store }

func (v *Svc) List(fam string, limit int, cursor string, includeArchived bool) ([]*Account, string) {
	items := make([]*Account, 0)
	for _, a := range v.s.accs {
		if a.FamilyID != fam || a.Deleted {
			continue
		}
		if !includeArchived && a.IsArchived {
			continue
		}
		items = append(items, a)
	}
	// 确定性排序：created_at 相同（我们用 seq 模拟）时靠 id 定序
	sort.Slice(items, func(i, j int) bool {
		if items[i].seq != items[j].seq {
			return items[i].seq < items[j].seq
		}
		return items[i].ID < items[j].ID
	})
	if cursor != "" {
		for i, a := range items {
			if a.ID == cursor {
				items = items[i+1:]
				break
			}
		}
	}
	var next string
	if len(items) > limit {
		next = items[limit-1].ID
		items = items[:limit]
	}
	return items, next
}

func (v *Svc) Create(fam, name, typ string, isDefault bool, crid string) (*Account, *BizError) {
	if v.s.idem[crid] != "" {
		return v.s.find(v.s.idem[crid], fam), nil // 幂等
	}
	if isDefault && v.s.hasDefault(fam) {
		return nil, errVio
	}
	a := v.s.add(fam, name, typ, 0)
	a.IsDefault = isDefault
	v.s.idem[crid] = a.ID
	return a, nil
}

func (v *Svc) Update(fam, id, name string, version int) (*Account, *BizError) {
	a := v.s.find(id, fam)
	if a == nil {
		return nil, &BizError{HTTPStatus: 404, Code: 3001, Message: "账户不存在"}
	}
	if a.Version != version {
		return nil, &BizError{
			HTTPStatus: 409, Code: 40901,
			Message: "数据已被他人修改，请刷新后重试",
			Hint:    fmt.Sprintf("服务端当前版本 = %d，你的请求基于版本 = %d", a.Version, version),
		}
	}
	a.Name = name
	a.Version++
	return a, nil
}

func (v *Svc) Archive(fam, id string, version int) (*Account, *BizError) {
	a := v.s.find(id, fam)
	if a == nil {
		return nil, &BizError{HTTPStatus: 404, Code: 3001, Message: "账户不存在"}
	}
	// 幂等检查在 version 检查之前（d5 情况 ⑦ 讲过为什么）
	if a.IsArchived {
		return a, nil
	}
	if a.Version != version {
		return nil, &BizError{
			HTTPStatus: 409, Code: 40901, Message: "数据已被他人修改，请刷新后重试",
			Hint: fmt.Sprintf("服务端当前版本 = %d，你的请求基于版本 = %d", a.Version, version),
		}
	}
	// ★ 今天的硬约束（d5）
	if a.Type != "credit_card" && a.BalanceCents != 0 {
		return nil, &BizError{
			HTTPStatus: 409, Code: 4001,
			Message: fmt.Sprintf("账户「%s」余额不为 %s，无法归档", a.Name, yuan(a.BalanceCents)),
			Hint:    "请先转账转出全部余额，或确认余额为 0 后再归档",
		}
	}
	a.IsArchived = true
	at := fixedNow
	a.ArchivedAt = &at
	a.IsDefault = false
	a.Version++
	return a, nil
}

func (v *Svc) Restore(fam, id string, version int) (*Account, *BizError) {
	a := v.s.find(id, fam)
	if a == nil {
		return nil, &BizError{HTTPStatus: 404, Code: 3001, Message: "账户不存在"}
	}
	if a.Version != version {
		return nil, &BizError{HTTPStatus: 409, Code: 40901, Message: "数据已被他人修改，请刷新后重试"}
	}
	a.IsArchived = false
	a.ArchivedAt = nil // ★ 必须置 nil，否则 d1 的 CHECK 会拒绝
	a.Version++
	return a, nil
}

