func (v *Svc) Handler() http.Handler {
	mux := http.NewServeMux()

	writeBiz := func(w http.ResponseWriter, e *BizError) {
		w.WriteHeader(e.HTTPStatus)
		json.NewEncoder(w).Encode(Envelope{
			Code: e.Code, Message: e.Message,
			Data:      map[string]string{"hint": e.Hint},
			RequestID: "req-" + fmt.Sprintf("%08x", 0x5eed0001),
		})
	}
	writeOK := func(w http.ResponseWriter, data any) {
		w.WriteHeader(200)
		json.NewEncoder(w).Encode(Envelope{Code: 0, Message: "ok", Data: data, RequestID: "req-demo"})
	}
	fam := func(r *http.Request) string { return r.Header.Get("X-Family-Id") }

	// ① GET /api/finance/accounts
	mux.HandleFunc("GET /api/finance/accounts", func(w http.ResponseWriter, r *http.Request) {
		limit := 20
		if s := r.URL.Query().Get("limit"); s != "" {
			fmt.Sscanf(s, "%d", &limit)
		}
		inc := r.URL.Query().Get("include_archived") == "true"
		items, next := v.List(fam(r), limit, r.URL.Query().Get("cursor"), inc)
		if items == nil {
			items = []*Account{}
		}
		writeOK(w, listResp{Items: items, NextCursor: next})
	})

	// ② POST /api/finance/accounts
	mux.HandleFunc("POST /api/finance/accounts", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Name      string `json:"name"`
			Type      string `json:"type"`
			IsDefault bool   `json:"is_default"`
			CRID      string `json:"client_request_id"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		a, e := v.Create(fam(r), req.Name, req.Type, req.IsDefault, req.CRID)
		if e != nil {
			writeBiz(w, e)
			return
		}
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(Envelope{Code: 0, Message: "ok", Data: a, RequestID: "req-demo"})
	})

	// ③ PATCH /api/finance/accounts/{id}
	mux.HandleFunc("PATCH /api/finance/accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Name    string `json:"name"`
			Version int    `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		a, e := v.Update(fam(r), r.PathValue("id"), req.Name, req.Version)
		if e != nil {
			writeBiz(w, e)
			return
		}
		writeOK(w, a)
	})

	// ④ POST /api/finance/accounts/{id}/archive
	mux.HandleFunc("POST /api/finance/accounts/{id}/archive", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version int `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		a, e := v.Archive(fam(r), r.PathValue("id"), req.Version)
		if e != nil {
			writeBiz(w, e)
			return
		}
		writeOK(w, a)
	})

	// ⑤ POST /api/finance/accounts/{id}/restore
	mux.HandleFunc("POST /api/finance/accounts/{id}/restore", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version int `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		a, e := v.Restore(fam(r), r.PathValue("id"), req.Version)
		if e != nil {
			writeBiz(w, e)
			return
		}
		writeOK(w, a)
	})

	return mux
}

