type res struct {
	Code int
	Body []byte
}

func do(srv *httptest.Server, method, path, fam, body string) res {
	var r *http.Request
	var err error
	if body == "" {
		r, err = http.NewRequest(method, srv.URL+path, nil)
	} else {
		r, err = http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	}
	if err != nil {
		panic(err)
	}
	r.Header.Set("X-Family-Id", fam)
	r.Header.Set("Content-Type", "application/json")
	resp, err := srv.Client().Do(r)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	buf := make([]byte, 8192)
	n, _ := resp.Body.Read(buf)
	return res{Code: resp.StatusCode, Body: buf[:n]}
}

func field(body []byte, key string) string {
	var m map[string]any
	if err := json.Unmarshal(body, &m); err != nil {
		return "?"
	}
	data, _ := m["data"].(map[string]any)
	if data == nil {
		// list 响应
		if d, ok := m["data"].(map[string]any); ok {
			_ = d
		}
		return "?"
	}
	v, ok := data[key]
	if !ok {
		return "?"
	}
	return fmt.Sprintf("%v", v)
}

func bizCode(body []byte) int {
	var m map[string]any
	json.Unmarshal(body, &m)
	c, _ := m["code"].(float64)
	return int(c)
}

