//
// 六个筛选条件（PRD 4.8）：
//   family_id（必带） / 时间窗 / account_id / category_id / type / is_private
//
// 今天真跑：250 条流水，5 个筛选维度，逐页翻完**不重不漏**，
// 并且演示「筛选条件变了，游标必须失效」这个必踩的坑。
//
// 本机没有 Postgres。查询用内存实现（语义照抄 Postgres 的
// WHERE + ORDER BY + LIMIT），SQL 手写并解释索引走向。
// =====================================================================

package main

import (
	"encoding/base64"
	"fmt"
	"sort"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000001"

type Txn struct {
	ID          string
	FamilyID    string
	AccountID   string
	ToAccountID string
	CategoryID  string
	Type        string
	AmountCents int64
	IsPrivate   bool
	MemberID    string
	OccurredAt  time.Time
	Deleted     bool
}

// ---------------------------------------------------------------------
// 筛选条件
// ---------------------------------------------------------------------

type Filter struct {
	FamilyID    string
	From        time.Time // 零值表示不限
	To          time.Time
	AccountID   string // 空表示不限
	CategoryID  string
	Type        string
	MemberID    string
	IncludeSelf bool   // 私密流水可见性（tech-plan 8.3 行级可见）
	SelfID      string // 当前成员
}

type Cursor struct {
	OccurredAt time.Time
	ID         string
}

// 游标编码：base64("<unix微秒>:<uuid>")，不透明，前端不解析
func (c Cursor) Encode() string {
	return base64.RawURLEncoding.EncodeToString(
		[]byte(fmt.Sprintf("%d:%s", c.OccurredAt.UnixMicro(), c.ID)))
}

func DecodeCursor(s string) (Cursor, bool) {
	raw, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return Cursor{}, false
	}
	parts := strings.SplitN(string(raw), ":", 2)
	if len(parts) != 2 {
		return Cursor{}, false
	}
	var us int64
	fmt.Sscanf(parts[0], "%d", &us)
	return Cursor{OccurredAt: time.UnixMicro(us).UTC(), ID: parts[1]}, true
}

func (f Filter) match(t *Txn) bool {
	if t.FamilyID != f.FamilyID {
		return false
	}
	if t.Deleted { // 软删永远不返回（d27 回收站是另一条路）
		return false
	}
	if !f.From.IsZero() && t.OccurredAt.Before(f.From) {
		return false
	}
	if !f.To.IsZero() && !t.OccurredAt.Before(f.To) {
		return false
	}
	if f.AccountID != "" && t.AccountID != f.AccountID && t.ToAccountID != f.AccountID {
		return false
	}
	if f.CategoryID != "" && t.CategoryID != f.CategoryID {
		return false
	}
	if f.Type != "" && t.Type != f.Type {
		return false
	}
	if f.MemberID != "" && t.MemberID != f.MemberID {
		return false
	}
	// 行级可见性：私密流水只有本人可见（tech-plan 8.3）
	if t.IsPrivate && t.MemberID != f.SelfID {
		return false
	}
	return true
}

// ORDER BY occurred_at DESC, id DESC + (occurred_at, id) < cursor
func (f Filter) query(all []*Txn, cur Cursor, limit int) []*Txn {
	var out []*Txn
	for _, t := range all {
		if !f.match(t) {
			continue
		}
		if !cur.OccurredAt.IsZero() {
			// 严格小于：游标本身那条不能重复
			if t.OccurredAt.After(cur.OccurredAt) {
				continue
			}
			if t.OccurredAt.Equal(cur.OccurredAt) && t.ID >= cur.ID {
				continue
			}
		}
		out = append(out, t)
	}
	// 稳定的全序：occurred_at 降序，id 降序
	// ★ 必须带 id：occurred_at 会重复（同一秒两笔），只按它排不是全序
	for i := 0; i < len(out); i++ {
		for j := i + 1; j < len(out); j++ {
			if out[j].OccurredAt.After(out[i].OccurredAt) ||
				(out[j].OccurredAt.Equal(out[i].OccurredAt) && out[j].ID > out[i].ID) {
				out[i], out[j] = out[j], out[i]
			}
		}
	}
	if len(out) > limit {
		out = out[:limit]
	}
	return out
}

