// =====================================================================
// W39 d12：收口 —— 流水 CRUD + W39 自查。
//
// W39 六天落下的东西，今天全部端到端跑一遍并断言：
//   d7  完整 DDL（DDL 是静态的，收口只验证约束规则在内存实现里被遵守）
//   d8  六个 type 的校验矩阵 + 余额影响
//   d9  转账 = 一笔（to_account_id）
//   d10 游标分页 + 多条件筛选
//   d11 occurred_at vs created_at
//
// 与 d6 一样用 httptest 起真 HTTP 服务、发真请求、断言真响应。
// 今天的重点是**跨天组合**：W38 的账户 + W39 的流水，
// 「建账户 → 记流水 → 余额变 → 查得到 → 改 → 撤销 → 余额回」一条链。
//
// W39 判据：
//   1. 流水 CRUD 五条接口跑通
//   2. 六个 type 的校验矩阵全部生效
//   3. 转账是一行，余额两侧都变，撤销后完全回滚
//   4. 列表游标分页 + 多条件筛选不重不漏
//   5. 补记流水落在正确的月份
// =====================================================================

package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const famB = "bbbbbbbb-0000-4000-8000-000000000001"

type Account struct {
	ID           string `json:"id"`
	FamilyID     string `json:"family_id"`
	Name         string `json:"name"`
	Type         string `json:"type"`
	BalanceCents int64  `json:"balance_cents"`
	IsDefault    bool   `json:"is_default"`
	IsArchived   bool   `json:"is_archived"`
	Version      int    `json:"version"`
	Deleted      bool   `json:"-"`
	seq          int    `json:"-"`
}

type Txn struct {
	ID          string    `json:"id"`
	FamilyID    string    `json:"family_id"`
	AccountID   string    `json:"account_id"`
	ToAccountID *string   `json:"to_account_id"`
	AmountCents int64     `json:"amount_cents"`
	Type        string    `json:"type"`
	CategoryID  *string   `json:"category_id"`
	MemberID    *string   `json:"member_id"`
	Note        *string   `json:"note"`
	OccurredAt  time.Time `json:"occurred_at"`
	CreatedAt   time.Time `json:"created_at"`
	CRID        string    `json:"-"`
	Version     int       `json:"version"`
	Deleted     bool      `json:"-"`
	seq         int       `json:"-"`
}

type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

type BizError struct {
	HTTPStatus int
	Code       int
	Message    string
}

// ---------------------------------------------------------------------
// Store：把 W38 + W39 六天的规则全部落进来
// ---------------------------------------------------------------------

type Store struct {
	accs []*Account
	txns []*Txn
	seq  int
	// 幂等：W41 d22/d23 才展开，这里先用 map 占位保证「同 crid 只写一笔」
	idem map[string]string
}

func newStore() *Store { return &Store{idem: map[string]string{}} }

func (s *Store) newAcc(fam, name, typ string, bal int64) *Account {
	s.seq++
	a := &Account{ID: fmt.Sprintf("acc-%03d", s.seq), FamilyID: fam, Name: name,
		Type: typ, BalanceCents: bal, Version: 1, seq: s.seq}
	s.accs = append(s.accs, a)
	return a
}

func (s *Store) findAcc(id, fam string) *Account {
	for _, a := range s.accs {
		if a.ID == id && a.FamilyID == fam && !a.Deleted {
			return a
		}
	}
	return nil
}

func (s *Store) newTxn(t *Txn) *Txn {
	s.seq++
	t.ID = fmt.Sprintf("txn-%04d", s.seq)
	t.Version = 1
	t.seq = s.seq
	s.txns = append(s.txns, t)
	return t
}

func (s *Store) findTxn(id, fam string) *Txn {
	for _, t := range s.txns {
		if t.ID == id && t.FamilyID == fam && !t.Deleted {
			return t
		}
	}
	return nil
}

// 校验矩阵（d8）
type rule struct {
	NeedTo      bool
	NeedCat     bool
	AllowTo     bool
	FromSign    int // 转出侧对余额的影响：-1 减、+1 加、0 不影响
	ToSign      int // 转入侧对余额的影响
	CountInStat bool
}

// ★ 方向必须显式写出来：income 是 +1，expense 是 -1。
// 只用 bool（AffectFrom）表达不了方向，会把 income 也写成减 ——
// 那正是 d8 讲的「用数学事实表达业务语义」的坑。
var rules = map[string]rule{
	"expense":       {NeedCat: true, FromSign: -1, CountInStat: true},
	"income":        {NeedCat: true, FromSign: +1, CountInStat: true},
	"transfer":      {NeedTo: true, AllowTo: true, FromSign: -1, ToSign: +1},
	"borrow_in":     {FromSign: +1},
	"lend_out":      {FromSign: -1},
	"reimbursement": {},
}

var errNotFound = &BizError{HTTPStatus: 404, Code: 3001, Message: "资源不存在"}
var errBadType = &BizError{HTTPStatus: 400, Code: 40001, Message: "type 不合法"}

func (e *BizError) Error() string { return fmt.Sprintf("%d %s", e.HTTPStatus, e.Message) }

func bad(msg string) *BizError {
	return &BizError{HTTPStatus: 400, Code: 40000, Message: msg}
}

// Create 流水：d8 校验矩阵 + d2 余额口径，全在这里
func (s *Store) Create(fam, crid, typ, accID string, toID *string, catID *string,
	amount int64, memberID *string, note *string, occ time.Time) (*Txn, *BizError) {

	// 幂等占位：同 crid 直接返回已有
	if id, ok := s.idem[crid]; ok {
		for _, t := range s.txns {
			if t.ID == id {
				return t, nil
			}
		}
	}

	r, ok := rules[typ]
	if !ok {
		return nil, errBadType
	}
	if amount <= 0 { // d7 的 CHECK (amount_cents > 0)
		return nil, bad("金额必须为正数（direction 由 type 决定，金额存绝对值）")
	}
	from := s.findAcc(accID, fam)
	if from == nil {
		return nil, errNotFound
	}
	if from.IsArchived {
		return nil, &BizError{HTTPStatus: 409, Code: 4002, Message: "账户已归档，不能记新流水"}
	}
	// 校验矩阵
	if r.NeedTo && toID == nil {
		return nil, bad("type=transfer 必须提供 to_account_id")
	}
	if !r.AllowTo && toID != nil {
		return nil, bad(fmt.Sprintf("type=%s 不允许 to_account_id", typ))
	}
	if r.NeedCat && catID == nil {
		return nil, bad(fmt.Sprintf("type=%s 必须提供 category_id", typ))
	}
	if !r.NeedCat && catID != nil {
		return nil, bad(fmt.Sprintf("type=%s 不允许 category_id（转账没有分类）", typ))
	}
	var to *Account
	if toID != nil {
		if *toID == accID {
			return nil, bad("转账的 to_account_id 不能等于 account_id（否则对账会双重计数）")
		}
		to = s.findAcc(*toID, fam)
		if to == nil {
			return nil, errNotFound
		}
		if to.IsArchived {
			return nil, &BizError{HTTPStatus: 409, Code: 4002, Message: "转入账户已归档"}
		}
	}
	// d11 校验：未来时间拒绝
	if occ.After(fixedNow.Add(5 * time.Minute)) {
		return nil, bad("记账时间不能晚于当前时间 5 分钟以上")
	}

	t := s.newTxn(&Txn{
		FamilyID: fam, AccountID: accID, ToAccountID: toID,
		AmountCents: amount, Type: typ, CategoryID: catID,
		MemberID: memberID, Note: note,
		OccurredAt: occ, CreatedAt: fixedNow, CRID: crid,
	})
	// d2 路线 B：原子改余额（方向由 type 决定，r.FromSign / r.ToSign）
	if r.FromSign != 0 {
		from.BalanceCents += int64(r.FromSign) * amount
		from.Version++
	}
	if r.ToSign != 0 && to != nil {
		to.BalanceCents += int64(r.ToSign) * amount
		to.Version++
	}
	s.idem[crid] = t.ID
	return t, nil
}

func (s *Store) Update(fam, id string, version int, note *string, occ *time.Time) (*Txn, *BizError) {
	t := s.findTxn(id, fam)
	if t == nil {
		return nil, errNotFound
	}
	// d8：A 组字段（钱/账户/类型）不能改，只能改 B/C/D 组
	// 改金额 = 冲正 + 重记（d25 展开），所以这里不提供
	if t.Version != version {
		return nil, &BizError{HTTPStatus: 409, Code: 40901, Message: "数据已被他人修改，请刷新后重试"}
	}
	if note != nil {
		t.Note = note
	}
	if occ != nil {
		if occ.After(fixedNow.Add(5 * time.Minute)) {
			return nil, bad("记账时间不能晚于当前时间 5 分钟以上")
		}
		t.OccurredAt = *occ
	}
	t.Version++
	return t, nil
}

func (s *Store) SoftDelete(fam, id string, version int, by string) *BizError {
	t := s.findTxn(id, fam)
	if t == nil {
		return errNotFound
	}
	if t.Version != version {
		return &BizError{HTTPStatus: 409, Code: 40901, Message: "数据已被他人修改，请刷新后重试"}
	}
	t.Deleted = true
	t.Version++
	// 余额回滚（d25 讲冲正）
	// 回滚 = 施加反向（不是「加回去」，因为方向可能是加也可能是减）
	r := rules[t.Type]
	from := s.findAcc(t.AccountID, fam)
	if r.FromSign != 0 && from != nil {
		from.BalanceCents -= int64(r.FromSign) * t.AmountCents
	}
	if r.ToSign != 0 && t.ToAccountID != nil {
		if to := s.findAcc(*t.ToAccountID, fam); to != nil {
			to.BalanceCents -= int64(r.ToSign) * t.AmountCents
		}
	}
	return nil
}

