// 列表：游标 + 多条件筛选（d10）
// ---------------------------------------------------------------------

type listQuery struct {
	From, To       time.Time
	AccountID      string
	CategoryID     string
	Type           string
	MemberID       string
	IncludeDeleted bool
	Limit          int
	Cursor         string
}

type listResp struct {
	Items      []*Txn `json:"items"`
	NextCursor string `json:"next_cursor"`
}

func (s *Store) List(fam, self string, q listQuery) (*listResp, *BizError) {
	limit := q.Limit
	if limit <= 0 || limit > 100 {
		limit = 20
	}
	var curOcc time.Time
	var curID string
	if q.Cursor != "" {
		raw, err := base64.RawURLEncoding.DecodeString(q.Cursor)
		if err != nil {
			return nil, &BizError{HTTPStatus: 400, Code: 40010, Message: "游标格式非法"}
		}
		parts := strings.SplitN(string(raw), ":", 2)
		if len(parts) != 2 {
			return nil, &BizError{HTTPStatus: 400, Code: 40010, Message: "游标格式非法"}
		}
		var us int64
		fmt.Sscanf(parts[0], "%d", &us)
		curOcc, curID = time.UnixMicro(us).UTC(), parts[1]
	}
	var out []*Txn
	for _, t := range s.txns {
		if t.FamilyID != fam {
			continue
		}
		if t.Deleted != q.IncludeDeleted {
			continue
		}
		if !q.From.IsZero() && t.OccurredAt.Before(q.From) {
			continue
		}
		if !q.To.IsZero() && !t.OccurredAt.Before(q.To) {
			continue
		}
		if q.AccountID != "" && t.AccountID != q.AccountID && (t.ToAccountID == nil || *t.ToAccountID != q.AccountID) {
			continue
		}
		if q.CategoryID != "" && (t.CategoryID == nil || *t.CategoryID != q.CategoryID) {
			continue
		}
		if q.Type != "" && t.Type != q.Type {
			continue
		}
		if q.MemberID != "" && (t.MemberID == nil || *t.MemberID != q.MemberID) {
			continue
		}
		if !curOcc.IsZero() {
			if t.OccurredAt.After(curOcc) {
				continue
			}
			if t.OccurredAt.Equal(curOcc) && t.ID >= curID {
				continue
			}
		}
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].OccurredAt.Equal(out[j].OccurredAt) {
			return out[i].OccurredAt.After(out[j].OccurredAt)
		}
		return out[i].ID > out[j].ID
	})
	resp := &listResp{Items: []*Txn{}}
	if len(out) > limit {
		last := out[limit-1]
		resp.NextCursor = base64.RawURLEncoding.EncodeToString(
			[]byte(fmt.Sprintf("%d:%s", last.OccurredAt.UnixMicro(), last.ID)))
		out = out[:limit]
	}
	resp.Items = out
	return resp, nil
}

