func (s *Store) Handler() http.Handler {
	mux := http.NewServeMux()
	fam := func(r *http.Request) string { return r.Header.Get("X-Family-Id") }
	self := func(r *http.Request) string { return r.Header.Get("X-Member-Id") }

	bad := func(w http.ResponseWriter, e *BizError) {
		w.WriteHeader(e.HTTPStatus)
		json.NewEncoder(w).Encode(Envelope{Code: e.Code, Message: e.Message, Data: nil, RequestID: "req-w39"})
	}
	ok := func(w http.ResponseWriter, code int, data any) {
		w.WriteHeader(code)
		json.NewEncoder(w).Encode(Envelope{Code: 0, Message: "ok", Data: data, RequestID: "req-w39"})
	}

	// ① POST /api/finance/transactions
	mux.HandleFunc("POST /api/finance/transactions", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			AccountID   string  `json:"account_id"`
			ToAccountID *string `json:"to_account_id"`
			AmountCents int64   `json:"amount_cents"`
			Type        string  `json:"type"`
			CategoryID  *string `json:"category_id"`
			MemberID    *string `json:"member_id"`
			Note        *string `json:"note"`
			OccurredAt  *string `json:"occurred_at"`
			CRID        string  `json:"client_request_id"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		occ := fixedNow
		if req.OccurredAt != nil {
			parsed, err := time.Parse(time.RFC3339, *req.OccurredAt)
			if err != nil {
				bad(w, &BizError{HTTPStatus: 400, Code: 40010, Message: "occurred_at 必须是 RFC3339"})
				return
			}
			occ = parsed.UTC()
		}
		t, e := s.Create(fam(r), req.CRID, req.Type, req.AccountID, req.ToAccountID,
			req.CategoryID, req.AmountCents, req.MemberID, req.Note, occ)
		if e != nil {
			bad(w, e)
			return
		}
		ok(w, 201, t)
	})

	// ② GET /api/finance/transactions
	mux.HandleFunc("GET /api/finance/transactions", func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query()
		lq := listQuery{AccountID: q.Get("account_id"), CategoryID: q.Get("category_id"),
			Type: q.Get("type"), MemberID: q.Get("member_id"), Cursor: q.Get("cursor"),
			IncludeDeleted: q.Get("deleted") == "true"}
		if s := q.Get("limit"); s != "" {
			fmt.Sscanf(s, "%d", &lq.Limit)
		}
		if v := q.Get("from"); v != "" {
			lq.From, _ = time.Parse("2006-01-02", v)
		}
		if v := q.Get("to"); v != "" {
			lq.To, _ = time.Parse("2006-01-02", v)
		}
		resp, e := s.List(fam(r), self(r), lq)
		if e != nil {
			bad(w, e)
			return
		}
		ok(w, 200, resp)
	})

	// ③ GET /api/finance/transactions/{id}
	mux.HandleFunc("GET /api/finance/transactions/{id}", func(w http.ResponseWriter, r *http.Request) {
		t := s.findTxn(r.PathValue("id"), fam(r))
		if t == nil {
			bad(w, errNotFound)
			return
		}
		ok(w, 200, t)
	})

	// ④ PATCH /api/finance/transactions/{id}
	mux.HandleFunc("PATCH /api/finance/transactions/{id}", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version    int     `json:"version"`
			Note       *string `json:"note"`
			OccurredAt *string `json:"occurred_at"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		var occ *time.Time
		if req.OccurredAt != nil {
			parsed, err := time.Parse(time.RFC3339, *req.OccurredAt)
			if err != nil {
				bad(w, &BizError{HTTPStatus: 400, Code: 40010, Message: "occurred_at 必须是 RFC3339"})
				return
			}
			u := parsed.UTC()
			occ = &u
		}
		t, e := s.Update(fam(r), r.PathValue("id"), req.Version, req.Note, occ)
		if e != nil {
			bad(w, e)
			return
		}
		ok(w, 200, t)
	})

	// ⑤ DELETE /api/finance/transactions/{id}（软删）
	mux.HandleFunc("DELETE /api/finance/transactions/{id}", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version int `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		if e := s.SoftDelete(fam(r), r.PathValue("id"), req.Version, self(r)); e != nil {
			bad(w, e)
			return
		}
		ok(w, 200, map[string]any{"id": r.PathValue("id"), "deleted": true})
	})

	// 辅助：查账户余额（收口断言用）
	mux.HandleFunc("GET /api/finance/accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
		a := s.findAcc(r.PathValue("id"), fam(r))
		if a == nil {
			bad(w, errNotFound)
			return
		}
		ok(w, 200, a)
	})

	return mux
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

type res struct {
	Code int
	Body []byte
}

func do(srv *httptest.Server, method, path, fam, body string) res {
	var r *http.Request
	var err error
	if body == "" {
		r, err = http.NewRequest(method, srv.URL+path, nil)
	} else {
		r, err = http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	}
	if err != nil {
		panic(err)
	}
	r.Header.Set("X-Family-Id", fam)
	r.Header.Set("X-Member-Id", "mem-mom")
	resp, err := srv.Client().Do(r)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	buf := make([]byte, 16384)
	n, _ := resp.Body.Read(buf)
	return res{Code: resp.StatusCode, Body: buf[:n]}
}

func codeOf(body []byte) int {
	var m map[string]any
	json.Unmarshal(body, &m)
	c, _ := m["code"].(float64)
	return int(c)
}

func msgOf(body []byte) string {
	var m map[string]any
	json.Unmarshal(body, &m)
	s, _ := m["message"].(string)
	return s
}

func idOf(body []byte) string {
	var m struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	json.Unmarshal(body, &m)
	return m.Data.ID
}

func balOf(s *Store, id string) int64 {
	for _, a := range s.accs {
		if a.ID == id {
			return a.BalanceCents
		}
	}
	return 0
}

