// =====================================================================
// W40 d15：转账的实现 —— BEGIN → 改A → 改B → COMMIT。
//
// 今天把 d14 的清单变成真正的代码。四层架构（S2 学的）：
//   handler  → 解析、鉴权、错误翻译
//   service  → 业务编排、**事务边界在这里**
//   repo     → 一条 SQL 一个方法，只管执行
//
// 关键点：**事务在 service 层开，repo 方法接收 tx 参数**。
// 第 5 节真跑完整链路（httptest + 真 HTTP），并验证：
//   成功路径：4 条写全部落盘
//   失败路径：任何一条失败，4 条写全部回滚
//
// 第 6 节用 GORM DryRun 打印**真实**的事务 SQL 顺序。
//
// 本机没有 Postgres。repo 层内存实现，SQL 用 DryRun 真实生成。
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// =====================================================================
// Repo 层：一条 SQL 一个方法，只管执行，不管事务
// =====================================================================

type Account struct {
	ID           string
	FamilyID     string
	Name         string
	Type         string
	BalanceCents int64
	IsArchived   bool
	Version      int
}

type Txn struct {
	ID          string
	FamilyID    string
	AccountID   string
	ToAccountID string
	AmountCents int64
	Type        string
	CRID        string
	Version     int
	Committed   bool
}

type Outbox struct {
	ID      string
	Topic   string
	Payload string
}

type IdemRow struct {
	FamilyID  string
	CRID      string
	TxnID     string
	CreatedAt time.Time
}

type DB struct {
	Accounts map[string]*Account
	Txns     []*Txn
	Outbox   []*Outbox
	Idem     map[string]*IdemRow // key = familyID|crid
	seq      int
	// 事务状态
	inTx    bool
	bufAcc  map[string]*Account
	bufTxn  []*Txn
	bufOut  []*Outbox
	bufIdem map[string]*IdemRow
	// 故障注入
	failOn         string
	Trace          []string
	CommittedCount int
}

func newDB() *DB {
	return &DB{Accounts: map[string]*Account{}, Idem: map[string]*IdemRow{}}
}

// balanceOf：★ 必须通过 id 回查，不能直接用 seed 返回的那个指针
//
// 原因：事务里改余额时，代码做的是「复制一份、改、放进缓冲区」（见 DecBalance），
// COMMIT 时才把新对象写回 d.Accounts[id]。
// 所以 seed 返回的**旧指针**在事务提交后仍然指向旧值 ——
// 打印它会看到「转账前」的余额，看起来像没扣款，其实数据是对的。
// 这正是 Go 的「struct 是值语义、指针是引用语义」在事务实现里的体现：
// 事务靠「换对象」实现隔离，而不是「原地改」。
func (d *DB) balanceOf(id string) int64 {
	if a, ok := d.Accounts[id]; ok {
		return a.BalanceCents
	}
	return 0
}

func (d *DB) seed(id, name, typ string, bal int64) *Account {
	a := &Account{ID: id, FamilyID: famA, Name: name, Type: typ, BalanceCents: bal, Version: 1}
	d.Accounts[id] = a
	return a
}

// ---- 事务控制（只有 service 层调）----

func (d *DB) Begin() {
	d.inTx = true
	d.bufAcc = map[string]*Account{}
	d.bufTxn = nil
	d.bufOut = nil
	d.bufIdem = map[string]*IdemRow{}
	d.Trace = append(d.Trace, "BEGIN")
}

func (d *DB) Commit() {
	for k, a := range d.bufAcc {
		d.Accounts[k] = a
	}
	d.Txns = append(d.Txns, d.bufTxn...)
	d.Outbox = append(d.Outbox, d.bufOut...)
	for k, v := range d.bufIdem {
		d.Idem[k] = v
	}
	d.CommittedCount++
	d.bufAcc, d.bufTxn, d.bufOut, d.bufIdem = map[string]*Account{}, nil, nil, map[string]*IdemRow{}
	d.inTx = false
	d.Trace = append(d.Trace, "COMMIT")
}

func (d *DB) Rollback() {
	d.bufAcc, d.bufTxn, d.bufOut, d.bufIdem = map[string]*Account{}, nil, nil, map[string]*IdemRow{}
	d.inTx = false
	d.Trace = append(d.Trace, "ROLLBACK")
}

// ---- Repo 方法：每个都只做一件事 ----

// (1) 查账户（**读**，可以在事务外）
func (r *DB) GetAccount(fam, id string) *Account {
	a, ok := r.Accounts[id]
	if !ok || a.FamilyID != fam {
		return nil
	}
	return a
}

// (2) 查幂等记录（**读**，在事务外）
func (r *DB) GetIdem(fam, crid string) *IdemRow {
	return r.Idem[fam+"|"+crid]
}

// (3) 原子扣减（**写**，事务内）
//
//	★ WHERE 里带 balance_cents >= amount：这是「防透支」的第二道防线
func (r *DB) DecBalance(fam, id string, amount int64) error {
	if r.failOn == "dec:"+id {
		return fmt.Errorf("账户 %s 扣减失败：余额不足（CHECK / WHERE 条件不满足）", id)
	}
	a, ok := r.Accounts[id]
	if !ok || a.FamilyID != fam {
		return fmt.Errorf("账户 %s 不存在", id)
	}
	if a.IsArchived {
		return fmt.Errorf("账户「%s」已归档", a.Name)
	}
	if a.Type != "credit_card" && a.BalanceCents < amount {
		return fmt.Errorf("账户「%s」余额不足：%d < %d", a.Name, a.BalanceCents, amount)
	}
	if r.inTx {
		cp := *a
		a = &cp
		r.bufAcc[id] = a
	}
	a.BalanceCents -= amount
	a.Version++
	r.Trace = append(r.Trace, "UPDATE account -"+fmt.Sprint(amount)+" id="+id)
	return nil
}

// (4) 原子增加（**写**，事务内）
func (r *DB) IncBalance(fam, id string, amount int64) error {
	if r.failOn == "inc:"+id {
		return fmt.Errorf("账户 %s 入账失败：连接中断", id)
	}
	a, ok := r.Accounts[id]
	if !ok || a.FamilyID != fam {
		return fmt.Errorf("账户 %s 不存在", id)
	}
	if a.IsArchived {
		return fmt.Errorf("转入账户「%s」已归档", a.Name)
	}
	if r.inTx {
		cp := *a
		a = &cp
		r.bufAcc[id] = a
	}
	a.BalanceCents += amount
	a.Version++
	r.Trace = append(r.Trace, "UPDATE account +"+fmt.Sprint(amount)+" id="+id)
	return nil
}

// (5) 插流水（**写**，事务内）
func (r *DB) InsertTxn(fam, from, to, typ, crid string, amount int64) (string, error) {
	if r.failOn == "txn" {
		return "", fmt.Errorf("INSERT finance_transaction 失败：唯一键冲突 / 磁盘满")
	}
	r.seq++
	id := fmt.Sprintf("txn-%04d", r.seq)
	t := &Txn{ID: id, FamilyID: fam, AccountID: from, ToAccountID: to,
		AmountCents: amount, Type: typ, CRID: crid, Version: 1}
	if r.inTx {
		r.bufTxn = append(r.bufTxn, t)
	} else {
		r.Txns = append(r.Txns, t)
	}
	r.Trace = append(r.Trace, "INSERT txn id="+id)
	return id, nil
}

// (6) 写幂等记录（**写**，事务内）
func (r *DB) PutIdem(fam, crid, txnID string) error {
	if r.failOn == "idem" {
		return fmt.Errorf("INSERT 幂等记录失败")
	}
	row := &IdemRow{FamilyID: fam, CRID: crid, TxnID: txnID, CreatedAt: fixedNow}
	if r.inTx {
		r.bufIdem[fam+"|"+crid] = row
	} else {
		r.Idem[fam+"|"+crid] = row
	}
	r.Trace = append(r.Trace, "INSERT idem crid="+crid)
	return nil
}

// (7) 写 outbox（**写**，事务内）
func (r *DB) PutOutbox(topic, payload string) {
	o := &Outbox{ID: fmt.Sprintf("obx-%d", len(r.Outbox)+len(r.bufOut)+1), Topic: topic, Payload: payload}
	if r.inTx {
		r.bufOut = append(r.bufOut, o)
	} else {
		r.Outbox = append(r.Outbox, o)
	}
	r.Trace = append(r.Trace, "INSERT outbox topic="+topic)
}

// =====================================================================
// Service 层：★ 事务边界在这里
// =====================================================================

type BizError struct {
	HTTPStatus int
	Code       int
	Message    string
}

type TransferReq struct {
	AccountID   string
	ToAccountID string
	AmountCents int64
	CRID        string
	MemberID    string
}

type Svc struct{ db *DB }

// Transfer 是转账的唯一入口。事务只包 4 条写。
func (s *Svc) Transfer(req TransferReq) (*Txn, *BizError) {
	// ---- 事务外：读与校验（d14：目的是早失败，不是保证正确）----
	if req.AmountCents <= 0 {
		return nil, &BizError{HTTPStatus: 400, Code: 40000, Message: "转账金额必须为正数"}
	}
	if req.AccountID == req.ToAccountID {
		return nil, &BizError{HTTPStatus: 400, Code: 40000, Message: "转出与转入账户不能相同"}
	}
	// 幂等：已处理过就直接返回原结果（不重跑副作用）
	if row := s.db.GetIdem(famA, req.CRID); row != nil {
		for _, t := range s.db.Txns {
			if t.ID == row.TxnID {
				return t, nil
			}
		}
	}
	from := s.db.GetAccount(famA, req.AccountID)
	if from == nil {
		return nil, &BizError{HTTPStatus: 404, Code: 3001, Message: "转出账户不存在"}
	}
	to := s.db.GetAccount(famA, req.ToAccountID)
	if to == nil {
		return nil, &BizError{HTTPStatus: 404, Code: 3001, Message: "转入账户不存在"}
	}
	if from.IsArchived {
		return nil, &BizError{HTTPStatus: 409, Code: 4002, Message: "转出账户已归档"}
	}
	if to.IsArchived {
		return nil, &BizError{HTTPStatus: 409, Code: 4002, Message: "转入账户已归档"}
	}
	// 余额预检（★ 只是为了早失败；真正的防线在 DecBalance 的 WHERE 里）
	if from.Type != "credit_card" && from.BalanceCents < req.AmountCents {
		return nil, &BizError{HTTPStatus: 409, Code: 4001,
			Message: "转出账户余额不足"}
	}

	// ---- 事务：只包这 4 条写 ----
	var out *Txn
	err := s.runTx(func() error {
		// ① 扣转出
		if err := s.db.DecBalance(famA, req.AccountID, req.AmountCents); err != nil {
			return err
		}
		// ② 加转入
		if err := s.db.IncBalance(famA, req.ToAccountID, req.AmountCents); err != nil {
			return err
		}
		// ③ 插流水（转账 = 一笔，d9）
		txnID, err := s.db.InsertTxn(famA, req.AccountID, req.ToAccountID, "transfer", req.CRID, req.AmountCents)
		if err != nil {
			return err
		}
		for _, t := range s.db.bufTxn {
			if t.ID == txnID {
				out = t
			}
		}
		// ④ 写幂等记录（d13 第 4 行：漏了会重复扣款）
		if err := s.db.PutIdem(famA, req.CRID, txnID); err != nil {
			return err
		}
		// ⑤ outbox（d14：事件在同一个事务里登记，提交后由发布器发）
		s.db.PutOutbox("finance.transaction.created",
			fmt.Sprintf(`{"txn_id":%q,"type":"transfer","amount_cents":%d}`, txnID, req.AmountCents))
		return nil
	})
	if err != nil {
		// 事务内的任何错误 → 全部回滚，**一个字节都不落**
		return nil, &BizError{HTTPStatus: 500, Code: 50000, Message: "转账失败：" + err.Error()}
	}
	return out, nil
}

func (s *Svc) runTx(fn func() error) error {
	s.db.Begin()
	defer s.db.Rollback() // ★ 幂等：Commit 成功后 Rollback 返回 ErrTxDone，无害
	if err := fn(); err != nil {
		return err
	}
	s.db.Commit()
	return nil
}

// =====================================================================

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

type res struct {
	Code int
	Body []byte
}

func do(srv *httptest.Server, method, path, body string) res {
	r, _ := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	r.Header.Set("X-Family-Id", famA)
	resp, err := srv.Client().Do(r)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	buf := make([]byte, 8192)
	n, _ := resp.Body.Read(buf)
	return res{Code: resp.StatusCode, Body: buf[:n]}
}

func codeOf(b []byte) int {
	var m map[string]any
	json.Unmarshal(b, &m)
	c, _ := m["code"].(float64)
	return int(c)
}

