	fmt.Println("    }")
	fmt.Println("    from, err := s.repo.GetAccount(ctx, req.AccountID)")
	fmt.Println("    if err != nil { return nil, ErrNotFound }")
	fmt.Println("    if from.IsArchived { return nil, ErrArchived }")
	fmt.Println("    // 余额预检只是优化，真正的防线在下面的 DecBalance")
	fmt.Println("")
	fmt.Println("    // ───── 事务内：4 条写 + 1 条 outbox ─────")
	fmt.Println("    err = s.db.Transaction(func(tx *gorm.DB) error {")
	fmt.Println("        if err := s.repo.DecBalance(tx, from, n); err != nil { return err }")
	fmt.Println("        if err := s.repo.IncBalance(tx, to,   n); err != nil { return err }")
	fmt.Println("        txn, err := s.repo.InsertTxn(tx, ...)   // 转账 = 一笔")
	fmt.Println("        if err != nil { return err }")
	fmt.Println("        if err := s.repo.PutIdem(tx, req.CRID, txn.ID); err != nil { return err }")
	fmt.Println("        s.repo.PutOutbox(tx, ...)   // 事件登记")
	fmt.Println("        return nil")
	fmt.Println("    })")
	fmt.Println("    if err != nil { return nil, err }   // 已回滚")
	fmt.Println("")
	fmt.Println("    // ───── 事务外：发布事件（可能失败，由 outbox 补）─────")
	fmt.Println("    go s.publisher.Flush(ctx)")
	fmt.Println("    return txn, nil")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 注意 repo 方法的第一个参数是 `tx` 而不是隐式取 db。")
	fmt.Println("  传错成 s.db（外层连接）是最隐蔽的事务 bug：代码看着在事务里，")
	fmt.Println("  实际那条 UPDATE 在事务外执行，事务回滚了它却留下了。")
	fmt.Println("  而且**它不会报错**。")

