	fmt.Println("        \"version\":       gorm.Expr(\"version + ?\", 1),")
	fmt.Println("    })")
	fmt.Println("if res.Error != nil { return res.Error }")
	fmt.Println("if res.RowsAffected == 0 { return ErrInsufficientBalance }  // ★ 不是靠 Error")
