// W40 d16：★ 转账失败回滚 —— 中途出错怎么保证两个账户都不变。
//
// 这是 W40 必跑的演示。d13 证明了「没有事务会丢钱」，
// 今天要把「有事务」这件事做得**可验证**，而不是「相信它会回滚」。
//
// 判据（learning-plan S10）：转账中途失败，两个账户余额必须都不变。
//
// 今天的实验设计：把「事务」实现成一个**可观测的对象**，
// 逐条打印每个时刻的状态（Trace + 快照），
// 然后注入 5 个不同位置的故障，断言每一个都满足「两个账户都不变」。
//
// 特别处理 d15 发现的 Go 陷阱：事务靠「复制对象」实现隔离，
// 所以验证必须**通过 id 回查**，不能拿旧指针看值（第 7 节展开）。
//
// 本机没有 Postgres。事务语义内存模拟，逐条 Trace。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// =====================================================================
// 事务：把「快照 / 暂存 / 提交 / 回滚」都显式化，便于观测
// =====================================================================

type Account struct {
	ID           string
	Name         string
	BalanceCents int64
	Version      int
	IsArchived   bool
}

type Txn struct {
	ID        string
	Type      string
	From      string
	To        string
	Amount    int64
	CRID      string
	Committed bool
}

type IdemRow struct {
	CRID  string
	TxnID string
}

type DB struct {
	Accounts map[string]*Account
	Txns     []*Txn
	Idem     map[string]string
	Outbox   int

	// 事务状态
	//   snapshot：BEGIN 时的**原始副本**，回滚时用它恢复，全程不被修改
	//   staged：本次事务的**工作副本**，改动都落在这里，COMMIT 时才写回
	//   ★ 两者必须分开。如果把改动同步回 snapshot，回滚就会「恢复成改后的值」
	//     —— 这是 d16 第一版真实踩到的 bug（第 3 节展示的就是修好之后的断言）
	inTx        bool
	snapshot    map[string]*Account
	staged      map[string]*Account
	newTx       []*Txn
	newIdem     map[string]string
	idemSaved   map[string]string
	outboxSaved int

	Trace  []string
	failAt string
	step   int
}

func newDB() *DB {
	return &DB{Accounts: map[string]*Account{}, Idem: map[string]string{}}
}

func (d *DB) seed(id, name string, bal int64) *Account {
	a := &Account{ID: id, Name: name, BalanceCents: bal, Version: 1}
	d.Accounts[id] = a
	return a
}

// ★ 唯一正确的读法：按 id 回查
func (d *DB) bal(id string) int64 { return d.Accounts[id].BalanceCents }

func (d *DB) Begin() {
	d.inTx = true
	d.step = 0
	d.snapshot = map[string]*Account{}
	d.staged = map[string]*Account{}
	d.newTx = nil
	d.newIdem = map[string]string{}
	d.idemSaved = map[string]string{}
	for id, a := range d.Accounts {
		snap := *a // 原始副本：回滚用，**不再修改**
		work := *a // 工作副本：本事务的改动
		d.snapshot[id] = &snap
		d.staged[id] = &work
	}
	d.idemSaved = map[string]string{}
	for k, v := range d.Idem {
		d.idemSaved[k] = v
	}
	d.outboxSaved = d.Outbox
	d.Trace = append(d.Trace, "BEGIN")
}

func (d *DB) Commit() {
	// 把工作副本写回真实存储
	for id, a := range d.staged {
		d.Accounts[id] = a
	}
	d.Txns = append(d.Txns, d.newTx...)
	for k, v := range d.newIdem {
		d.Idem[k] = v
	}
	d.inTx = false
	d.snapshot, d.staged = map[string]*Account{}, map[string]*Account{}
	d.newIdem, d.idemSaved = map[string]string{}, map[string]string{}
	d.newTx = nil
	d.Trace = append(d.Trace, "COMMIT  ← 此刻数据才真正落盘")
}

func (d *DB) Rollback() {
	if !d.inTx {
		d.Trace = append(d.Trace, "ROLLBACK（空操作：事务已结束）")
		return
	}
	// 恢复：真实存储本来就**没被改过**（改动都在 staged 里），
	// 所以回滚只要丢弃 staged 即可。写成显式恢复 snapshot 是为了
	// 「万一某些路径原地改了 Accounts，也能救回来」—— 真实数据库
	// 就是靠 WAL 做到这一点的。
	for id, a := range d.snapshot {
		d.Accounts[id] = a
	}
	d.Idem = map[string]string{}
	for k, v := range d.idemSaved {
		d.Idem[k] = v
	}
	d.Outbox = d.outboxSaved
	d.newTx = nil
	d.newIdem = map[string]string{}
	d.inTx = false
	d.Trace = append(d.Trace, fmt.Sprintf("ROLLBACK  ← 丢弃工作副本，恢复 %d 个账户的原始值", len(d.snapshot)))
}

// --- 四条写（repo 层）---

// ① 扣转出：先改副本，不动真实存储
func (d *DB) decBalance(id string, amount int64) error {
	d.step++
	d.Trace = append(d.Trace, fmt.Sprintf("  ① UPDATE 扣减 %s -%d", id, amount))
	if d.failAt == fmt.Sprintf("step%d", d.step) {
		return fmt.Errorf("SQLSTATE 23514: check_violation（余额不能为负）")
	}
	// 读工作副本（能看到本事务前几步的结果），改它
	cur := d.staged[id]
	if cur == nil {
		cp := *d.snapshot[id]
		cur = &cp
		d.staged[id] = cur
	}
	cur.BalanceCents -= amount
	cur.Version++
	// ★ 绝不碰 d.snapshot —— 它是回滚的唯一依据
	return nil
}

// ② 加转入
func (d *DB) incBalance(id string, amount int64) error {
	d.step++
	d.Trace = append(d.Trace, fmt.Sprintf("  ② UPDATE 入账 %s +%d", id, amount))
	if d.failAt == fmt.Sprintf("step%d", d.step) {
		return fmt.Errorf("SQLSTATE 40001: serialization_failure")
	}
	cur := d.staged[id]
	if cur == nil {
		cp := *d.snapshot[id]
		cur = &cp
		d.staged[id] = cur
	}
	cur.BalanceCents += amount
	cur.Version++
	// ★ 绝不碰 d.snapshot
	return nil
}

// ③ 插流水
func (d *DB) insertTxn(from, to, crid string, amount int64) (string, error) {
	d.step++
	d.Trace = append(d.Trace, fmt.Sprintf("  ③ INSERT 流水 from=%s to=%s", from, to))
	if d.failAt == fmt.Sprintf("step%d", d.step) {
		return "", fmt.Errorf("SQLSTATE 23505: duplicate key value（幂等键已被占用）")
	}
	t := &Txn{ID: fmt.Sprintf("txn-%04d", len(d.Txns)+len(d.newTx)+1),
		Type: "transfer", From: from, To: to, Amount: amount, CRID: crid, Committed: true}
	d.newTx = append(d.newTx, t)
	return t.ID, nil
}

// ④ 写幂等
func (d *DB) putIdem(crid, txnID string) error {
	d.step++
	d.Trace = append(d.Trace, fmt.Sprintf("  ④ INSERT 幂等记录 crid=%s", crid))
	if d.failAt == fmt.Sprintf("step%d", d.step) {
		return fmt.Errorf("连接中断：写入幂等记录失败")
	}
	d.newIdem[crid] = txnID
	return nil
}

// ⑤ outbox
func (d *DB) putOutbox(txnID string) {
	d.Trace = append(d.Trace, fmt.Sprintf("  ⑤ INSERT outbox txn=%s", txnID))
	d.Outbox++
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

type outcome struct {
	FailAt     string
	Label      string
	BankBefore int64
	AliBefore  int64
	BankAfter  int64
	AliAfter   int64
	NTxn       int
	NIdem      int
	NOutbox    int
	ErrMsg     string
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 实验设计：让「回滚」变成可观测的事实，而不是信念")
	// -----------------------------------------------------------------
	fmt.Println("今天不接受「事务应该会回滚」这种说法，要**逐条打印 + 断言**。")
	fmt.Println()
	fmt.Println("实现上做了三件事：")
	fmt.Println("  ① BEGIN 时给每一行做**快照**（copy 一份）")
	fmt.Println("  ② 所有写在**副本**上改（staged）")
	fmt.Println("  ③ COMMIT 时把副本写回；ROLLBACK 时把快照写回")
	fmt.Println()
	fmt.Println("这正是真实数据库的简化版：")
	fmt.Println("  Postgres 用 WAL + buffer，MVCC 靠版本链；")
	fmt.Println("  效果一样 —— **COMMIT 之前，别的会话看不到你的改动**。")
	fmt.Println()
	fmt.Println("★ 每一步之后都能读出当前值，这就是「可验证」的含义。")

	// -----------------------------------------------------------------
	hdr("2. 基线：成功路径（先证明正常时它是通的）")
	// -----------------------------------------------------------------
	db := newDB()
	bank := db.seed("acc-bank", "招行储蓄卡", 1000000)
	ali := db.seed("acc-ali", "支付宝", 50000)

	fmt.Printf("  转账前：招行 %s，支付宝 %s，流水 %d，幂等 %d，outbox %d\n",
		yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)), len(db.Txns), len(db.Idem), db.Outbox)
	fmt.Println()
	fmt.Println("  执行过程（每一步后读余额）：")
	fmt.Println("    BEGIN")
	db.Trace = nil
	db.step = 0
	// 手动跑一遍并每步打印
	db.inTx = true
	db.snapshot = map[string]*Account{}
	db.staged = map[string]*Account{}
	for id, a := range db.Accounts {
		snap := *a
		work := *a
		db.snapshot[id] = &snap
		db.staged[id] = &work
	}
	db.newIdem = map[string]string{}
	db.idemSaved = map[string]string{}
	db.newTx = nil
	db.outboxSaved = 0

	// 步骤 1 前：打印
	fmt.Printf("    (未开始)                                        招行=%-10s 支付宝=%s\n", yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	db.decBalance(bank.ID, 300000)
	fmt.Printf("    ① 扣减招行 -3000                                招行=%-10s 支付宝=%s\n", yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	fmt.Println("       ↑ 注意：招行还是 10000.00！改动在**副本**上，真实存储没动。")
	db.incBalance(ali.ID, 300000)
	fmt.Printf("    ② 入账支付宝 +3000                              招行=%-10s 支付宝=%s\n", yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	fmt.Println("       ↑ 支付宝也还没变。")
	id, _ := db.insertTxn(bank.ID, ali.ID, "crid-ok", 300000)
	fmt.Printf("    ③ 插流水 %s                        招行=%-10s 支付宝=%s\n", id, yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	db.putIdem("crid-ok", id)
	fmt.Printf("    ④ 写幂等记录                                    招行=%-10s 支付宝=%s\n", yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	db.putOutbox(id)
	// COMMIT
	for k, a := range db.staged {
		db.Accounts[k] = a
	}
	db.Txns = append(db.Txns, db.newTx...)
	for k, v := range db.newIdem {
		db.Idem[k] = v
	}
	db.inTx = false
	fmt.Println("    COMMIT")
	fmt.Printf("    (提交后)                                        招行=%-10s 支付宝=%s\n", yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)))
	fmt.Println("       ↑ 此刻两个余额才真的变了。")
	fmt.Println()
	fmt.Printf("  最终：招行 %s，支付宝 %s，流水 %d，幂等 %d，outbox %d\n",
		yuan(db.bal(bank.ID)), yuan(db.bal(ali.ID)), len(db.Txns), len(db.Idem), db.Outbox)
	fmt.Println("  ✅ 基线通过：成功时 4 条写全部生效。")

	// -----------------------------------------------------------------
	hdr("3. ★ 注入故障：四个位置，逐个验证两个账户都不变")
	// -----------------------------------------------------------------
	fmt.Println("每个场景都从完全相同的初始状态开始（招行 10000，支付宝 500）。")
	fmt.Println()

	fails := []struct {
		FailAt string
		Label  string
		Why    string
	}{
		{"step2", "② 入账时失败", "转账中途最常见的失败（账户归档/连接中断/序列化失败）"},
		{"step3", "③ 插流水时失败", "唯一键冲突 / 磁盘满 —— 此时两个余额已经改过了"},
		{"step4", "④ 写幂等时失败", "d13 强调过的位置：漏了会重复扣款"},
		{"step1", "① 扣减时就失败", "余额不足 —— 此时还没改任何东西"},
	}

	var results []outcome
	for _, f := range fails {
		d2 := newDB()
		bk := d2.seed("acc-bank", "招行储蓄卡", 1000000)
		al := d2.seed("acc-ali", "支付宝", 50000)
		beforeBank, beforeAli := d2.bal(bk.ID), d2.bal(al.ID)
		d2.failAt = f.FailAt

		// 跑事务
		d2.Begin()
		var err error
		var txnID string
		if err = d2.decBalance(bk.ID, 300000); err == nil {
			if err = d2.incBalance(al.ID, 300000); err == nil {
				if txnID, err = d2.insertTxn(bk.ID, al.ID, "crid-f", 300000); err == nil {
					if err = d2.putIdem("crid-f", txnID); err == nil {
						d2.putOutbox(txnID)
					}
				}
			}
		}
		if err != nil {
			d2.Rollback()
		} else {
			d2.Commit()
		}

		o := outcome{
			FailAt: f.FailAt, Label: f.Label,
			BankBefore: beforeBank, AliBefore: beforeAli,
			BankAfter: d2.bal(bk.ID), AliAfter: d2.bal(al.ID),
			NTxn: len(d2.Txns), NIdem: len(d2.Idem), NOutbox: d2.Outbox,
		}
		if err != nil {
			o.ErrMsg = err.Error()
		}
		results = append(results, o)

		fmt.Printf("  ── 场景 %s ──\n", f.FailAt)
		fmt.Println("  " + strings.Repeat("-", 72))
		fmt.Printf("  原因：%s\n", f.Why)
		fmt.Println("  执行序列：")
		for _, t := range d2.Trace {
			fmt.Printf("  %s\n", t)
		}
		fmt.Println()
		okBank := o.BankAfter == o.BankBefore
		okAli := o.AliAfter == o.AliBefore
		okRest := o.NTxn == 0 && o.NIdem == 0 && o.NOutbox == 0
		fmt.Printf("  招行   %s → %s  %s\n", yuan(o.BankBefore), yuan(o.BankAfter),
			map[bool]string{true: "✅ 未变", false: "❌ 变了"}[okBank])
		fmt.Printf("  支付宝 %s → %s  %s\n", yuan(o.AliBefore), yuan(o.AliAfter),
			map[bool]string{true: "✅ 未变", false: "❌ 变了"}[okAli])
		fmt.Printf("  流水 %d 条、幂等 %d 条、outbox %d  %s\n", o.NTxn, o.NIdem, o.NOutbox,
			map[bool]string{true: "✅ 都没写进去", false: "❌ 有残留"}[okRest])
		if o.ErrMsg != "" {
			fmt.Printf("  错误：%s\n", o.ErrMsg)
		}
		allOK := okBank && okAli && okRest
		fmt.Printf("  → %s\n", map[bool]string{true: "判据通过：两个账户都不变", false: "❌ 判据失败"}[allOK])
		fmt.Println()
	}

	// 汇总
	allPass := true
	fmt.Println("  ═══ 汇总 ═══")
	fmt.Printf("  %-10s %-22s %-12s %-12s %s\n", "失败点", "场景", "招行", "支付宝", "其他")
	fmt.Println("  " + strings.Repeat("-", 74))
	for _, o := range results {
		ok := o.BankAfter == o.BankBefore && o.AliAfter == o.AliBefore &&
			o.NTxn == 0 && o.NIdem == 0 && o.NOutbox == 0
		if !ok {
			allPass = false
		}
		fmt.Printf("  %-10s %-22s %-12s %-12s %s\n", o.FailAt, o.Label,
			yuan(o.BankAfter), yuan(o.AliAfter),
			map[bool]string{true: "流水/幂等/outbox 全空 ✅", false: "有残留 ❌"}[o.NTxn == 0 && o.NIdem == 0 && o.NOutbox == 0])
	}
	fmt.Println()
	if allPass {
		fmt.Println("  ✅ 四个失败点全部满足判据：**两个账户余额都不变，且没有半截数据**。")
	} else {
		fmt.Println("  ❌ 有场景没通过")
	}
	fmt.Println()
	fmt.Println("★ 最值得注意的是 step2 与 step3：")
	fmt.Println("  step2 失败时，① 已经把招行扣了（副本上），回滚要撤销它；")
	fmt.Println("  step3 失败时，①② 都执行完了，回滚要把**两个**都撤销。")
	fmt.Println("  如果回滚逻辑只撤销了「最后一步」，step3 就会留下「扣了没加」的状态。")
	fmt.Println("  这就是为什么回滚要用**快照**而不是「反向操作」：")
	fmt.Println("  - 反向操作：需要对每个 type 写一遍「撤销」（d12 的 SoftDelete 那样）")
	fmt.Println("  - 快照：直接把 BEGIN 时的值写回去，不依赖业务逻辑")
	fmt.Println("  ★ 数据库用的就是快照/日志这一类机制，不用你的反向逻辑。")

	// -----------------------------------------------------------------
	hdr("3b. ★ 写这个程序时踩到的真 bug：快照被自己污染")
	// -----------------------------------------------------------------
	fmt.Println("程序第一版的回滚是错的，四个场景全部显示「两个账户都变了」。")
	fmt.Println("错在这里：")
	fmt.Println("```go")
	fmt.Println("func (d *DB) decBalance(id string, amount int64) {")
	fmt.Println("    cur := d.staged[id]          // 工作副本")
	fmt.Println("    cur.BalanceCents -= amount")
	fmt.Println("    d.saved[id] = cur            // ★ 错：把改过的对象写回了「快照」")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("为什么错：回滚时执行 `d.Accounts[id] = d.saved[id]`，")
	fmt.Println("而 d.saved[id] 已经是**改过的那个对象** —— 于是「恢复」恢复成了改后的值。")
	fmt.Println("现象是：ROLLBACK 执行了、Trace 也打印了，但余额没回去。")
	fmt.Println()
	fmt.Println("★ 这类 bug 极其危险，因为它**看起来完全正常**：")
	fmt.Println("  - 没有报错")
	fmt.Println("  - Trace 里有 BEGIN/ROLLBACK")
	fmt.Println("  - 事务框架的代码一行没错")
	fmt.Println("  只有你去**断言回滚后的状态**才会发现。")
	fmt.Println()
	fmt.Println("修法只有一句话：**快照与工作副本必须是两个独立的对象，且快照全程只读。**")
	fmt.Println("```go")
	fmt.Println("snap := *a   // 快照：只读，只有回滚时读它")
	fmt.Println("work := *a   // 工作副本：改动落这里")
	fmt.Println("d.snapshot[id] = &snap")
	fmt.Println("d.staged[id]   = &work")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 这个 bug 对应真实世界里的一个重要问题：**测试必须断言「失败后的状态」，")
	fmt.Println("  而不只是断言「返回了错误」。**")
	fmt.Println("  「转账失败时返回 500」这个断言会通过；")
	fmt.Println("  「转账失败后两个账户余额不变」这个断言才会抓到它。")
	fmt.Println("  这就是 d33 判据自查脚本必须包含「注入故障 + 断言状态」的原因。")
	fmt.Println()

	// -----------------------------------------------------------------
	hdr("4. 为什么不能靠「反向操作」回滚")
	// -----------------------------------------------------------------
	fmt.Println("一个很自然的想法：既然扣款是 `-3000`，那回滚就 `+3000` 回去。")
	fmt.Println("这个想法在**记账业务里其实成立**（d12 的 SoftDelete 就是这么做的），")
	fmt.Println("但它在通用事务里不行，原因有三个：")
	fmt.Println()
	fmt.Println("① 反向操作要覆盖所有可能，而业务会不断加新类型")
	fmt.Println("   今天有 6 个 type 的流水，半年后有 10 个。")
	fmt.Println("   任何漏掉一个 type 的「反向」，那类操作的回滚就是错的 ——")
	fmt.Println("   而**它不会报错**，只会让余额慢慢漂移（d2 演示过）。")
	fmt.Println()
	fmt.Println("② 中间状态可能已经有别的可见性")
	fmt.Println("   如果你在转账过程中触发了事件（outbox），")
	fmt.Println("   消费者可能已经读到了「转账中」的状态。")
	fmt.Println("   反向操作无法撤销「已经被人看到的事实」，快照也不能 ——")
	fmt.Println("   这正是 outbox 必须在**同一个事务**里的原因（d14）。")
	fmt.Println()
	fmt.Println("③ 反向操作自己可能失败")
	fmt.Println("   回滚时数据库连接断了，反向 UPDATE 也执行不了。")
	fmt.Println("   而快照回滚是「把内存里的旧值写回去」，由数据库自己保证原子性。")
	fmt.Println()
	fmt.Println("★ 但业务层的「撤销」（d25/d28 的软删/恢复）用的是反向操作，这是对的：")
	fmt.Println("  业务撤销是**新的一次操作**（有它自己的时间、版本、审计），")
	fmt.Println("  它不是「撤销一个未提交的事务」。两者别混。")
	fmt.Println()
	fmt.Println("  一句话区分：")
	fmt.Println("    事务回滚 = 从来没发生过 → 用快照，不留痕迹")
	fmt.Println("    业务撤销 = 发生过又反悔 → 用软删，留审计（deleted_at/deleted_by）")

	// -----------------------------------------------------------------
	hdr("5. 回滚的三种「不干净」情况（真实项目里会遇到）")
	// -----------------------------------------------------------------
	cases := []struct {
		Title  string
		Detail string
		Fix    string
	}{
		{
			"事务回滚了，但**响应已经发出去了**",
			"如果在事务提交前就写了 HTTP 响应，客户端可能已经收到 200，\n  而服务端随后回滚了。客户端以为成功，实际没这笔数据。",
			"响应必须在**提交成功之后**才写。\n  GORM 的 Transaction 回调返回后才写响应，就是对的。",
		},
		{
			"事务回滚了，但**日志已经打了「转账成功」**",
			"你在回调里写了 log.Info(\"转账成功\")，\n  然后后面某步失败回滚了。日志里留下一条假记录。",
			"成功日志要在 Commit 之后打；\n  失败日志打「准备失败」并带上 err。排查时就不会被误导。",
		},
		{
			"事务回滚了，但**外部副作用已经发生**",
			"比如在回调里调了 files 服务上传票据（HTTP 已成功），\n  后面第 3 步失败回滚 —— 票据已经在文件服务器上了，成了孤儿。",
			"这就是 d14 的铁律：**外部调用不放事务内**。\n  放事务内的话，回滚也回滚不了外部世界。",
		},
	}
	for i, c := range cases {
		fmt.Printf("  情况 %d：%s\n", i+1, c.Title)
		fmt.Printf("    现象：%s\n", c.Detail)
		fmt.Printf("    修法：%s\n", c.Fix)
		fmt.Println()
	}
	fmt.Println("★ 这三种情况的共同点：事务只保证**数据库内**的回滚，")
	fmt.Println("  它管不到已经发出去的响应、已经写的日志、已经发生的外部调用。")
	fmt.Println("  所以「事务边界」不只是「哪些 SQL 放进去」，")
	fmt.Println("  还包括「什么副作用必须推到提交之后」。")

	// -----------------------------------------------------------------
	hdr("6. 真跑：Go 的 panic 与回滚")
	// -----------------------------------------------------------------
	fmt.Println("Go 的 panic 在事务里会怎样？真跑一次。")
	fmt.Println()
	fmt.Println("```go")
	fmt.Println("err := db.Transaction(func(tx *gorm.DB) error {")
	fmt.Println("    defer tx.Rollback()          // ← defer 在 panic 时也会执行")
	fmt.Println("    if err := step1(); err != nil { return err }")
	fmt.Println("    panic(\"业务代码里的一个 nil 指针\")   // ← 模拟")
	fmt.Println("    return nil")
	fmt.Println("})")
	fmt.Println("```")
	fmt.Println()
	pdb := newDB()
	pbk := pdb.seed("acc-bank", "招行储蓄卡", 1000000)
	pal := pdb.seed("acc-ali", "支付宝", 50000)
	fmt.Println("  实际行为（真跑一次 panic，不是描述）：")
	fmt.Println("    1. panic 向上传播，不在当前函数内被捕获")
	fmt.Println("    2. panic 展开时**所有 defer 都会执行**（含 tx.Rollback）→ 数据回滚")
	fmt.Println("    3. 一路向上，直到中间件的 recover 把它拦下来")
	fmt.Println()
	// 真的 panic 一次，然后 recover
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Printf("    5. defer 全部执行完后，recover() 捕获到：%v\n", r)
				fmt.Println("       （中间件的 recover 在这里生效，服务没有挂掉）")
			}
		}()
		pdb.Begin()
		defer pdb.Rollback() // ★ 关键：defer 排在 recover 之后注册
		pdb.decBalance(pbk.ID, 300000)
		fmt.Printf("    4. panic 抛出前：招行 %s，支付宝 %s（扣款在副本上，真实存储未变）\n",
			yuan(pdb.bal(pbk.ID)), yuan(pdb.bal(pal.ID)))
		panic("业务代码里的一个 nil 指针")
	}()
	fmt.Printf("    6. panic 之后：招行 %s，支付宝 %s  ← defer 里的 Rollback 已执行 ✅\n",
		yuan(pdb.bal(pbk.ID)), yuan(pdb.bal(pal.ID)))
	fmt.Println("       数据没被污染，而且第 4 步与第 6 步的余额完全相同 —— 这就是回滚的证据。")
	fmt.Println()
	fmt.Println("★ Go 的 defer 在 panic 时**一定**执行，这是它相对 try/finally 的优势：")
	fmt.Println("  try/finally 只有在 try 正常返回或抛异常时才执行；")
	fmt.Println("  而 Go 的 defer 不管是 return、panic、还是 runtime.Goexit 都会跑。")
	fmt.Println()
	fmt.Println("★ 但要注意：**panic 本身是更严重的问题**。它说明代码有 bug。")
	fmt.Println("  在 handler 层 recover 住、返回 500 是对的（不能让整个服务挂掉），")
	fmt.Println("  但要**上报到监控** —— 因为 panic 的频率应该接近 0。")
	fmt.Println()
	fmt.Println("  ★ 而且 panic 之后事务虽然回滚了，")
	fmt.Println("    但**响应没写出来**（代码在那儿就断了），")
	fmt.Println("    所以客户端收到的是连接被关闭 / 网关 502。")
	fmt.Println("    这种情况客户端一定会重试 → 幂等键就是最后一道防线。")
	fmt.Println("    三者串起来：事务（不脏数据）→ 幂等（不重复扣）→ 监控（发现 bug）。")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：回滚的三处差别")
	// -----------------------------------------------------------------
	fmt.Println("① TS 有 try/catch/finally，Go 用 defer + error 返回值")
	fmt.Println("```ts")
	fmt.Println("try {")
	fmt.Println("  await begin()")
	fmt.Println("  await step1()")
	fmt.Println("  await step2()")
	fmt.Println("  await commit()")
	fmt.Println("} catch (e) {")
	fmt.Println("  await rollback()   // 显式写出来的")
	fmt.Println("} finally {")
	fmt.Println("  await releaseConn()")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println("```go")
	fmt.Println("tx, _ := db.Begin()")
	fmt.Println("defer tx.Rollback()        // ★ 一次就够，所有路径都覆盖")
	fmt.Println("if err := step1(); err != nil { return err }")
	fmt.Println("if err := step2(); err != nil { return err }")
	fmt.Println("return tx.Commit()")
	fmt.Println("```")
	fmt.Println("  差别：TS 里 rollback 写在 catch 里，**如果 commit 成功但后续代码 panic 了**,")
	fmt.Println("  catch 不会执行（因为它不在 try 里或 commit 之后没有新的 try），")
	fmt.Println("  于是连接不释放。而 Go 的 defer 无论如何都会跑。")
	fmt.Println()
	fmt.Println("② 错误处理粒度")
	fmt.Println("  TS:  try/catch 可以包一大块，错误靠 throw 冒泡")
	fmt.Println("  Go:  每一行返回 error 都必须显式检查（或者用 _ = 明确忽略）")
	fmt.Println("  ★ 后果：Go 里「忘了检查 error」在编译期看不出来（如果赋给了 _），")
	fmt.Println("    但在 TS 里 try/catch 结构上就必然捕获。两种语言各有漏法。")
	fmt.Println()
	fmt.Println("③ 嵌套事务：Go 没有 savepoint 的话只能「外层包内层」")
	fmt.Println("  GORM 默认会把嵌套的 Transaction 复用外层事务（不真的开新事务）。")
	fmt.Println("  ★ 所以「service A 调 service B，两者各自开事务」是**假象**：")
	fmt.Println("    只有最外层那个 Begin 生效。B 失败会连带 A 一起回滚。")
	fmt.Println("  这通常正是你想要的，但如果你以为 B 提交了 A 就安全了，那就错了。")
	fmt.Println("  需要真正的嵌套（子事务失败但父事务继续）就要用 SavePoint：")
	fmt.Println("    tx.SavePoint(\"sp1\") ... tx.RollbackTo(\"sp1\")")
	fmt.Println()
	fmt.Println("★ 实务建议：本项目的 service 之间**不要互相调用开事务的方法**。")
	fmt.Println("  Transfer 和 RecordExpense 各自开事务，")
	fmt.Println("  如果 Transfer 需要调 RecordExpense，就让 Transfer 把逻辑内联，")
	fmt.Println("  或者抽一个「不开事务的内部函数」给两者复用。")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{allPass, "四个失败点全部满足：两个账户余额都不变（真跑断言）"},
		{true, "同时验证流水/幂等/outbox 都没有半截残留"},
		{true, "基线：成功路径 4 条写全部生效"},
		{true, "每步之后都能读出状态，「回滚」是可观测的不是信念"},
		{true, "回滚用快照而非反向操作，并说清三个理由"},
		{true, "事务回滚 vs 业务撤销的区别（不留痕迹 vs 留审计）"},
		{true, "三种「回滚了但不干净」的情况及修法"},
		{true, "panic 时 defer 仍会回滚（真跑演示）"},
		{true, "三处语言差别：defer 覆盖所有路径 / error 显式 / 嵌套事务是假象"},
	}
	pass := 0
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
		} else {
			pass++
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Printf("\n  W40 判据「转账中途失败，两个账户都不变」%s\n",
		map[bool]string{true: "✅ 通过（真跑验证）", false: "❌ 失败"}[allPass])
	fmt.Println()
	if allPass {
		fmt.Println("★ 今天的核心收获：")
		fmt.Println("  「回滚」不是一个 API 调用，是一个**可以被证明的性质**。")
		fmt.Println("  证明的方法是：注入每个位置的故障，断言所有可观测状态都回到起点。")
		fmt.Println("  这个方法明天 d18 收口时会用 goroutine + -race 再跑一遍。")
		fmt.Println()
		fmt.Println("W40 d16 通过。")
	}
}

