package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
	"sync"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// =====================================================================
// 并发安全的内存库：每个账户一把行锁（模拟 Postgres 的行级锁）
// =====================================================================

type Account struct {
	ID           string
	Name         string
	BalanceCents int64
	Version      int
	mu           *sync.Mutex // 这一把锁 = 数据库里这一行的行锁
}

type Txn struct {
	ID          string
	From        string
	To          string
	AmountCents int64
	CRID        string
}

type DB struct {
	Accounts map[string]*Account
	Txns     []*Txn
	seq      int
	mu       sync.Mutex // 保护 Txns 与 seq（相当于表级元数据锁）
	// 统计
	Committed int
	Rolled    int
}

func newDB() *DB {
	return &DB{Accounts: map[string]*Account{}}
}

func (d *DB) acc(name string, bal int64) *Account {
	a := &Account{ID: "acc-" + name, Name: name, BalanceCents: bal, Version: 1, mu: &sync.Mutex{}}
	d.Accounts[a.ID] = a
	return a
}

func (d *DB) lockAccounts(ids ...string) func() {
	// ★ 按 ID 排序后加锁 —— 这是防死锁的关键（d14 讲过加锁顺序）
	sorted := append([]string(nil), ids...)
	sort.Strings(sorted)
	var locks []*sync.Mutex
	seen := map[string]bool{}
	for _, id := range sorted {
		if seen[id] {
			continue
		}
		seen[id] = true
		if a, ok := d.Accounts[id]; ok {
			a.mu.Lock()
			locks = append(locks, a.mu)
		}
	}
	return func() {
		for i := len(locks) - 1; i >= 0; i-- {
			locks[i].Unlock()
		}
	}
}

// 转账：完整的事务语义（加锁 → 改两个余额 → 插流水 → 提交 / 失败回滚）
func (d *DB) transfer(from, to string, amount int64, crid string) (string, error) {
	if from == to {
		return "", fmt.Errorf("转出与转入不能相同")
	}
	src, okS := d.Accounts[from]
	dst, okD := d.Accounts[to]
	if !okS || !okD {
		return "", fmt.Errorf("账户不存在")
	}

	unlock := d.lockAccounts(from, to) // BEGIN + 取行锁（按 ID 排序）
	defer unlock()                     // COMMIT/ROLLBACK 都释放

	// 预检（在锁内，所以这次看到的是最新值）
	if src.BalanceCents < amount {
		d.mu.Lock()
		d.Rolled++
		d.mu.Unlock()
		return "", fmt.Errorf("余额不足：当前 %d，需要 %d", src.BalanceCents, amount)
	}

	// ★ 扣减有条件（对应 SQL 的 WHERE balance_cents >= ?）
	if src.BalanceCents < amount {
		d.mu.Lock()
		d.Rolled++
		d.mu.Unlock()
		return "", fmt.Errorf("并发导致余额不足")
	}
	src.BalanceCents -= amount
	src.Version++
	dst.BalanceCents += amount
	dst.Version++

	d.mu.Lock()
	d.seq++
	t := &Txn{ID: fmt.Sprintf("txn-%04d", d.seq), From: from, To: to,
		AmountCents: amount, CRID: crid}
	d.Txns = append(d.Txns, t)
	d.Committed++
	d.mu.Unlock()
	return t.ID, nil
}

func (d *DB) balance(id string) int64 {
	return d.Accounts[id].BalanceCents
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 真实并发测试：两个 goroutine 同时转账
// =====================================================================

type result struct {
	Name    string
	CRID    string
	Amount  int64
	TxnID   string
	Err     string
	Elapsed string
}

func (d *DB) concurrentTransferTwo() []result {
	// 起始信号：两个 goroutine 都阻塞在接收上，收到同一个信号后同时冲出去
	start := make(chan struct{})
	results := make(chan result, 2)
	var wg sync.WaitGroup

	type job struct {
		name   string
		crid   string
		amount int64
		to     string
	}
	jobs := []job{
		{"妈妈", "crid-mom-1", 300000, "acc-支付宝"},
		{"爸爸", "crid-dad-1", 300000, "acc-微信"},
	}

	for _, j := range jobs {
		wg.Add(1)
		go func(j job) {
			defer wg.Done()
			<-start // ★ 同步起点：制造真正的竞争窗口
			t0 := time.Now()
			id, err := d.transfer("acc-招行", j.to, j.amount, j.crid)
			el := time.Since(t0)
			r := result{Name: j.name, CRID: j.crid, Amount: j.amount, TxnID: id, Elapsed: el.Round(time.Microsecond).String()}
			if err != nil {
				r.Err = err.Error()
			}
			results <- r
		}(j)
	}
	close(start) // 同时放行
	wg.Wait()
	close(results)

	var out []result
	for r := range results {
		out = append(out, r)
	}
	// 排序保证输出确定（channel 接收顺序不确定）
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func (d *DB) concurrentTransferSameAccount() []result {
	// 同一个账户被两个 goroutine 同时扣
	start := make(chan struct{})
	results := make(chan result, 2)
	var wg sync.WaitGroup
	jobs := []struct {
		name string
		crid string
		to   string
		amt  int64
	}{
		{"转出到支付宝", "crid-x-1", "acc-支付宝", 300000}, // 3000 元
		{"转出到微信", "crid-x-2", "acc-微信", 300000},   // 3000 元
	}
	for _, j := range jobs {
		wg.Add(1)
		go func(j struct {
			name string
			crid string
			to   string
			amt  int64
		}) {
			defer wg.Done()
			<-start
			id, err := d.transfer("acc-招行", j.to, j.amt, j.crid)
			r := result{Name: j.name, CRID: j.crid, Amount: j.amt, TxnID: id}
			if err != nil {
				r.Err = err.Error()
			}
			results <- r
		}(j)
	}
	close(start)
	wg.Wait()
	close(results)
	var out []result
	for r := range results {
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

