		yuan(d.balance("acc-招行")), yuan(d.balance("acc-支付宝")), yuan(d.balance("acc-微信")))
	fmt.Printf("  流水 %d 条，COMMIT %d 次，ROLLBACK %d 次\n", len(d.Txns), d.Committed, d.Rolled)
