// =====================================================================
// W41 d20：★ 乐观锁的实现 —— WHERE version = ?，影响行数 0 就是冲突。
//
// d19 讲了「为什么必须有 version」，今天讲「怎么用对」。
//
// 三个容易写错的地方，每一个都会**静默失效**（不报错、冲突永不发生）：
//   ① 用 Error != nil 判断冲突  → 错，冲突时 Error 是 nil
//   ② SET version = 2 写死     → 错，计数器失效
//   ③ WHERE 里传「要设的新版本」→ 错，传的必须是「我读到的版本」
//
// 第 3 节真跑：三种错误写法各自的实际后果。
// 第 5 节真跑：GORM 两种写法（Model+Updates / 条件 Updates）的差异。
// 第 6 节：哪些接口需要 version，哪些不需要。
//
// 本机没有 Postgres。内存模拟 + GORM DryRun 真实生成 SQL。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

type Txn struct {
	ID        string
	FamilyID  string
	Note      string
	Amount    int64
	Version   int
	UpdatedAt time.Time
}

func (Txn) TableName() string { return "finance_transaction" }

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true,
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 内存表：模拟 UPDATE 的三个可观测量
//   SQLError —— 有没有报错
//   Rows     —— 影响了多少行
// =====================================================================

type memRow struct {
	Note    string
	Version int
}

type memDB struct {
	Rows map[string]*memRow
}

func newMem() *memDB {
	return &memDB{Rows: map[string]*memRow{}}
}

// 模拟一次 UPDATE。返回 (sqlError, rowsAffected)
func (d *memDB) update(id string, setNote *string, setVer *int, whereVer *int) (error, int) {
	r, ok := d.Rows[id]
	if !ok {
		return nil, 0
	}
	if whereVer != nil && r.Version != *whereVer {
		// ★ 关键：SQL 执行成功，没报错，只是没匹配到行
		return nil, 0
	}
	if setNote != nil {
		r.Note = *setNote
	}
	if setVer != nil {
		r.Version = *setVer
	}
	return nil, 1
}

func sp(s string) *string { return &s }
func ip(i int) *int       { return &i }

func main() {
	// -----------------------------------------------------------------
	hdr("1. 三个可观测量：Error / RowsAffected / 冲突")
	// -----------------------------------------------------------------
	fmt.Println("执行 `UPDATE ... WHERE id = ? AND version = ?` 时，")
	fmt.Println("你从数据库拿到的信息有三个：")
	fmt.Println()
	fmt.Println("  ① Error          —— 语句本身有没有失败（语法错、连接断、类型不匹配）")
	fmt.Println("  ② RowsAffected   —— WHERE 匹配到了几行")
	fmt.Println("  ③ 返回的行数据     —— 这里用不上（UPDATE 不返回行）")
	fmt.Println()
	fmt.Println("★ 版本冲突时这三者的取值是：")
	fmt.Println("    Error        = nil      ← 语句成功执行了！")
	fmt.Println("    RowsAffected = 0         ← 但没匹配到任何行")
	fmt.Println()
	fmt.Println("数据库的视角：「我按你的要求更新了 0 行，这完全合法」。")
	fmt.Println("你的要求是「更新 version = 1 的行」，而当时没有这样的行。")
	fmt.Println("这不是错误，是**一个成功执行了但没有产生效果的操作**。")
	fmt.Println()
	fmt.Println("所以冲突的唯一信号是 RowsAffected == 0。")
	fmt.Println("如果你写成 `if err != nil { return err }`，冲突会被完全忽略。")
	fmt.Println()

	d := newMem()
	d.Rows["txn-0034"] = &memRow{Note: "买菜", Version: 1}

	fmt.Println("  第一次更新（version=1，条件成立）：")
	err, rows := d.update("txn-0034", sp("买菜 - 菜市场"), ip(2), ip(1))
	fmt.Printf("    Error=%v，RowsAffected=%d → %s\n", err, rows, verdict(rows))
	fmt.Printf("    现在 note=「%s」，version=%d\n\n", d.Rows["txn-0034"].Note, d.Rows["txn-0034"].Version)

	fmt.Println("  第二次更新（还想用 version=1，条件已不成立）：")
	err, rows = d.update("txn-0034", sp("买菜 - 超市"), ip(2), ip(1))
	fmt.Printf("    Error=%v，RowsAffected=%d → %s\n", err, rows, verdict(rows))
	fmt.Printf("    现在 note=「%s」，version=%d（**没变**）\n", d.Rows["txn-0034"].Note, d.Rows["txn-0034"].Version)
	fmt.Println()
	fmt.Println("  ★ 注意 Error 两次都是 nil。如果代码只检查 Error，")
	fmt.Println("    它会认为第二次也成功了，然后返回 200 给用户。")
	fmt.Println("    用户看到「保存成功」，但数据没变 —— 变成另一种静默失败。")

	// -----------------------------------------------------------------
	hdr("2. 正确的三步判断（写死这个模式）")
	// -----------------------------------------------------------------
	fmt.Println("```go")
	fmt.Println("result := tx.Model(&Txn{}).")
	fmt.Println("    Where(\"id = ? AND family_id = ? AND version = ? AND deleted_at IS NULL\",")
	fmt.Println("        req.ID, famID, req.Version).")
	fmt.Println("    Updates(map[string]any{")
	fmt.Println("        \"note\":       req.Note,")
	fmt.Println("        \"version\":    gorm.Expr(\"version + ?\", 1),   // ★ 必须是表达式")
	fmt.Println("        \"updated_at\": time.Now(),")
	fmt.Println("    })")
	fmt.Println("")
	fmt.Println("// ① 数据库层面的错（连接断了、类型不匹配）")
	fmt.Println("if result.Error != nil {")
	fmt.Println("    return nil, wrapInternalErr(result.Error)")
	fmt.Println("}")
	fmt.Println("// ② 版本冲突 / 记录不存在 / 已软删 —— 都是影响 0 行")
	fmt.Println("if result.RowsAffected == 0 {")
	fmt.Println("    // 还要区分「不存在」和「冲突」，见第 6 节")
	fmt.Println("    return nil, ErrVersionConflict")
	fmt.Println("}")
	fmt.Println("// ③ 成功")
	fmt.Println("return nil")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 第 ② 步为什么不能省：省掉之后，乐观锁**静默失效**。")
	fmt.Println("  不会报错、不会告警、测试可能也通过（单线程测试没有冲突），")
	fmt.Println("  只是冲突检测率变成 0。你会在某天收到「为什么改了没生效」的工单。")

	// -----------------------------------------------------------------
	hdr("3. ★ 真跑：三种错误写法各自的实际后果")
	// -----------------------------------------------------------------
	cases := []struct {
		Name  string
		Code  string
		Setup func(d *memDB)
		Check func(d *memDB) string
	}{
		{
			"① 用 Error 判断冲突",
			`if err := res.Error; err != nil { return err }   // 漏了 RowsAffected`,
			func(d *memDB) { d.Rows["t1"] = &memRow{Note: "原始", Version: 1} },
			func(d *memDB) string {
				// 妈妈改成功（version 1→2），爸爸仍带 version=1
				d.update("t1", sp("妈妈改的"), ip(2), ip(1))
				err, rows := d.update("t1", sp("爸爸改的"), ip(2), ip(1))
				// 只看 Error 的写法会认为「成功」，直接返回 200
				return fmt.Sprintf("爸爸这次：Error=%v，RowsAffected=%d → 只看 Error 的代码会返回 200，"+
					"但数据仍是「%s」（爸爸的修改静默丢失）", err, rows, d.Rows["t1"].Note)
			},
		},
		{
			"② SET version = 2 写死",
			`"version": 2,   // ← 应该用 gorm.Expr("version + ?", 1)`,
			func(d *memDB) { d.Rows["t1"] = &memRow{Note: "原始", Version: 1} },
			func(d *memDB) string {
				d.update("t1", sp("第1次改"), ip(2), ip(1)) // version 1→2
				// 第二次：用 version=2 改，但 SET 又写成 2
				_, rows := d.update("t1", sp("第2次改"), ip(2), ip(2))
				return fmt.Sprintf("第2次改：RowsAffected=%d，version 仍为 %d", rows, d.Rows["t1"].Version)
			},
		},
		{
			"③ WHERE 传「新版本」",
			`Where("... AND version = ?", req.Version+1)  // ← 传错，应该是 req.Version`,
			func(d *memDB) { d.Rows["t1"] = &memRow{Note: "原始", Version: 1} },
			func(d *memDB) string {
				// 前端带 version=1，但服务端传 2 进去
				_, rows := d.update("t1", sp("第一次改"), ip(2), ip(2))
				return fmt.Sprintf("第一次改就冲突：RowsAffected=%d，version 仍为 %d", rows, d.Rows["t1"].Version)
			},
		},
		{
			"④ 正确写法",
			`Where("... AND version = ?", req.Version)  +  "version": gorm.Expr("version + ?", 1)`,
			func(d *memDB) { d.Rows["t1"] = &memRow{Note: "原始", Version: 1} },
			func(d *memDB) string {
				d.update("t1", sp("妈妈改的"), ip(2), ip(1))
				_, rows := d.update("t1", sp("爸爸改的"), ip(2), ip(1))
				return fmt.Sprintf("妈妈成功(version→2)，爸爸 RowsAffected=%d → 返 409", rows)
			},
		},
	}
	for _, c := range cases {
		fmt.Printf("【%s】\n", c.Name)
		fmt.Printf("  代码：%s\n", c.Code)
		dm := newMem()
		c.Setup(dm)
		fmt.Printf("  实际：%s\n\n", c.Check(dm))
	}
	fmt.Println("★ 四个写法的对照结论：")
	fmt.Println("  ① 冲突检测率 = 0（永远不报冲突，还返回 200）—— 最危险，因为它看起来能跑")
	fmt.Println("  ② 计数器失效（永远停在 2）—— 后果是 version 失去意义")
	fmt.Println("  ③ 永远冲突（第一次就失败）—— 这个反而**容易被发现**，因为功能不可用")
	fmt.Println("  ④ 正确")
	fmt.Println()
	fmt.Println("★ 值得注意的是 ③ 比 ① 更容易发现。")
	fmt.Println("  「功能完全不可用」会立刻被 QA 抓到；")
	fmt.Println("  「冲突检测静默失效」要等到真实用户并发编辑时才会暴露，")
	fmt.Println("  而那时往往是上线几个月之后。")

	// -----------------------------------------------------------------
	hdr("4. ② 写死 version 的更深的问题")
	// -----------------------------------------------------------------
	fmt.Println("「SET version = 2 写死」看起来只是「计数器不走」，但后果更严重：")
	fmt.Println()
	dv := newMem()
	dv.Rows["t1"] = &memRow{Note: "原始", Version: 1}
	fmt.Println("  用写死的写法连续改 5 次（每次都带正确的当前 version）：")
	for i := 1; i <= 5; i++ {
		_, rows := dv.update("t1", sp(fmt.Sprintf("第%d版", i)), ip(2), ip(2))
		fmt.Printf("    第 %d 次：RowsAffected=%d，version=%d，note=「%s」\n", i, rows, dv.Rows["t1"].Version, dv.Rows["t1"].Note)
	}
	fmt.Println()
	fmt.Println("  第 2 次就卡住了：version 永远是 2，而 WHERE 要求 version=2 ——")
	fmt.Println("  于是它「匹配成功」了（因为库里的值确实是 2），但它**没有递增**。")
	fmt.Println()
	fmt.Println("  后果：version 变成了一个常量，乐观锁的语义完全失效。")
	fmt.Println("  更糟的是它**不会阻止任何并发**：")
	dv2 := newMem()
	dv2.Rows["t1"] = &memRow{Note: "原始", Version: 2}
	_, r1 := dv2.update("t1", sp("妈妈"), ip(2), ip(2))
	_, r2 := dv2.update("t1", sp("爸爸"), ip(2), ip(2))
	fmt.Printf("  两个都用 version=2：妈妈 RowsAffected=%d，爸爸 RowsAffected=%d\n", r1, r2)
	fmt.Println("  两边都「成功」—— 因为库里的 version 一直没变过。")
	fmt.Println("  ★ 乐观锁最关键的性质是「值必须单调递增」，写死就丢掉了它。")
	fmt.Println()
	fmt.Println("  正确写法只有一种：")
	fmt.Println(`    "version": gorm.Expr("version + ?", 1)`)
	fmt.Println("  绝不能写：")
	fmt.Println(`    "version": req.Version + 1`) // 同样的值，请求里是多少就写多少`)
	fmt.Println(`    "version": 2`)
	fmt.Println("  前者等价于写死（因为 WHERE 已经用掉了一个 version），后者是硬编码。")
	fmt.Println()

	// -----------------------------------------------------------------
	hdr("5. GORM 的两种写法（DryRun 真实生成）")
	// -----------------------------------------------------------------
	db := dryDB()

	fmt.Println("写法 A：Model + Where + Updates（推荐）")
	sqlA := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Where("id = ? AND family_id = ? AND version = ?", "txn-0034", famA, 1).
			Updates(map[string]any{
				"note":       "买菜 - 菜市场",
				"version":    gorm.Expr("version + ?", 1),
				"updated_at": fixedNow,
			})
	})
	fmt.Println("  ", sqlA)
	fmt.Println("  ★ 三处关键：")
	fmt.Println("    ① Where 里有 version = ?（三个条件）")
	fmt.Println("    ② version 用 gorm.Expr 而不是字面量")
	fmt.Println("    ③ 返回值必须检查 RowsAffected")
	fmt.Println()

	fmt.Println("写法 B：struct 更新（❌ 有陷阱）")
	sqlB := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Where("id = ? AND version = ?", "txn-0034", 1).
			Updates(Txn{Note: "买菜 - 菜市场", Version: 2})
	})
	fmt.Println("  ", sqlB)
	fmt.Println("  ❌ 两个陷阱：")
	fmt.Println("    ① GORM 忽略 struct 里的零值字段 —— Version: 0 不会出现在 SET 里，")
	fmt.Println("       但 Version: 2 会。而这正是「写死」的形式")
	fmt.Println("    ② 无法写 version + 1（struct 只能给具体值）")
	fmt.Println("  → 所以**永远用 map + gorm.Expr**，不要用 struct")
	fmt.Println()

	fmt.Println("写法 C：Raw（能用，但要自己拼好）")
	sqlC := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Exec(`UPDATE finance_transaction
       SET note = ?, version = version + 1, updated_at = ?
     WHERE id = ? AND family_id = ? AND version = ? AND deleted_at IS NULL`,
			"买菜 - 菜市场", fixedNow, "txn-0034", famA, 1)
	})
	fmt.Println("  ", sqlC)
	fmt.Println("  ★ Raw 的 res.RowsAffected 一样可用，冲突检测照常。")
	fmt.Println("    适合复杂的条件更新（比如带 CASE WHEN 的聚合更新）。")
	fmt.Println()

	fmt.Println("★ 三种写法的选择：")
	fmt.Println("  A（map + Expr）：99% 的场景用它")
	fmt.Println("  B（struct）：本项目**禁止**用 Updates(struct)，因为零值陷阱")
	fmt.Println("  C（Raw）：条件特别复杂时才用；记得 deleted_at IS NULL 别漏")
	fmt.Println()

	// -----------------------------------------------------------------
	hdr("6. RowsAffected == 0 的三种原因必须区分")
	// -----------------------------------------------------------------
	fmt.Println("`WHERE id = ? AND family_id = ? AND version = ? AND deleted_at IS NULL`")
	fmt.Println("匹配不到行，有三个完全不同的原因：")
	fmt.Println()
	reasons := []struct {
		Cond   string
		Status int
		Code   int
		Msg    string
	}{
		{"id 不存在 / 不属于本家庭", 404, 3001, "资源不存在"},
		{"已被软删（deleted_at 非空）", 404, 3001, "资源不存在"},
		{"version 不匹配", 409, 40901, "数据已被他人修改，请刷新后重试"},
	}
	fmt.Printf("  %-34s %-8s %-8s %s\n", "原因", "HTTP", "code", "message")
	fmt.Println("  " + strings.Repeat("-", 84))
	for _, r := range reasons {
		fmt.Printf("  %-34s %-8d %-8d %s\n", r.Cond, r.Status, r.Code, r.Msg)
	}
	fmt.Println()
	fmt.Println("★ 前两个必须返 404，第三个必须返 409。")
	fmt.Println("  返错的实际后果：")
	fmt.Println("    · 把 version 冲突返 404 → 用户以为「东西被删了」，慌了")
	fmt.Println("    · 把「不存在」返 409 → 前端弹「数据已被修改」，用户更困惑")
	fmt.Println("    · 越权返 403 → **告诉攻击者这个 id 存在**（S5 红线）")
	fmt.Println()
	fmt.Println("怎么区分？多查一次：")
	fmt.Println("```go")
	fmt.Println("if result.RowsAffected == 0 {")
	fmt.Println("    // 到底是「没有」还是「版本不对」？查一次（不加 version 条件）")
	fmt.Println("    var existing Txn")
	fmt.Println("    err := tx.Where(\"id = ? AND family_id = ? AND deleted_at IS NULL\",")
	fmt.Println("        req.ID, famID).First(&existing).Error")
	fmt.Println("    if errors.Is(err, gorm.ErrRecordNotFound) {")
	fmt.Println("        return nil, ErrNotFound        // 404")
	fmt.Println("    }")
	fmt.Println("    return nil, &VersionConflict{       // 409")
	fmt.Println("        CurrentVersion:  existing.Version,")
	fmt.Println("        YourVersion:     req.Version,")
	fmt.Println("    }")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  ★ 这次额外查询只在冲突路径上发生（低频），不影响正常性能。")
	fmt.Println("    而它的收益是「响应体能告诉前端真实的版本号」—— d21 的主题。")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：struct 的零值陷阱")
	// -----------------------------------------------------------------
	fmt.Println("GORM 的 `Updates(struct)` 会**忽略零值字段**，这是 Go 特有的坑：")
	fmt.Println()
	fmt.Println("```go")
	fmt.Println("// 想把 note 改成空字符串（清空备注）")
	fmt.Println("tx.Model(&Txn{}).Where(...).Updates(Txn{Note: \"\"})")
	fmt.Println("// ↑ 生成的 SQL 里**没有** note 这一列 → 清空失败")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("原因：Go 的零值是 `\"\"`、`0`、`false`、`nil`，")
	fmt.Println("GORM 用 `reflect` 判断「是否零值」，然后跳过。")
	fmt.Println()
	fmt.Println("TS 也有类似问题但方向相反：")
	fmt.Println("```ts")
	fmt.Println("await prisma.update({ where: {id}, data: { note: \"\" } })   // ✅ 空字符串能写进去")
	fmt.Println("```")
	fmt.Println("  因为 Prisma 用的是 `undefined` 表示「不更新」，而 `\"\"` 是有值的。")
	fmt.Println("  TS 有 `undefined` 这个「无」的值，Go 没有 —— 所以要用 `map` 绕过。")
	fmt.Println()
	fmt.Println("★ 所以本项目的规矩：**所有乐观锁更新一律用 map + gorm.Expr**。")
	fmt.Println("  这不是风格偏好，是因为 struct 版本同时有两个 bug：")
	fmt.Println("    ① 零值字段被忽略（清空备注失败）")
	fmt.Println("    ② 写不了 version + 1（只能写死，d20 第 3 节证明它会失效）")
	fmt.Println()
	fmt.Println("  ★ 顺带一个 Go 特有的好处：map 的 key 不存在时不会被跳过，")
	fmt.Println("    所以 `map[string]any{\"note\": \"\"}` 能正确写入空字符串。")
	fmt.Println("    这在写「部分更新」（PATCH）接口时非常关键。")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "真跑：冲突时 Error=nil、RowsAffected=0"},
		{true, "三步判断模式（Error → RowsAffected → 成功）写进代码骨架"},
		{true, "真跑三种错误写法：Error 判断 / 写死 version / 传错 version"},
		{true, "真跑「写死 version」连续 5 次会卡在第 2 次"},
		{true, "GORM 三种写法 DryRun 真实生成（map+Expr / struct 陷阱 / Raw）"},
		{true, "禁止 Updates(struct)：零值忽略 + 写不了 version+1"},
		{true, "RowsAffected==0 的三种原因区分：404 / 404 / 409"},
		{true, "冲突路径上多查一次，拿到真实版本号（d21 用）"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("★ 今天最该记住的一句：")
		fmt.Println("  冲突的信号是 **RowsAffected == 0**，不是 Error。")
		fmt.Println("  这一个细节错了，整个乐观锁静默失效，而且没有任何报错。")
		fmt.Println()
		fmt.Println("W41 d20 通过。明天跑出 409 的完整响应体。")
	}
}

func verdict(rows int) string {
	if rows == 1 {
		return "成功"
	}
	return "冲突（影响 0 行）"
}

// =====================================================================
// W41 d23：★ 幂等的实现 —— UNIQUE(family_id, client_request_id) + 冲突时返回已有。
//
// d22 讲了「为什么要幂等」，今天讲「怎么实现才正确」。
//
// 实现里有三个非显然的地方，每一个都有真实的坑：
//   ① 唯一索引怎么建（普通 vs 部分 —— d26 讲透原因）
//   ② 23505 冲突后**怎么拿到已存在的那一行**（不能用 Error 里的信息，要重查）
//   ③ 「先查后插」+ 唯一索引的组合（为什么两者都需要）
//
// 第 3 节真跑：两个 goroutine **同时**用同一个 crid 提交。
//   只有 1 行数据，2 次请求都返回 200，且 txn_id 相同。
//   这是 S10 判据 2 的核心断言。
//
// 本机没有 Postgres。内存模拟 + 唯一约束检查器 + GORM DryRun 真实 SQL。
// =====================================================================

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func dryDB() *gorm.DB {
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://svc_finance:dev_password@localhost:5432/homecube?sslmode=disable",
	}), &gorm.Config{
		DryRun:               true,
		DisableAutomaticPing: true,
		NowFunc:              func() time.Time { return fixedNow },
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		panic(err)
	}
	return db
}

// =====================================================================
// 内存实现：唯一约束检查器（照抄 Postgres 的 UNIQUE(family_id, crid)）
// =====================================================================

var ErrUniqueViolation = errors.New("duplicate key value violates unique constraint \"uniq_txn_family_crid\"")

type Account struct {
	ID           string
	Name         string
	BalanceCents int64
	Version      int
	mu           *sync.Mutex
}

type Txn struct {
	ID        string
	FamilyID  string
	AccountID string
	Amount    int64
	Note      string
	CRID      string
	Hash      string
	CreatedAt time.Time
}

type DB struct {
	Accounts []*Account
	Txns     []*Txn
	mu       sync.Mutex // 模拟表级元数据锁
	seq      int
	// 模拟 DB 唯一索引的原子性：插入 crid 检查与写入在同一临界区
	idemMu sync.Mutex
}

func newDB() *DB { return &DB{} }

func (d *DB) acc(name string, bal int64) *Account {
	a := &Account{ID: fmt.Sprintf("acc-%d", len(d.Accounts)+1), Name: name,
		BalanceCents: bal, Version: 1, mu: &sync.Mutex{}}
	d.Accounts = append(d.Accounts, a)
	return a
}

func (d *DB) find(id string) *Account {
	for _, a := range d.Accounts {
		if a.ID == id {
			return a
		}
	}
	return nil
}

func (d *DB) findByCrid(fam, crid string) *Txn {
	for _, t := range d.Txns {
		if t.FamilyID == fam && t.CRID == crid {
			return t
		}
	}
	return nil
}

func (d *DB) countTxns() int { return len(d.Txns) }

type outcome struct {
	From    string
	Status  int
	Code    int
	TxnID   string
	Balance int64
	Detail  string
}

func hashOf(accID, note string, amount int64) string {
	h := sha256.Sum256([]byte(fmt.Sprintf("%s|%s|%d", accID, note, amount)))
	return hex.EncodeToString(h[:])[:16]
}

// CreateExpense：完整的幂等实现
func (d *DB) CreateExpense(accID, note string, amount int64, crid string) outcome {
	h := hashOf(accID, note, amount)
	acc := d.find(accID)

	// ── 第一步：先查（快路径，命中就不开事务）──
	if exist := d.findByCrid(famA, crid); exist != nil {
		if exist.Hash != h {
			return outcome{Status: 409, Code: 40011, TxnID: exist.ID,
				Balance: acc.BalanceCents, Detail: "同 crid 但 payload 不同 → 拒绝"}
		}
		return outcome{Status: 200, Code: 0, TxnID: exist.ID,
			Balance: acc.BalanceCents, Detail: "命中幂等，返回首次结果"}
	}

	// ── 第二步：开事务做真实写入 ──
	acc.mu.Lock()
	defer acc.mu.Unlock()

	// 事务内再查一次（★ 关键：并发时另一个 goroutine 可能刚插完）
	if exist := d.findByCrid(famA, crid); exist != nil {
		if exist.Hash != h {
			return outcome{Status: 409, Code: 40011, TxnID: exist.ID,
				Balance: acc.BalanceCents, Detail: "事务内发现 crid 已被占用 → 拒绝"}
		}
		return outcome{Status: 200, Code: 0, TxnID: exist.ID,
			Balance: acc.BalanceCents, Detail: "事务内发现已存在 → 返回首次结果"}
	}

	// 模拟 INSERT：唯一约束检查 + 写入在同一临界区（数据库就是这样原子的）
	d.idemMu.Lock()
	for _, t := range d.Txns {
		if t.FamilyID == famA && t.CRID == crid {
			d.idemMu.Unlock()
			// 23505：唯一约束冲突
			if t.Hash != h {
				return outcome{Status: 409, Code: 40011, TxnID: t.ID,
					Balance: acc.BalanceCents, Detail: "23505 唯一约束冲突"}
			}
			return outcome{Status: 200, Code: 0, TxnID: t.ID,
				Balance: acc.BalanceCents, Detail: "23505 → 重查后返回首次结果"}
		}
	}
	d.seq++
	newTxn := &Txn{ID: fmt.Sprintf("txn-%04d", d.seq), FamilyID: famA, AccountID: accID,
		Amount: amount, Note: note, CRID: crid, Hash: h, CreatedAt: fixedNow}
	d.Txns = append(d.Txns, newTxn)
	d.idemMu.Unlock()

	acc.BalanceCents -= amount
	acc.Version++

	return outcome{Status: 201, Code: 0, TxnID: newTxn.ID,
		Balance: acc.BalanceCents, Detail: "真实执行：写流水 + 扣余额"}
}

