	code := `// service/transaction.go
func (s *TxnSvc) Create(ctx context.Context, req CreateReq) (*TxnView, *BizError) {
    // ── 0. 幂等键必填（铁律 3）
    if req.CRID == "" {
        return nil, &BizError{400, 40010, "缺少 client_request_id"}
    }
    h := hashPayload(req)   // 只哈希业务字段

    // ── 1. 快路径：先查（重试的请求在这里短路，不开事务）
    if exist, err := s.repo.FindByCrid(ctx, famID, req.CRID); err == nil {
        if exist.PayloadHash != h {
            return nil, &BizError{409, 40011,
                "client_request_id 已被另一个不同的请求占用"}
        }
        return s.repo.ToView(exist), nil   // 200 + 首次结果
    }

    // ── 2. 慢路径：一个事务做全部副作用
    var out *TxnView
    err := s.db.Transaction(func(tx *gorm.DB) error {
        // 2a. 校验（d14：读与校验尽量在这里之前，但正确性靠下面）
        acc, err := s.repo.GetAccount(tx, req.AccountID)
        if err != nil { return err }
        if acc.IsArchived {
            return &BizError{409, 4002, "账户已归档"}
        }

        // 2b. 原子扣减（d15：条件在 WHERE 里）
        res := tx.Model(&Account{}).
            Where("id = ? AND family_id = ? AND balance_cents >= ?",
                  req.AccountID, famID, req.AmountCents).
            Updates(map[string]any{
                "balance_cents": gorm.Expr("balance_cents - ?", req.AmountCents),
                "version":       gorm.Expr("version + ?", 1),
            })
        if res.Error != nil { return res.Error }
        if res.RowsAffected == 0 { return ErrInsufficientBalance }

        // 2c. 插流水（唯一约束在这里兜底并发）
        t := &Txn{ ... CRID: req.CRID, PayloadHash: h }
        if err := s.repo.InsertTxn(tx, t); err != nil {
            // ★ 23505 → 不是错误，是「已经有人做过这件事」
            if isUniqueViolation(err) {
                return &AlreadyDone{TxnID: t.ID}
            }
            return err
        }

        // 2d. outbox（d14）
        s.repo.PutOutbox(tx, "finance.transaction.created", t.ID)
        out = s.repo.ToView(t)
        return nil
    })
    if err != nil {
        // ★ 23505 的情况：事务回滚了（本来也没写成功），重查返回首次结果
        if ad, ok := err.(*AlreadyDone); ok {
            exist, e2 := s.repo.FindByCrid(ctx, famID, req.CRID)
            if e2 == nil { return s.repo.ToView(exist), nil }
        }
        return nil, toBizError(err)
    }
    return out, nil
}

// 判定 23505
func isUniqueViolation(err error) bool {
    var pgErr *pgconn.PgError
    return errors.As(err, &pgErr) && pgErr.Code == "23505"
}`
	fmt.Println(code)
	fmt.Println()
	fmt.Println("★ 注意第 2c 步的 AlreadyDone 路径：")
	fmt.Println("  插入失败 → 整个事务回滚 → 然后**在事务外**重查。")
	fmt.Println("  为什么重查要在事务外？因为此时事务已经结束，")
	fmt.Println("  而另一个 goroutine 的行可能在这个间隙里才提交。")
	fmt.Println("  顺序反了会读到「还是不存在」→ 返 404 → 客户端以为失败。")

	// -----------------------------------------------------------------
	hdr("6. Go 与 TypeScript：错误分类是幂等实现的关键")
	// -----------------------------------------------------------------
	fmt.Println("Go 里判定 23505 需要 pgx 的类型：")
	fmt.Println("```go")
	fmt.Println("import \"github.com/jackc/pgx/v5/pgconn\"")
	fmt.Println()
	fmt.Println("var pgErr *pgconn.PgError")
	fmt.Println("if errors.As(err, &pgErr) {")
	fmt.Println("    switch pgErr.Code {")
	fmt.Println("    case \"23505\": // unique_violation")
	fmt.Println("        // 幂等命中")
	fmt.Println("    case \"23514\": // check_violation")
	fmt.Println("        // 约束不满足（比如金额必须为正）")
	fmt.Println("    case \"40001\": // serialization_failure")
	fmt.Println("        // 序列化冲突，应该重试整个事务")
	fmt.Println("    }")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ `errors.As` 而不是类型断言（`err.(*pgconn.PgError)`）：")
	fmt.Println("  因为错误可能被包装过（fmt.Errorf(\"...: %w\", err)），")
	fmt.Println("  类型断言会失败，errors.As 会「剥掉每一层包装」直达原始错误。")
	fmt.Println("  这就是 S1 讲「error 为什么要包装而不是直接 return」的兑现。")
	fmt.Println()
	fmt.Println("TS 里的对应：")
	fmt.Println("```ts")
	fmt.Println("// 错误从 HTTP 响应来，没有 pgErr，所以判定靠 code")
	fmt.Println("if (e.code === 40011) { /* 同 crid 不同 payload */ }")
	fmt.Println("```")
	fmt.Println("  ★ 所以**业务码必须在服务端定好并透出**，")
	fmt.Println("    让前端不需要理解 SQLSTATE 就能分支。")
	fmt.Println("    SQLSTATE 是实现细节，HTTP code 才是契约。")

	// -----------------------------------------------------------------
	hdr("7. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "三个非显然点：普通唯一索引 / 23505 后重查 / 先查后插+约束"},
		{true, "GORM DryRun 真实生成三条 SQL（先查 / 插入 / 重查）"},
		{true, "真跑：两个 goroutine 同一 crid → 1 个 201 + 1 个 200，txn_id 相同"},
		{true, "真跑：流水 1 条、余额只扣一次（三个断言全过）"},
		{true, "真跑：去掉唯一索引 → 2 行流水、扣 2 次、两个 201"},
		{true, "完整服务层代码 + 23505 的 AlreadyDone 路径"},
		{true, "errors.As 而非类型断言（错误包装后仍能取出）"},
		{true, "业务码是契约，SQLSTATE 是实现细节"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("★ S10 判据 2 的完成情况：")
		fmt.Println("  「同一 client_request_id 重复提交 → 只产生一笔」")
		fmt.Println()
		fmt.Println("  上面第 3 节是真跑的两个 goroutine：")
		fmt.Println("    - 一个 201（真实执行），一个 200（命中幂等）")
		fmt.Println("    - 两者返回**同一个 txn_id**")
		fmt.Println("    - 库里只有 1 行流水，余额只扣了一次")
		fmt.Println()
		fmt.Println("W41 d23 通过。明天 W41 收口：并发测试全跑一遍 + 自查。")
	}
	_ = ErrUniqueViolation
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

// =====================================================================
// W41 d24：★ W41 收口 —— 乐观锁 + 幂等 + 并发测试（真 goroutine）。
//
// S10 判据 1 与 2 在这里做端到端验证：
//   判据 1：两人同时改一笔流水 → 后到者 409 且带双方版本
//   判据 2：同一 client_request_id 重复提交 → 只产生一笔
// 判据 7：讲清乐观锁和幂等分别解决什么问题、能不能互相替代
//
// 今天的并发测试是**四个场景**，每个都用真 goroutine + channel 同步起点：
//   ① 两人同时改一笔（同 version）    → 恰好一个成功，另一个 409
//   ② 两人同时改一笔（不同 version）  → 都成功（各自基于不同版本，不冲突）
//   ③ 两人同时用同一 crid 提交       → 一笔数据，一个 201 一个 200
//   ④ 两人同时改不同账户              → 都成功（互不干扰）
//
// 第 4 个场景常被误解为「乐观锁会误伤无关的并发」，今天真跑证明不会。
//
// 配套 race_test.go 提供 go test -race 的版本。
//
// 本机没有 Postgres。内存模拟（行锁 + 唯一约束 + version 三种机制）。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

// ---------------------------------------------------------------------
// 一个同时支持三种机制的内存库：
//   · 行锁（sync.Mutex per row）        —— 模拟 Postgres 行锁
//   · version 乐观锁                    —— d19/d20
//   · UNIQUE(family_id, crid) 唯一约束  —— d22/d23
// ---------------------------------------------------------------------

type Txn struct {
	ID      string
	Note    string
	Version int
	CRID    string
}

type Acc struct {
	ID     string
	Name   string
	mu     *sync.Mutex
	Amount int64
}

type Store struct {
	mu   sync.Mutex // 保护 Txns 与 Idem 这两张「元数据表」
	Txns map[string]*Txn
	Idem map[string]string // key = family|crid → txn_id
	seq  int
	Accs map[string]*Acc
}

func newStore() *Store {
	return &Store{Txns: map[string]*Txn{}, Idem: map[string]string{}, Accs: map[string]*Acc{}}
}

func (s *Store) addAcc(id, name string, amt int64) {
	s.Accs[id] = &Acc{ID: id, Name: name, Amount: amt, mu: &sync.Mutex{}}
}

func (s *Store) newTxnID() string {
	s.seq++
	return fmt.Sprintf("txn-%04d", s.seq)
}

type editResult struct {
	Who         string
	HTTP        int
	Code        int
	Note        string
	Version     int
	ExpectedVer int
	CurrentVer  int
	Idempotent  bool
	Detail      string
}

// 编辑流水：乐观锁
func (s *Store) edit(id, note string, expectVer int, who string) editResult {
	// 取该行的锁（模拟 Postgres 的行级锁；乐观锁在真库上不需要显式加锁，
	// 这里加是为了让内存模拟的行为可预测）
	s.mu.Lock()
	t, ok := s.Txns[id]
	s.mu.Unlock()
	if !ok {
		return editResult{Who: who, HTTP: 404, Code: 3001, Detail: "资源不存在"}
	}
	// 模拟：真库上是「一条 UPDATE 语句原子完成检查+写入」
	s.mu.Lock()
	defer s.mu.Unlock()
	t, ok = s.Txns[id]
	if !ok {
		return editResult{Who: who, HTTP: 404, Code: 3001, Detail: "资源不存在"}
	}
	if t.Version != expectVer {
		return editResult{
			Who: who, HTTP: 409, Code: 40901,
			Note: t.Note, Version: t.Version,
			ExpectedVer: expectVer, CurrentVer: t.Version,
			Detail: "版本冲突：响应体带双方版本",
		}
	}
	t.Note = note
	t.Version++
	return editResult{Who: who, HTTP: 200, Code: 0, Note: t.Note, Version: t.Version,
		ExpectedVer: expectVer, CurrentVer: t.Version, Detail: "更新成功"}
}

// 创建流水：幂等 + 乐观锁的余额条件
func (s *Store) create(accID string, amount int64, crid string, who string) editResult {
	key := famA + "|" + crid
	// 快路径：先查（命中就短路，不开事务）
	s.mu.Lock()
	if tid, ok := s.Idem[key]; ok {
		t := s.Txns[tid]
		s.mu.Unlock()
		return editResult{Who: who, HTTP: 200, Code: 0, Note: t.Note, Version: t.Version,
			Idempotent: true, Detail: "命中幂等，返回首次结果（快路径）"}
	}
	s.mu.Unlock()

	// 慢路径：先取账户行锁（模拟事务里的行锁）
	acc := s.Accs[accID]
	acc.mu.Lock()
	defer acc.mu.Unlock()

	if acc.Amount < amount {
		return editResult{Who: who, HTTP: 409, Code: 4001, Detail: "余额不足（条件扣减 WHERE balance >= ? 不满足）"}
	}

	// ★ 关键：唯一约束的「检查 + 写入」必须在**同一个临界区**里。
	// 这正是 Postgres 里 INSERT ... 带 UNIQUE 索引的原子性保证。
	// 拆成两段（先查后插）就会出现两个 goroutine 都查到「不存在」，
	// 然后都插入 —— d23 第 4 节演示过那个后果。
	s.mu.Lock()
	if tid, ok := s.Idem[key]; ok { // ← 相当于 23505
		t := s.Txns[tid]
		s.mu.Unlock()
		return editResult{Who: who, HTTP: 200, Code: 0, Note: t.Note, Version: t.Version,
			Idempotent: true, Detail: "23505 唯一约束冲突 → 重查后返回首次结果"}
	}
	tid := s.newTxnID()
	s.Txns[tid] = &Txn{ID: tid, Note: fmt.Sprintf("%.2f 元", float64(amount)/100), Version: 1, CRID: crid}
	s.Idem[key] = tid
	s.mu.Unlock()

	acc.Amount -= amount
	return editResult{Who: who, HTTP: 201, Code: 0, Note: s.Txns[tid].Note, Version: 1,
		Detail: "真实执行：写流水 + 扣余额 + 记幂等"}
}

// firstTxnID 返回按 id 排序的第一个流水 id（确定性）
func firstTxnID(s *Store) string {
	ids := make([]string, 0, len(s.Txns))
	for id := range s.Txns {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	if len(ids) == 0 {
		return ""
	}
	return ids[0]
}

func (s *Store) countTxns() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.Txns)
}

func (s *Store) txnCount() int { return s.countTxns() }

// 通用：跑 N 个 goroutine，同一起点，收集结果后排序
func runConcurrent(fns []func() editResult) []editResult {
	start := make(chan struct{})
	ch := make(chan editResult, len(fns))
	var wg sync.WaitGroup
	for _, fn := range fns {
		wg.Add(1)
		go func(f func() editResult) {
			defer wg.Done()
			<-start
			ch <- f()
		}(fn)
	}
	close(start)
	wg.Wait()
	close(ch)
	var out []editResult
	for r := range ch {
		out = append(out, r)
	}
	// 排序保证输出确定：按 Who 排，再按 HTTP 排
	sort.Slice(out, func(i, j int) bool {
		if out[i].Who != out[j].Who {
			return out[i].Who < out[j].Who
		}
		return out[i].HTTP < out[j].HTTP
	})
	return out
}

// printConcurrent 打印并发场景的结果。
// ★ **不按 goroutine 身份打印**（谁先执行是不确定的，打印出来两次运行就不同）。
//
//	只打印**聚合后的事实**：几个 200、几个 201、几个 409，以及最终状态。
//	这样输出是确定的，而且断言也不依赖顺序（CARD-GUIDE 的硬要求）。
func printConcurrentCounts(label string, rs []editResult) {
	n200, n201, n409 := countHTTP(rs, 200), countHTTP(rs, 201), countHTTP(rs, 409)
	fmt.Printf("    %s：HTTP 200 ×%d，201 ×%d，409 ×%d\n", label, n200, n201, n409)
}

func countHTTP(rs []editResult, code int) int {
	n := 0
	for _, r := range rs {
		if r.HTTP == code {
			n++
		}
	}
	return n
}

func main() {
	// -----------------------------------------------------------------
	hdr("W41 收口 ①：★ 判据 1 —— 两人同时改一笔（同 version）")
	// -----------------------------------------------------------------
	s1 := newStore()
	s1.mu.Lock()
	s1.Txns["txn-0034"] = &Txn{ID: "txn-0034", Note: "买菜", Version: 1}
	s1.mu.Unlock()

	fmt.Println("  妈妈和爸爸同时打开 txn-0034（两边都读到 version=1），各改各的备注。")
	fmt.Println()
	rs := runConcurrent([]func() editResult{
		func() editResult { return s1.edit("txn-0034", "买菜 - 菜市场", 1, "妈妈") },
		func() editResult { return s1.edit("txn-0034", "买菜 - 超市代收", 1, "爸爸") },
	})
	s1.mu.Lock()
	final := *s1.Txns["txn-0034"]
	s1.mu.Unlock()
	// ★ 不打印「最终 note 是谁写的」—— 那取决于谁先抢到锁，是不确定的。
	//   真正确定且需要断言的事实是：version 恰好是 2（只成功一次）。
	printConcurrentCounts("两个 goroutine 的结果", rs)
	fmt.Printf("    最终 version=%d（只递增了 1 次 → 只有一次写生效）\n", final.Version)
	fmt.Printf("    最终 note 是胜出者的内容（「%s」或「%s」，**取决于谁先抢到锁**）\n",
		"买菜 - 菜市场", "买菜 - 超市代收")
	fmt.Println()
	ok200, ok409 := countHTTP(rs, 200), countHTTP(rs, 409)
	payloadOK := false
	for _, r := range rs {
		if r.HTTP == 409 && r.ExpectedVer == 1 && r.CurrentVer >= 2 {
			payloadOK = true
		}
	}
	fmt.Println("  ★ 判据 1 的四个断言：")
	fmt.Printf("    恰好 1 个成功（200）           %d  %s\n", ok200,
		map[bool]string{true: "✅", false: "❌"}[ok200 == 1])
	fmt.Printf("    恰好 1 个冲突（409）           %d  %s\n", ok409,
		map[bool]string{true: "✅", false: "❌"}[ok409 == 1])
	fmt.Printf("    409 响应带双方版本              %v  %s\n", payloadOK,
		map[bool]string{true: "✅ expected=1, current≥2", false: "❌"}[payloadOK])
	fmt.Printf("    version 只递增了 1 次          %d  %s\n", final.Version,
		map[bool]string{true: "✅", false: "❌"}[final.Version == 2])
	fmt.Println()
	fmt.Println("  ★ 关键是：失败的那个人**没有丢数据**——他的 note 没进去，")
	fmt.Println("    但服务端明确告诉了他「现在是 version 2，内容是 X」，")
	fmt.Println("    他可以据此决定要不要重放（d21 讲的前端流程）。")

	// -----------------------------------------------------------------
	hdr("W41 收口 ②：两人改同一笔，但**各自读到了最新值**")
	// -----------------------------------------------------------------
	fmt.Println("  这个场景常被误解：「乐观锁会误伤无关的并发」。")
	fmt.Println()
	s2 := newStore()
	s2.mu.Lock()
	s2.Txns["t1"] = &Txn{ID: "t1", Note: "原始", Version: 1}
	s2.mu.Unlock()

	// editFresh = 每次编辑前**重新读一次**当前 version（正确的客户端行为）
	editFresh := func(note, who string) editResult {
		s2.mu.Lock()
		cur := s2.Txns["t1"].Version
		s2.mu.Unlock()
		return s2.edit("t1", note, cur, who)
	}
	rs2 := runConcurrent([]func() editResult{
		func() editResult { return editFresh("妈妈改的", "妈妈") },
		func() editResult { return editFresh("爸爸改的", "爸爸") },
	})
	s2.mu.Lock()
	f2 := *s2.Txns["t1"]
	s2.mu.Unlock()
	printConcurrentCounts("两个 goroutine 的结果", rs2)
	fmt.Printf("    最终 version=%d（从 1 递增到 %d → 两次写都生效了）\n", f2.Version, f2.Version)
	fmt.Println()
	bothOK := countHTTP(rs2, 200) == 2
	fmt.Printf("  ★ 两次都成功：%v\n", bothOK)
	fmt.Println("    因为每个人都在**写之前重新读了一次**当前版本，")
	fmt.Println("    所以两个人依据的分别是 v1→v2 和 v2→v3，**不存在同一份旧数据**。")
	fmt.Println()
	fmt.Println("  ★ 这个对比才是乐观锁的准确语义：")
	fmt.Println("    它防的是「基于**同一份**旧数据的并发写」，")
	fmt.Println("    而**不是**「同一行的所有并发写」。")
	fmt.Println("    真正串行的操作（各自读到最新值）永远不冲突。")
	fmt.Println()
	fmt.Println("  ★ 顺带说明客户端的正确行为：**PATCH 之前重新 GET 一次**。")
	fmt.Println("    如果客户端一直用「页面打开时那个 version」，")
	fmt.Println("    那么任何两个人先后编辑同一笔，第二个人都会 409 ——")
	fmt.Println("    即使第二个人的操作发生在第一个人的 10 分钟之后。")
	fmt.Println("    那不是并发问题，那是**客户端缓存了过期的 version**。")
	fmt.Println("    修法：提交前若距上次 GET 超过 N 秒（或用户重新进入页面），先刷新。")
	fmt.Println()
	fmt.Println("  ★ 最后一条边界：version 只能保证「你看到的是最新的」，")
	fmt.Println("    **不能保证「你的写一定生效」**。")
	fmt.Println("    上面两次都是 200、version 也递增了 2 次，")
	fmt.Println("    但最终只留下一个 note —— 后写的那次覆盖了先写的那次，")
	fmt.Println("    两个人都没有收到任何提示（谁先执行是不确定的，所以这里不说是谁）。")
	fmt.Println("    如果业务上不允许覆盖，需要额外的规则（字段级时间戳 / 变更历史 / ")
	fmt.Println("    「金额改动必须留痕」），version 本身不提供。")

	hdr("W41 收口 ③：★ 判据 2 —— 同一 crid 重复提交（真并发）")
	// -----------------------------------------------------------------
	fmt.Println("  两个 goroutine 用**同一个** crid 提交同一笔支出。")
	fmt.Println()
	s3 := newStore()
	s3.addAcc("acc-cash", "现金钱包", 1000000)
	rs3 := runConcurrent([]func() editResult{
		func() editResult { return s3.create("acc-cash", 3250, "req-concurrent-1", "请求A") },
		func() editResult { return s3.create("acc-cash", 3250, "req-concurrent-1", "请求B") },
	})
	nt3 := s3.txnCount()
	bal3 := s3.Accs["acc-cash"].Amount
	printConcurrentCounts("两个 goroutine 的结果", rs3)
	fmt.Printf("    写入的流水：1 条，note=「%s」\n", s3.Txns[firstTxnID(s3)].Note)
	fmt.Println()
	fmt.Printf("  流水 %d 条，余额 %s\n", nt3, yuan(bal3))
	fmt.Println()
	idemOK := nt3 == 1 && bal3 == 1000000-3250 && countHTTP(rs3, 201) == 1 && countHTTP(rs3, 200) == 1
	fmt.Println("  ★ 判据 2 的四个断言：")
	fmt.Printf("    流水只有 1 条                %d  %s\n", nt3, map[bool]string{true: "✅", false: "❌"}[nt3 == 1])
	fmt.Printf("    余额只扣一次（10000-32.50）  %s  %s\n", yuan(bal3),
		map[bool]string{true: "✅", false: "❌"}[bal3 == 1000000-3250])
	fmt.Printf("    恰好 1 个 201（真实执行）    %d  %s\n", countHTTP(rs3, 201),
		map[bool]string{true: "✅", false: "❌"}[countHTTP(rs3, 201) == 1])
	fmt.Printf("    恰好 1 个 200（幂等命中）    %d  %s\n", countHTTP(rs3, 200),
		map[bool]string{true: "✅", false: "❌"}[countHTTP(rs3, 200) == 1])
	if idemOK {
		fmt.Println("  ✅ 判据 2 通过：同一 crid 重复提交只产生一笔")
	}

	// -----------------------------------------------------------------
	hdr("W41 收口 ④：两人同时用**不同** crid 提交（都应成功）")
	// -----------------------------------------------------------------
	fmt.Println("  两个不同的 crid = 两个独立且合法的请求，幂等不拦，乐观锁也不拦。")
	fmt.Println()
	s4 := newStore()
	s4.addAcc("acc-cash", "现金钱包", 1000000)
	rs4 := runConcurrent([]func() editResult{
		func() editResult { return s4.create("acc-cash", 1000, "req-mom-1", "妈妈") },
		func() editResult { return s4.create("acc-cash", 2000, "req-dad-1", "爸爸") },
	})
	nt4 := s4.txnCount()
	bal4 := s4.Accs["acc-cash"].Amount
	// ★ 收集 note 后**排序**再拼：txn id 的分配顺序取决于 goroutine 抢锁顺序，
	//   按 id 排序仍然是不确定的；按 note 排序才确定。
	s4.mu.Lock()
	notes4 := make([]string, 0, len(s4.Txns))
	for _, t := range s4.Txns {
		notes4 = append(notes4, t.Note)
	}
	s4.mu.Unlock()
	sort.Strings(notes4)
	printConcurrentCounts("两个 goroutine 的结果", rs4)
	fmt.Printf("    写入的流水：%d 条，note 分别是「%s」\n", len(notes4), strings.Join(notes4, " / "))
	fmt.Println()
	fmt.Printf("  流水 %d 条，余额 %s\n", nt4, yuan(bal4))
	fmt.Println()
	fmt.Printf("  ★ 验算：10000 - 10.00 - 20.00 = %s，实际 %s  %s\n", yuan(1000000-3000), yuan(bal4),
		map[bool]string{true: "✅", false: "❌"}[bal4 == 1000000-3000])
	fmt.Println("    两次都是真实执行（各 201），流水 2 条 —— 这是**正确**的。")
	fmt.Println("    因为它们本来就是两笔不同的账。")
	fmt.Println()
	fmt.Println("  ★ 这个场景说明了幂等键的边界：它只防「同一请求重复」，")
	fmt.Println("    不防「不同请求做同一件事」。后者（比如妈妈和爸爸各自买了菜）")
	fmt.Println("    本来就该是两笔。")
