	for _, r := range rsX {
		fmt.Printf("    %s：HTTP %d %s\n", r.Who, r.HTTP,
			map[bool]string{true: "（用户看到「数据已被他人修改」，但没人改）", false: ""}[r.HTTP == 409])
	}
	fmt.Println("    ❌ 客户端收到假的 409：他自己点了两下，却收到「数据被他人修改」")
	fmt.Println("       而且重试多少次都是 409（version 已经变了）")
	fmt.Println()
	fmt.Println("  场景 Y：只有幂等，没有乐观锁（两人同时改同一笔）")
	sy := newStore()
