	sy.Idem[famA+"|crid-mom"] = "t1"
	sy.Idem[famA+"|crid-dad"] = "t1"
	sy.mu.Unlock()
	// 两人用不同 crid「编辑」同一行，没有 version 条件
	noLockEdit := func(note, who string) editResult {
		sy.mu.Lock()
		defer sy.mu.Unlock()
		t := sy.Txns["t1"]
		t.Note = note
		t.Version++
		return editResult{Who: who, HTTP: 200, Code: 0, Note: t.Note, Version: t.Version,
			Detail: "无条件写入（没有 version 检查）"}
	}
	rsY := runConcurrent([]func() editResult{
		func() editResult { return noLockEdit("妈妈改的", "妈妈") },
		func() editResult { return noLockEdit("爸爸改的", "爸爸") },
	})
	sy.mu.Lock()
	fY := sy.Txns["t1"]
	sy.mu.Unlock()
	printConcurrentCounts("两个 goroutine 的结果", rsY)
	fmt.Printf("    最终 version=%d（递增了 2 次）\n", fY.Version)
	fmt.Println()
	fmt.Println("  ❌ 两次都 200，version 也递增了，但只有一个 note 留下了 ——")
