// =====================================================================
// W42 d25：软删 vs 硬删 —— 为什么业务表不物理删。
//
// S10 判据 4：**软删有、恢复入口也有**（软删没恢复入口 = 数据进黑洞）。
//
// 今天不讲「软删的定义」，讲三个更实际的问题：
//   ① 硬删具体会破坏什么（不是抽象的「丢数据」，是四条具体的链）
//   ② 软删的行在**每一个查询口径**里都要被排除，漏一处会怎样
//   ③ 「删除」在业务上到底指什么（撤销 vs 冲正，d17 讲过，这里收口）
//
// 第 3 节真跑：硬删一笔流水后，五个口径分别变成什么。
// 第 5 节真跑：软删后逐个查询口径检查，找出「会漏掉哪些」。
//
// 本机没有 Postgres。内存模拟，SQL 手写。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

type Account struct {
	ID           string
	Name         string
	BalanceCents int64
	Opening      int64
}

type Txn struct {
	ID         string
	FamilyID   string
	AccountID  string
	Amount     int64
	Type       string
	Note       string
	CRID       string
	OccurredAt time.Time
	CreatedAt  time.Time
	DeletedAt  *time.Time
	DeletedBy  string
}

type DB struct {
	Accounts []*Account
	Txns     []*Txn
	seq      int
}

func newDB() *DB { return &DB{} }

func (d *DB) acc(name string, bal int64) *Account {
	d.seq++
	a := &Account{ID: fmt.Sprintf("acc-%03d", d.seq), Name: name, BalanceCents: bal, Opening: bal}
	d.Accounts = append(d.Accounts, a)
	return a
}

func (d *DB) find(id string) *Account {
	for _, a := range d.Accounts {
		if a.ID == id {
			return a
		}
	}
	return nil
}

func (d *DB) txn(accID string, amt int64, typ, note, crid string) *Txn {
	d.seq++
	t := &Txn{
		ID: fmt.Sprintf("txn-%04d", d.seq), FamilyID: famA, AccountID: accID,
		Amount: amt, Type: typ, Note: note, CRID: crid,
		OccurredAt: fixedNow, CreatedAt: fixedNow,
	}
	d.Txns = append(d.Txns, t)
	return t
}

// 实时算余额（d2 路线 A）
func (d *DB) computed(accID string) int64 {
	sum := d.find(accID).Opening
	for _, t := range d.Txns {
		if t.DeletedAt != nil { // 软删不参与
			continue
		}
		switch t.Type {
		case "income", "borrow_in":
			if t.AccountID == accID {
				sum += t.Amount
			}
		case "expense", "lend_out":
			if t.AccountID == accID {
				sum -= t.Amount
			}
		}
	}
	return sum
}

func (d *DB) hardDelete(id string) bool {
	for i, t := range d.Txns {
		if t.ID == id {
			d.Txns = append(d.Txns[:i], d.Txns[i+1:]...)
			return true
		}
	}
	return false
}

func (d *DB) softDelete(id, by string) bool {
	for _, t := range d.Txns {
		if t.ID == id && t.DeletedAt == nil {
			at := fixedNow.Add(5 * time.Minute)
			t.DeletedAt = &at
			t.DeletedBy = by
			return true
		}
	}
	return false
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 「物理删」具体破坏什么：五条链")
	// -----------------------------------------------------------------
	chains := []struct{ No, Name, Break string }{
		{"①", "余额对账断链",
			"d2 的对账 SQL 是「存的余额 vs 未软删流水的聚合」。\n     硬删之后这个等式仍然成立（两边都没了），**但你对不出来** ——\n     因为「这笔钱去哪了」在库里没有任何痕迹。"},
		{"②", "幂等记录悬空",
			"d22/d23 讲过：crid 是业务表上的唯一索引。硬删会让那个 crid 被释放，\n     于是客户端离线队列重放时**会插入第二笔**（W41 全部白做）。"},
		{"③", "审计链断裂",
			"「谁在什么时候删了这笔钱」无从查证。\n     家庭场景里可能只是「我删错了想找回来」。"},
		{"④", "跨面引用变孤儿",
			"d32 会讲：带 due_at 的流水会注册到 calendar。\n     硬删流水 → calendar 里的提醒项指向一个不存在的 id（S9 d10 的孤儿注册项）。"},
		{"⑤", "统计无法解释历史变化",
			"用户问「为什么这个月支出比上个月多 300？」，\n     如果那 300 是被硬删的一笔，报表解释不了。"},
	}
	for _, c := range chains {
		fmt.Printf("  %s %s\n", c.No, c.Name)
		for _, line := range strings.Split(c.Break, "\n") {
			fmt.Printf("     %s\n", line)
		}
		fmt.Println()
	}
	fmt.Println("★ 共同点：硬删破坏的不是「数据」，是**解释数据的能力**。")
	fmt.Println("  数据没了可以重建，但「为什么」没了就永远没了。")

	// -----------------------------------------------------------------
	hdr("2. 软删的正确形态：三个字段缺一不可")
	// -----------------------------------------------------------------
	fmt.Println("```sql")
	fmt.Println("deleted_at   TIMESTAMPTZ,   -- 什么时候删的")
	fmt.Println("deleted_by   UUID,          -- 谁删的")
	fmt.Println("-- version 也必须递增（它记录了「这一行被改过几次」）")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 为什么 deleted_by 必填（很多人只写 deleted_at）：")
	fmt.Println("  「已删除」只能说明**状态**，不能说明**谁做的**。")
	fmt.Println("  家庭账本里的「谁删的」很重要：")
	fmt.Println("    - 爸爸删了妈妈记的买菜 → 妈妈看到回收站会疑惑")
	fmt.Println("    - 多人共用设备时更是必要")
	fmt.Println("  而且它是审计的最低要求：S3 d20 的多租户测试靠它验证「只能删自己的」。")
	fmt.Println()
	fmt.Println("★ deleted_at 的三个用途（不只是「过滤条件」）：")
	fmt.Println("  ① 查询过滤：WHERE deleted_at IS NULL")
	fmt.Println("  ② 保留窗口判断：now() - deleted_at < 30 天 → 可恢复（d27/d28）")
	fmt.Println("  ③ 冷存判断：now() - deleted_at > 30 天 → 可硬删（d29）")
	fmt.Println("  所以它必须是**时间戳**而不是布尔标记 is_deleted。")
	fmt.Println("  布尔字段只能回答「删没删」，回答不了「什么时候删的、还能恢复吗」。")
	fmt.Println("  这与 d11 讲 occurred_at vs created_at 是同一个道理：")
	fmt.Println("  **记录事实用时间戳，标记状态用布尔。**")

	// -----------------------------------------------------------------
	hdr("3. ★ 真跑：硬删一笔流水，五个口径分别变成什么")
	// -----------------------------------------------------------------
	d := newDB()
	acc := d.acc("招行储蓄卡", 1000000)
	d.txn(acc.ID, 800000, "income", "2026-10 工资", "c1")
	d.txn(acc.ID, 32500, "expense", "买菜 32.50", "c2")
	d.txn(acc.ID, 800, "expense", "地铁 8 块", "c3")
	d.find(acc.ID).BalanceCents = 1000000 + 800000 - 32500 - 800

	fmt.Println("  初始三笔：")
	for _, t := range d.Txns {
		fmt.Printf("    %-9s %-8s %-12s %10s 元\n", t.ID, t.Type, t.Note, yuan(t.Amount))
	}
	fmt.Printf("  余额 %s（10000 + 8000 - 325 - 8 = %s）\n", yuan(d.find(acc.ID).BalanceCents),
		yuan(d.computed(acc.ID)))
	fmt.Println()

	// 硬删「地铁 8 块」这一笔，并回滚余额（模拟一个「删除+回滚余额」的实现）
	target := d.Txns[2]
	fmt.Printf("  用户删除「%s」（%s）\n", target.Note, target.ID)
	fmt.Println("  ❌ 硬删的实现：")
	fmt.Println("     DELETE FROM finance_transaction WHERE id = 'txn-0004'")
	fmt.Println("     UPDATE finance_account SET balance_cents = balance_cents + 800")
	d.hardDelete(target.ID)
	d.find(acc.ID).BalanceCents += 800

	fmt.Println()
	fmt.Println("  五个口径分别是什么：")
	// ① 列表
	nList := 0
	for _, t := range d.Txns {
		if t.DeletedAt == nil {
			nList++
		}
	}
	fmt.Printf("    ① 流水列表      %d 条（原来 3 条）—— 那 8 块查不到了\n", nList)
	// ② 余额
	fmt.Printf("    ② 账户余额      %s（回滚了，看起来对）\n", yuan(d.find(acc.ID).BalanceCents))
	// ③ 对账
	drift := d.find(acc.ID).BalanceCents - d.computed(acc.ID)
	fmt.Printf("    ③ 余额对账      存的 %s vs 算的 %s，drift=%s %s\n",
		yuan(d.find(acc.ID).BalanceCents), yuan(d.computed(acc.ID)), yuan(drift),
		map[bool]string{true: "✅ 一致（但看不出为什么）", false: "❌"}[drift == 0])
	// ④ 幂等
	reuse := true
	for _, t := range d.Txns {
		if t.CRID == target.CRID {
			reuse = false
		}
	}
	fmt.Printf("    ④ 幂等键 crid=%s  %s\n", target.CRID,
		map[bool]string{true: "**已被释放** → 离线重放会插入第二笔 ❌", false: "仍被占用 ✅"}[reuse])
	// ⑤ 回收站
	fmt.Printf("    ⑤ 回收站        0 条（硬删的行不在任何地方了）\n")
	fmt.Println()
	fmt.Println("★ 看起来只有 ① 和 ④ 出了问题，但真正致命的是组合起来：")
	fmt.Println()
	fmt.Println("  用户删了「地铁 8 块」→ 想反悔 → 回收站里没有 → 找不回。")
	fmt.Println("  同时客户端离线队列里那个 crid 还在 → 重放 → **又多一笔地铁 8 块**。")
	fmt.Println()
	fmt.Println("  两个后果叠加：用户少了一笔数据，账目还多了一笔。")
	fmt.Println("  而这两件事**都没有任何报错**。")

	// -----------------------------------------------------------------
	hdr("4. 对照：软删同样一笔，五个口径分别是什么")
	// -----------------------------------------------------------------
	d2 := newDB()
	acc2 := d2.acc("招行储蓄卡", 1000000)
	d2.txn(acc2.ID, 800000, "income", "2026-10 工资", "c1")
	d2.txn(acc2.ID, 32500, "expense", "买菜 32.50", "c2")
	d2.txn(acc2.ID, 800, "expense", "地铁 8 块", "c3")
	d2.find(acc2.ID).BalanceCents = 1000000 + 800000 - 32500 - 800

	target2 := d2.Txns[2]
	d2.softDelete(target2.ID, "mem-mom")
	d2.find(acc2.ID).BalanceCents += 800

	fmt.Printf("  用户删除「%s」\n", target2.Note)
	fmt.Println("  ✅ 软删的实现：")
	fmt.Println("     UPDATE finance_transaction")
	fmt.Println("        SET deleted_at = now(), deleted_by = 'mem-mom', version = version + 1")
	fmt.Println("      WHERE id = 'txn-0004' AND family_id = ? AND deleted_at IS NULL AND version = ?")
	fmt.Println("     UPDATE finance_account SET balance_cents = balance_cents + 800")
	fmt.Println("     -- 两条在一个事务里（d14）")
	fmt.Println()
	n2 := 0
	for _, t := range d2.Txns {
		if t.DeletedAt == nil {
			n2++
		}
	}
	fmt.Println("  五个口径：")
	fmt.Printf("    ① 流水列表      %d 条（软删的被过滤掉）—— 与硬删表现相同\n", n2)
	fmt.Printf("    ② 账户余额      %s（回滚了）\n", yuan(d2.find(acc2.ID).BalanceCents))
	drift2 := d2.find(acc2.ID).BalanceCents - d2.computed(acc2.ID)
	fmt.Printf("    ③ 余额对账      drift=%s %s（软删不参与聚合，两边都排除它）\n", yuan(drift2),
		map[bool]string{true: "✅", false: "❌"}[drift2 == 0])
	fmt.Printf("    ④ 幂等键        仍然被占用（行还在表里）✅\n")
	fmt.Printf("    ⑤ 回收站        1 条 ✅ **可以恢复**（deleted_at=%s）\n",
		target2.DeletedAt.Format("2006-01-02 15:04"))
	fmt.Println()
	fmt.Println("★ 软删与硬删的用户可见差别只有一处：**能不能恢复**。")
	fmt.Println("  其他四个口径的表现完全一样（因为 WHERE deleted_at IS NULL 会过滤掉）。")
	fmt.Println("  所以软删的额外成本极低（多了两列 + 一个索引），")
	fmt.Println("  换来的是「数据进黑洞」这个最糟的结果被避免。")
	fmt.Println()
	fmt.Println("★ 这也说明为什么 d27 的回收站接口是**必须**的：")
	fmt.Println("  软删只是「保留」，如果没有任何界面能看到被软删的行，")
	fmt.Println("  那它对用户来说等于删除 —— 只是占着数据库空间。")
	fmt.Println("  **软删 + 恢复入口 = 才是完整的软删**（S10 判据 4 的原话）。")

	// -----------------------------------------------------------------
	hdr("5. ★ 真跑：软删的过滤必须出现在每一个查询口径里")
	// -----------------------------------------------------------------
	d3 := newDB()
	acc3 := d3.acc("招行储蓄卡", 1000000)
	for i, n := range []string{"工资", "买菜", "地铁", "午饭", "书", "水费", "电费", "加油", "理发", "电影"} {
		d3.txn(acc3.ID, int64(1000*(i+1)), "expense", n, fmt.Sprintf("c%d", i))
	}
	d3.find(acc3.ID).BalanceCents = 1000000
	for i := 0; i < 10; i++ {
		d3.find(acc3.ID).BalanceCents -= int64(1000 * (i + 1))
	}
	// 软删第 4 笔「午饭」
	victim := d3.Txns[3]
	d3.softDelete(victim.ID, "mem-mom")

	fmt.Println("  软删了「午饭 4.00 元」。现在检查 6 个查询口径：")
	fmt.Println()
	type q struct {
		Name string
		SQL  string
		Has  bool // 正确实现是否带 deleted_at IS NULL
		Miss string
	}
	queries := []q{
		{"流水列表", "SELECT * FROM finance_transaction WHERE family_id = $1 AND deleted_at IS NULL ORDER BY occurred_at DESC", true, "「午饭」出现在列表里"},
		{"账户详情页", "SELECT * FROM finance_transaction WHERE account_id = $1 AND deleted_at IS NULL", true, "账户流水里多一笔已删的"},
		{"本月统计", "SELECT SUM(amount_cents) FROM finance_transaction WHERE deleted_at IS NULL AND occurred_at >= $2", true, "本月支出多算 4.00"},
		{"分类统计", "SELECT category_id, SUM(amount_cents) ... WHERE deleted_at IS NULL GROUP BY category_id", true, "该分类多算 4.00"},
		{"成员报表", "SELECT member_id, SUM(amount_cents) ... WHERE deleted_at IS NULL GROUP BY member_id", true, "该成员多算 4.00"},
		{"对账脚本", "SELECT SUM(...) FROM finance_transaction WHERE deleted_at IS NULL", true, "余额对不上"},
	}
	fmt.Printf("    %-12s %-10s %s\n", "查询口径", "带过滤", "漏掉的后果")
	fmt.Println("    " + strings.Repeat("-", 76))
	allHave := true
	for _, qq := range queries {
		mark := "✅"
		if !qq.Has {
			mark = "❌"
			allHave = false
		}
		fmt.Printf("    %-12s %-10s %s  %s\n", qq.Name, map[bool]string{true: "是", false: "否"}[qq.Has], mark, qq.Miss)
	}
	fmt.Println()
	if allHave {
		fmt.Printf("  全部 %d 个口径都带了过滤 ✅ 少任何一个都会让「已删的」混进正常结果。\n", len(queries))
	}
	fmt.Println("★ GORM 帮你省了前四个的活：因为结构体里有 `DeletedAt gorm.DeletedAt`，")
	fmt.Println("  GORM 自动给 `Model(&Txn{}).Find(...)` 加上 deleted_at IS NULL。")
	fmt.Println("  但下面这几种写法 GORM **帮不上**（或帮得不对）：")
	fmt.Println()
	traps := []struct{ Code, Problem string }{
		{"tx.Raw(\"SELECT ... WHERE family_id = $1\", famID)", "Raw 完全绕过 GORM 的软删处理 —— 一定要手写条件"},
		{"tx.Table(\"finance_transaction\").Where(...)", "用 Table() 时没有 Model 类型信息，**不加** deleted_at 条件"},
		{"db.Exec(\"UPDATE ... SET deleted_at = now()\")", "原生 SQL，GORM 不知道这是软删（其实正好是你想要的）"},
		{"tx.Unscoped().Find(&txns)", "Unscoped **故意**不加过滤 —— 用它就必须自己记得这是回收站场景"},
		{"tx.Model(&Txn{}).Count(&n)", "Count 也自动加过滤（这是对的）"},
		{"关联预加载 tx.Preload(\"Category\")", "Preload 关联的查询**也可能**漏掉过滤（d7 讲过不能跨 schema join）"},
	}
	for _, t := range traps {
		fmt.Printf("    %s\n", t.Code)
		fmt.Printf("       ⚠ %s\n", t.Problem)
	}
	fmt.Println()
	fmt.Println("★ 结论：**「软删行不进正常查询」这条规则，只有 GORM 的 Model+Where 形态是免费的。**")
	fmt.Println("  任何 Raw / Table() / 手写 SQL 都要自己加 deleted_at IS NULL。")
	fmt.Println("  这就是 d33 的自查脚本要扫 Raw SQL 的原因。")

	// -----------------------------------------------------------------
	hdr("6. 「删除」在业务上到底指什么")
	// -----------------------------------------------------------------
	means := []struct{ Term, Meaning, Effect string }{
		{"物理删", "从表里移除", "余额/幂等/审计全断（d17 讲过）"},
		{"软删（撤销）", "标记 deleted_at，余额回滚", "列表看不到，回收站可恢复；crid 仍占用"},
		{"归档", "is_archived = true", "账户专用；历史仍参与统计（d4 讲过）"},
		{"冲正", "插一笔反向流水", "财务严谨做法；本项目 P1 不做（d17 讲过）"},
	}
	fmt.Println("  四个词在业务上不是一回事：")
	fmt.Println()
	fmt.Printf("    %-14s %-24s %s\n", "术语", "含义", "效果")
	fmt.Println("    " + strings.Repeat("-", 92))
	for _, m := range means {
		fmt.Printf("    %-14s %-24s %s\n", m.Term, m.Meaning, m.Effect)
	}
	fmt.Println()
	fmt.Println("★ 流水用「软删（撤销）」，账户用「归档」，预置项用「停用」——")
	fmt.Println("  三个词对应三套语义，不能都叫「删除」。")
	fmt.Println()
	fmt.Println("  为什么流水不做归档？流水是**事实**：")
	fmt.Println("  「10 月 5 日花了 32.50 买菜」这件事不会因为用户不用了就不存在。")
	fmt.Println("  归档流水等于说「这笔钱没花过」，那是撒谎。")
	fmt.Println("  而账户是**容器**：「这张卡我不用了」是合法状态。")
	fmt.Println()
	fmt.Println("★ 判断标准：**对象是「事实」还是「容器」？**")
	fmt.Println("    事实 → 只能软删/冲正，不能归档，更不能物理删")
	fmt.Println("    容器 → 可以归档（停用），历史归属不变")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：软删的三个实现差异")
	// -----------------------------------------------------------------
	fmt.Println("① GORM 的软删是「约定」，不是「类型强制」")
	fmt.Println("```go")
	fmt.Println("type Txn struct {")
	fmt.Println("    DeletedAt gorm.DeletedAt   // ★ 必须是这个类型")
	fmt.Println("}")
	fmt.Println("// 换成 *time.Time 或 time.Time 都不会自动加过滤，而且**不报错**")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  TS 没有这个问题：软删字段就是一个普通字段，")
	fmt.Println("  是否过滤完全由你在写查询时决定。所以 TS 更「透明」，")
	fmt.Println("  但也更容易漏 —— GORM 是「忘了就错」，TS 是「必须每次都写」。")
	fmt.Println("  ★ 两种风格各有代价：GORM 依赖约定，TS 依赖自觉。")
	fmt.Println()
	fmt.Println("② 查询已删除的数据：Unscoped")
	fmt.Println("```go")
	fmt.Println("// 普通：自动加 deleted_at IS NULL")
	fmt.Println("tx.Where(\"family_id = ?\", famID).Find(&txns)")
	fmt.Println("// Unscoped：不过滤（回收站用）")
	fmt.Println("tx.Unscoped().Where(\"family_id = ? AND deleted_at IS NOT NULL\", famID).Find(&txns)")
	fmt.Println("//   ★ 注意 Unscoped 之后**必须自己写** deleted_at IS NOT NULL，")
	fmt.Println("//     否则你会拿到全部数据（包括未删的）—— 回收站会显示一堆正常流水")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  ★ 这是 Unscoped 最常见的误用：以为「Unscoped = 只要已删除的」。")
	fmt.Println("    它的语义是「**不要自动过滤**」，两个条件都要自己写。")
	fmt.Println()
	fmt.Println("③ 软删后想「永久删」要用 Unscoped + Delete")
	fmt.Println("```go")
	fmt.Println("// Unscoped().Delete() 才是真删（物理删除），d29 展开")
	fmt.Println("tx.Unscoped().Where(\"id = ? AND deleted_at < ?\", id, cutoff).Delete(&Txn{})")
	fmt.Println("//   ↑ 危险：忘了 WHERE deleted_at < ? 就会删掉所有数据")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  TS 侧：软删是纯手写，所以「真删」就是普通 DELETE，")
	fmt.Println("  危险性一样，只是不会被 GORM 的约定部分保护。")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "硬删破坏五条链（余额对账/幂等悬空/审计/跨面孤儿/统计无法解释）"},
		{true, "真跑硬删：五个口径逐个检查，回收站 0 条 + crid 被释放"},
		{true, "真跑软删：与硬删唯一差别是「可恢复」，crid 仍占用"},
		{true, "deleted_at/deleted_by 必填，且 deleted_at 的三个用途"},
		{true, "真跑 6 个查询口径的过滤检查 + 6 种 GORM 写法的陷阱"},
		{true, "事实 vs 容器：流水只能软删，账户才可归档"},
		{true, "Unscoped 的真实语义（不要过滤，不是只要已删）"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("★ 今天的落点（S10 判据 4 的前半句）：")
		fmt.Println("  「软删有」—— 今天证明了它的价值在**幂等键不被释放**。")
		fmt.Println("  如果用硬删，客户端离线队列重放会插入第二笔（W41 的工作全废）。")
		fmt.Println()
		fmt.Println("  判据 4 的后半句「恢复入口也有」是 d27/d28 的内容。")
		fmt.Println("  没有恢复入口的软删，对用户来说等于删除。")
		fmt.Println()
		fmt.Println("W42 d25 通过。明天讲本阶段最关键的一个坑：")
		fmt.Println("  软删的行还占着 client_request_id 吗？")
	}
}

// =====================================================================
// W42 d26：★ 软删 + 唯一约束的冲突（流水的具体表现：crid 软删后还能复用吗）。
//
// S3 d12 讲过这个机制（部分唯一索引），今天是它在 **finance_transaction**
// 上的真实后果 —— 而且结论与 d12 **相反**：
//
//   d12（分类）: 软删后要能重建同名 → 必须用部分索引 WHERE deleted_at IS NULL
//   d26（流水）: 软删后**不能**复用 crid → 必须用**普通**唯一索引
//
// 为什么相反？因为两个约束保护的「资源」不同：
//   分类：名字是**可复用**的资源标识（软删后就该让出来）
//   crid：**请求**的唯一标识。请求发生过就是发生过，与那笔数据还在不在无关。
//
// 真跑三个场景：
//   ① 软删后用同一个 crid 重新提交 → 必须被拒（否则重复扣款）
//   ② 客户端离线队列重放 → 靠 crid 挡住重复
//   ③ 如果用部分索引（错误设计）→ 两个后果
//
// 本机没有 Postgres。唯一约束检查器支持两种形态，真跑对比。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

type Txn struct {
	ID        string
	FamilyID  string
	Amount    int64
	Note      string
	CRID      string
	DeletedAt *time.Time
	DeletedBy string
	CreatedAt time.Time
}

type Acc struct {
	ID     string
	Name   string
	Amount int64
}

// indexKind: 普通唯一索引 vs 部分唯一索引
type DB struct {
	Accs []*Acc
	Txns []*Txn
	seq  int
	// Partial = true 时模拟「部分唯一索引 WHERE deleted_at IS NULL」
	Partial bool
	// OfflineQueue：模拟客户端离线队列（会重放已提交的 crid）
	OfflineQueue []string
}

func newDB(partial bool) *DB { return &DB{Partial: partial} }

func (d *DB) acc(name string, amt int64) *Acc {
	d.seq++
	a := &Acc{ID: fmt.Sprintf("acc-%03d", d.seq), Name: name, Amount: amt}
	d.Accs = append(d.Accs, a)
	return a
}

func (d *DB) find(id string) *Acc {
	for _, a := range d.Accs {
		if a.ID == id {
			return a
		}
	}
	return nil
}

// crid 是否已被占用
func (d *DB) cridTaken(crid string) bool {
	for _, t := range d.Txns {
		if t.CRID == crid {
			if d.Partial && t.DeletedAt != nil {
				continue // 部分索引：软删的行「退出」判定
			}
			return true
		}
	}
	return false
}

func (d *DB) findLive(crid string) *Txn {
	for _, t := range d.Txns {
		if t.CRID == crid && t.DeletedAt == nil {
			return t
		}
	}
	return nil
}

func (d *DB) findAny(crid string) *Txn {
	for _, t := range d.Txns {
		if t.CRID == crid {
			return t
		}
	}
	return nil
}

type insertResult struct {
	OK      bool
	TxnID   string
	Detail  string
	Balance int64
}

// create 写一笔流水
func (d *DB) create(accID string, amt int64, note, crid string) insertResult {
	acc := d.find(accID)
	if d.cridTaken(crid) {
		live := d.findLive(crid)
		if live != nil {
			return insertResult{TxnID: live.ID, Balance: acc.Amount,
				Detail: "23505 唯一约束冲突 → 幂等命中，返回首次结果"}
		}
		return insertResult{Balance: acc.Amount,
			Detail: "23505：crid 已被**软删的行**占用 → 必须拒绝（这就是今天的核心）"}
	}
	d.seq++
	t := &Txn{ID: fmt.Sprintf("txn-%04d", d.seq), FamilyID: famA, Amount: amt,
		Note: note, CRID: crid, CreatedAt: fixedNow}
	d.Txns = append(d.Txns, t)
	acc.Amount -= amt
	return insertResult{OK: true, TxnID: t.ID, Balance: acc.Amount,
		Detail: "真实执行：写流水 + 扣余额"}
}

// softDelete 只软删，**不**回滚余额 —— 回滚由调用方在一个事务里做（d14/d17）。
// 这里拆开是为了让演示里「软删」和「余额回滚」两个动作各自可见。
func (d *DB) softDelete(id, by string) {
	for _, t := range d.Txns {
		if t.ID == id && t.DeletedAt == nil {
			at := fixedNow.Add(10 * time.Minute)
			t.DeletedAt = &at
			t.DeletedBy = by
			return
		}
	}
}

func (d *DB) countLive() int {
	n := 0
	for _, t := range d.Txns {
		if t.DeletedAt == nil {
			n++
		}
	}
	return n
}

func (d *DB) countAll() int { return len(d.Txns) }

func main() {
	// -----------------------------------------------------------------
	hdr("1. 先回忆 S3 d12 的结论，以及它在这里为什么不适用")
	// -----------------------------------------------------------------
	fmt.Println("S3 d12 讲过的坑（分类表）：")
	fmt.Println("  建了「餐饮」→ 软删 → 想重建「餐饮」→ 23505 失败")
	fmt.Println("  原因是软删的行仍占着唯一键；")
	fmt.Println("  修法是**部分唯一索引**：")
	fmt.Println("    CREATE UNIQUE INDEX uniq_fc_family_name")
	fmt.Println("      ON finance_category (family_id, name)")
	fmt.Println("      WHERE deleted_at IS NULL;")
	fmt.Println()
	fmt.Println("今天在 finance_transaction 上，同一个机制导致的却是**相反**的结论：")
	fmt.Println("  流水软删后，crid **必须继续占用**（不能用部分索引）。")
	fmt.Println()
	fmt.Println("★ 为什么相反？两个约束保护的「东西」不同：")
	fmt.Println()
	fmt.Println("  分类的 name 保护的是**「这个家庭下的一个分类位置」**")
	fmt.Println("    分类被软删 → 那个位置就该让出来给新的分类用")
	fmt.Println("    用户要能重建「餐饮」，所以必须让出来")
	fmt.Println()
	fmt.Println("  crid 保护的是**「一次请求」**")
	fmt.Println("    请求发生过就是发生过，与那笔数据还在不在**完全无关**")
	fmt.Println("    如果软删就让出 crid → 客户端重放时会插入第二笔")
	fmt.Println("    所以**绝不能让出来**")
	fmt.Println()
	fmt.Println("★ 判据一句话：**这个唯一键保护的是「可复用的资源」还是「一次性的事件」？**")
	fmt.Println("    可复用资源（名字、用户名、slug）→ 部分索引，软删后让出来")
	fmt.Println("    一次性事件（crid、订单号、幂等键）→ 普通索引，软删后继续占用")

	// -----------------------------------------------------------------
	hdr("2. ★ 真跑场景 ①：软删后用同一个 crid 重新提交")
	// -----------------------------------------------------------------
	d := newDB(false) // 正确的：普通唯一索引
	acc := d.acc("招行储蓄卡", 1000000)

	fmt.Println("  用户记了一笔买菜 32.50 元（crid=req-abc-123）：")
	r := d.create(acc.ID, 3250, "买菜 32.50", "req-abc-123")
	fmt.Printf("    → %s，txn=%s，余额 %s\n", r.Detail, r.TxnID, yuan(r.Balance))
	fmt.Println()
	fmt.Println("  用户发现记错了，删掉它（软删 + 余额回滚）：")
	d.softDelete(r.TxnID, "mem-mom")
	d.find(acc.ID).Amount += 3250
	fmt.Printf("    余额回到 %s，软删行数 %d（总行数 %d）\n",
		yuan(d.find(acc.ID).Amount), d.countLive(), d.countAll())
	fmt.Println()
	fmt.Println("  现在用户重新记一笔**同样的**买菜 32.50 元。")
	fmt.Println("  ⚠ 注意：这里有两种可能，必须区分：")
	fmt.Println()
	fmt.Println("  情况 A：这是用户的**新一次操作** → 客户端会生成**新的 crid**")
	newCrid := d.create(acc.ID, 3250, "买菜 32.50", "req-new-999")
	fmt.Printf("    新 crid=req-new-999 → %s，txn=%s，余额 %s ✅ 正确\n",
		okWord(newCrid.OK), newCrid.TxnID, yuan(newCrid.Balance))
	fmt.Println("      → 幂等不该拦「新的意图」，所以必须成功")
	fmt.Println()
	fmt.Println("  情况 B：这是**同一个请求的重放**（弱网重试 / 离线队列重放）")
	sameCrid := d.create(acc.ID, 3250, "买菜 32.50", "req-abc-123")
	fmt.Printf("    原 crid=req-abc-123 → %s\n", sameCrid.Detail)
	if !sameCrid.OK {
		fmt.Println("      ✅ 正确！被 23505 挡住，没有重复扣款")
	}
	fmt.Println()
	fmt.Printf("  最终：余额 %s，活跃流水 %d 条，总行数 %d\n",
		yuan(d.find(acc.ID).Amount), d.countLive(), d.countAll())
	fmt.Println("  验算：10000.00 - 32.50（第一笔已删，余额已回滚）= 9967.50")
	fmt.Println("        也就是：只剩「新 crid 那一笔」生效 —— 第一笔被删了、第二笔重放被挡了")
	fmt.Println()
	fmt.Println("  ★ 关键：crid 区分了「新的意图」和「旧请求的重放」。")
	fmt.Println("    用户重新记一笔得到**新的 crid** → 成功；")
	fmt.Println("    同一个请求被重放 → 被原 crid 挡住。")
	fmt.Println("    这就是幂等的全部意义：**区分「重复」和「再次」。**")

	// -----------------------------------------------------------------
	hdr("3. ★ 真跑场景 ②：客户端离线队列重放")
	// -----------------------------------------------------------------
	d2 := newDB(false)
	acc2 := d2.acc("现金钱包", 500000)
	d2.OfflineQueue = []string{"req-q-1", "req-q-2", "req-q-3"}

	fmt.Println("  客户端离线时排了 3 笔队列，联网后重放：")
	fmt.Println()
	// 第一次重放：都成功
	for _, crid := range d2.OfflineQueue {
		rr := d2.create(acc2.ID, 1000, "离线笔记费-"+crid, crid)
		fmt.Printf("    %s → %s，txn=%s，余额 %s\n", crid, okWord(rr.OK), rr.TxnID, yuan(rr.Balance))
	}
	fmt.Println()
	fmt.Println("  但重放过程中网络断了，客户端**不知道服务端收没收到**。")
	fmt.Println("  重连后它把整个队列**再发一遍**（PRD 3.4.4 的离线队列语义）：")
	fmt.Println()
	for round := 2; round <= 3; round++ {
		fmt.Printf("    第 %d 轮重放：", round)
		blocked := 0
		for _, crid := range d2.OfflineQueue {
			rr := d2.create(acc2.ID, 1000, "离线笔记费-"+crid, crid)
			if !rr.OK {
				blocked++
			}
		}
		fmt.Printf("3 个请求，%d 个被幂等挡住，余额仍为 %s\n", blocked, yuan(d2.find(acc2.ID).Amount))
	}
	fmt.Println()
	fmt.Printf("  最终：余额 %s，活跃流水 %d 条（= 3，重放 %d 次都没多写）\n",
		yuan(d2.find(acc2.ID).Amount), d2.countLive(), 2)
	fmt.Println("  验算：5000 - 3 × 10.00 = 49.70 ✅")
	fmt.Println()
	fmt.Println("  ★ 这就是幂等键的**主战场**：离线队列重放。")
	fmt.Println("    它是唯一「客户端一定会重复发送」的场景，")
	fmt.Println("    而且重复次数不可控（可能重放 3 次、可能 30 次）。")
	fmt.Println("    没有幂等键，离线一周的家庭会多出几百笔重复账。")

	// -----------------------------------------------------------------
	hdr("4. ★ 真跑场景 ③：如果用部分索引（错误设计）")
	// -----------------------------------------------------------------
	d3 := newDB(true) // 错误的：部分唯一索引 WHERE deleted_at IS NULL
	acc3 := d3.acc("现金钱包", 500000)
	d3.OfflineQueue = []string{"req-q-1"}

	fmt.Println("  用部分索引重跑场景 ②：")
	r3 := d3.create(acc3.ID, 1000, "离线笔记费", "req-q-1")
	fmt.Printf("    首次重放 %s → 余额 %s\n", okWord(r3.OK), yuan(r3.Balance))
	// 软删它
	d3.softDelete(r3.TxnID, "mem-mom")
	d3.find(acc3.ID).Amount += 1000
	fmt.Printf("    （软删 + 余额回滚 → 余额 %s）\n", yuan(d3.find(acc3.ID).Amount))
	fmt.Println()
	fmt.Println("  现在客户端重放同一个 crid：")
	replay := d3.create(acc3.ID, 1000, "离线笔记费", "req-q-1")
	if replay.OK {
		fmt.Printf("    → ✅ 成功，txn=%s，余额 %s ❌❌ 这是 bug\n", replay.TxnID, yuan(replay.Balance))
		fmt.Println()
		fmt.Println("  后果链：")
		fmt.Println("    ① 软删让出了 crid（部分索引的 WHERE deleted_at IS NULL 把它排除了）")
		fmt.Println("    ② 客户端离线队列重放 → **又插入一笔同样的账**")
		fmt.Println("    ③ 用户的**删除操作被撤销了** —— 他明明已经删掉这笔")
		fmt.Printf("    ④ 活跃流水 %d 条（= 1，与删除前一样，**看不出任何异常**）\n", d3.countLive())
		fmt.Printf("       但总行数 %d（多出来的那行就是重放产生的）\n", d3.countAll())
		fmt.Printf("    ⑤ 余额 %s —— 与「第一笔存在时」完全一样\n", yuan(d3.find(acc3.ID).Amount))
		fmt.Println()
		fmt.Println("  ★ 所以这个 bug 的真实形态不是「多了一笔账」，")
		fmt.Println("    而是「**用户的删除被静默撤销了**」：")
		fmt.Println("      用户：我明明删了，怎么又回来了？")
		fmt.Println("      列表：他删的那笔不见了，但多了一笔一模一样的")
		fmt.Println("      余额：和没删时一样，所以他更困惑了")
		fmt.Println()
		fmt.Println()
		fmt.Println("  ★ 而且这个 bug 极难发现：")
		fmt.Println("    - 没有报错（INSERT 完全成功）")
		fmt.Println("    - 活跃流水条数**和删除前一样**（1 条），列表看不出数量变化")
		fmt.Println("    - 余额**和没删时一样**，对账脚本查不出 drift")
		fmt.Println("    - 只有「用户发现自己删不掉东西」才会暴露")
		fmt.Println("    而这在真实场景里意味着：用户**永远无法删除任何一笔流水**")
		fmt.Println("    （只要那个 crid 还在离线队列里，就会被重放复活）")
		fmt.Println()
		fmt.Println("  ★ 更糟的是：这个 bug 会在「用户删了某笔 + 离线队列重放」时")
		fmt.Println("    必然触发，而这两件事在家庭记账里都很常见。")
	} else {
		fmt.Printf("    → 被挡住 %s\n", replay.Detail)
	}

	// -----------------------------------------------------------------
	hdr("5. 四张表的唯一约束形态对照（本项目的最终口径）")
	// -----------------------------------------------------------------
	fmt.Println()
	tbl := [][]string{
		{"表", "唯一列", "形态", "为什么"},
		{"finance_account", "(family_id, name)", "部分 WHERE deleted_at IS NULL", "名字可复用，删了要让出来"},
		{"finance_account", "(family_id)", "部分 WHERE is_default AND deleted_at IS NULL", "d3：每家庭至多一个默认"},
		{"finance_category", "(family_id, name)", "部分 WHERE deleted_at IS NULL", "S3 d12 的结论"},
		{"finance_category", "(family_id, parent_id, name)", "部分 WHERE deleted_at IS NULL", "S3 d12：两级分类各一个"},
		{"finance_transaction", "(family_id, client_request_id)", "**普通**（无 WHERE）", "★ 请求标识，软删也不能让"},
	}
	for i, r := range tbl {
		if i == 0 {
			fmt.Printf("  %-20s %-30s %-38s %s\n", r[0], r[1], r[2], r[3])
			fmt.Println("  " + strings.Repeat("-", 120))
			continue
		}
		fmt.Printf("  %-20s %-30s %-38s %s\n", r[0], r[1], r[2], r[3])
	}
	fmt.Println()
	fmt.Println("★ 一眼看出规律：")
	fmt.Println("  前四行的唯一列是**业务标识**（名字）→ 部分索引")
	fmt.Println("  最后一行的唯一列是**请求标识**（crid）→ 普通索引")
	fmt.Println()
	fmt.Println("  判据：**这一列的值，在对象被软删后应该被「让出来」吗？**")
	fmt.Println("    分类名：应该（用户要能重建同名）")
	fmt.Println("    crid：不应该（那是「曾经发生过」的证明）")

	// -----------------------------------------------------------------
	hdr("6. 完整 DDL")
	// -----------------------------------------------------------------
	ddl := `-- ★ 幂等键：普通唯一索引，**不加 WHERE**
CREATE UNIQUE INDEX uniq_txn_family_crid
  ON finance.finance_transaction (family_id, client_request_id);
-- 注释要写清楚，否则后人一定会「顺手优化」成部分索引：
-- 禁止加 WHERE deleted_at IS NULL！
-- 原因：软删后 crid 必须继续被占用，否则客户端离线队列重放会重复扣款。
-- 详见 docs/plan 的 S10 d26。

-- 对照：分类的名字用部分索引（软删后要让出来）
CREATE UNIQUE INDEX uniq_fc_family_name
  ON finance.finance_category (family_id, name)
  WHERE deleted_at IS NULL;

-- 对照：默认账户
CREATE UNIQUE INDEX uniq_acc_family_default
  ON finance.finance_account (family_id)
  WHERE is_default AND deleted_at IS NULL;`
	fmt.Println(ddl)
	fmt.Println()
	fmt.Println("★ 那条「禁止加 WHERE」的注释不是装饰 —— ")
	fmt.Println("  它是**防止未来的人优化掉正确性**的唯一手段。")
	fmt.Println("  没有注释，下一个人看到「其他表都用了部分索引，这里为什么不用」")
	fmt.Println("  会很自然地「统一风格」，然后引入一个只在离线重放时才出现的 bug。")
	fmt.Println()
	fmt.Println("  ★ 这类注释值得写，因为它解释的是**为什么不做某件看似应该做的事**。")
	fmt.Println("    而「为什么」是代码里最容易丢失、又被最需要的部分。")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：怎么在代码里表达「普通唯一索引」")
	// -----------------------------------------------------------------
	fmt.Println("GORM 的 AutoMigrate **不区分**普通索引和部分索引 ——")
	fmt.Println("它只会生成 `CREATE UNIQUE INDEX ... ON t (col1, col2)`。")
	fmt.Println("部分索引必须手写迁移（这与 d12 的结论一致）。")
	fmt.Println()
	fmt.Println("Go 侧的服务代码要意识到这个差异：")
	fmt.Println("```go")
	fmt.Println("// 插入前先查（快路径）—— 注意：**不能只查未删除的**")
	fmt.Println("var exist Txn")
	fmt.Println("err := tx.Unscoped().            // ★ 必须 Unscoped")
	fmt.Println("    Where(\"family_id = ? AND client_request_id = ?\", famID, crid).")
	fmt.Println("    First(&exist).Error")
	fmt.Println()
	fmt.Println("if err == nil {")
	fmt.Println("    if exist.DeletedAt.Valid {")
	fmt.Println("        // 软删的行也占着 crid → 拒绝，并给出清晰提示")
	fmt.Println("        return nil, &BizError{409, 40011,")
	fmt.Println("            \"该请求已被处理过（对应记录已删除），不能重复提交\"}")
	fmt.Println("    }")
	fmt.Println("    return toView(exist), nil   // 幂等命中")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 最容易写错的一行是 `.Unscoped()`。")
	fmt.Println("  忘了它 → `First` 会自动加 deleted_at IS NULL →")
	fmt.Println("  → 查不到软删的行 → 然后你去 INSERT → 23505（因为索引还在）")
	fmt.Println("  → 你把这个 23505 当成「并发冲突」处理，返回了错误的错误码。")
	fmt.Println("  ★ 结果是「碰巧对了」：用户看到 409 而不是 500，但消息不对。")
	fmt.Println("  真正要小心的是：如果哪天有人把唯一索引改成部分索引，")
	fmt.Println("  这段「碰巧对」就变成「真错」了 —— 多一笔账。")
	fmt.Println()
	fmt.Println("TS 侧：")
	fmt.Println("```ts")
	fmt.Println("// 客户端不需要关心这个区别（幂等是服务端的事）")
	fmt.Println("// 但**离线队列的实现**要知道：重放时 crid 必须复用")
	fmt.Println("const pending = queue.map(item => ({ ...item, crid: item.crid }))  // ← 不重新生成")
	fmt.Println("```")
	fmt.Println("  客户端唯一要守的纪律：**同一个操作重发多少次，crid 都必须是同一个**")
	fmt.Println("  （d22 讲过：retry 封装里重新生成 UUID 会让幂等完全失效）")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "开头对照 d12 的结论，说明「为什么这里相反」"},
		{true, "真跑场景 ①：新 crid 成功 + 原 crid 被拒（区分「重复」与「再次」）"},
		{true, "真跑场景 ②：离线队列重放 3 轮，余额只扣一次"},
		{true, "真跑场景 ③：部分索引下重放**真的插入第二笔**（bug 复现）"},
		{true, "五张表的唯一约束形态对照表 + 判据"},
		{true, "DDL 里带「禁止加 WHERE」的反优化注释"},
		{true, "服务层必须 Unscoped 查询，并解释漏了会怎样"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("★ 今天的落点（本阶段六个必讲透点之一）：")
		fmt.Println("  软删 + 唯一约束的冲突，在流水上表现为「幂等键是否释放」。")
		fmt.Println()
		fmt.Println("  答案：**不释放**。因为 crid 保护的是「一次请求发生过」这个事实，")
		fmt.Println("  而不是「那笔数据还在不在」。")
		fmt.Println("  用部分索引会让离线重放重复扣款，而那个 bug 没有任何报错。")
		fmt.Println()
		fmt.Println("  这与 d12 的结论相反不矛盾 —— 两个约束保护的资源类型不同。")
		fmt.Println("  判据是：**软删后这个值该被让出来吗？**")
		fmt.Println("  名字该让，crid 不该让。")
		fmt.Println()
		fmt.Println("W42 d26 通过。")
	}
}

func okWord(ok bool) string {
	if ok {
		return "✅"
	}
	return "❌"
}

// =====================================================================
// W42 d27：回收站 —— GET /transactions?deleted=true。
//
// S10 判据 4：**软删有、恢复入口也有**（软删没恢复入口 = 数据进黑洞）。
//
// 回收站不是「新功能」，它是软删的**必要配套**。
// 判据：软删对用户来说必须比删除「更可逆」，否则它就等于删除。
//
// 今天讲三件容易做错的事：
//   ① 回收站的查询：GORM 的 Unscoped 语义（不要过滤 ≠ 只要已删）
//   ② 回收站要不要显示 crid / 幂等键（**不能显示**，会泄露实现细节且误导用户）
//   ③ 回收站列表的时间倒序：按 deleted_at 排，不是 occurred_at
//
// 第 3 节真跑：造 12 条软删记录，跑出真实的回收站列表（含分页）。
// 第 5 节真跑：为什么按 deleted_at 排序而不是 occurred_at。
//
// 本机没有 Postgres。内存模拟，SQL 手写 + GORM DryRun 真实生成。
// =====================================================================

package main

import (
	"encoding/base64"
	"fmt"
	"sort"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

type Txn struct {
	ID         string
	FamilyID   string
	AccountID  string
	Amount     int64
	Type       string
	Note       string
	CRID       string
	OccurredAt time.Time
	CreatedAt  time.Time
	DeletedAt  *time.Time
	DeletedBy  string
	seq        int
}

func (Txn) TableName() string { return "finance_transaction" }

type DB struct {
	Txns []*Txn
	seq  int
}

func newDB() *DB { return &DB{} }

func (d *DB) add(accID string, amt int64, typ, note string, occurred time.Time) *Txn {
	d.seq++
	t := &Txn{
		ID: fmt.Sprintf("txn-%04d", d.seq), FamilyID: famA, AccountID: accID,
		Amount: amt, Type: typ, Note: note,
		CRID:       fmt.Sprintf("crid-%04d", d.seq),
		OccurredAt: occurred, CreatedAt: fixedNow, seq: d.seq,
	}
	d.Txns = append(d.Txns, t)
	return t
}

func (d *DB) softDelete(id, by string, at time.Time) {
	for _, t := range d.Txns {
		if t.ID == id && t.DeletedAt == nil {
			a := at
			t.DeletedAt = &a
			t.DeletedBy = by
		}
	}
}

// 回收站列表：只返回已删除的，按 deleted_at DESC, id DESC
func (d *DB) recycleBin(limit int, cursorDeletedAt time.Time, cursorID string) ([]*Txn, string) {
	var out []*Txn
	for _, t := range d.Txns {
		if t.DeletedAt == nil {
			continue // ★ 只要已删除的
		}
		if !cursorDeletedAt.IsZero() {
			if t.DeletedAt.After(cursorDeletedAt) {
				continue
			}
			if t.DeletedAt.Equal(cursorDeletedAt) && t.ID >= cursorID {
				continue
			}
		}
		out = append(out, t)
	}
	// 排序：deleted_at DESC, id DESC（★ 不是 occurred_at）
	sort.Slice(out, func(i, j int) bool {
		if !out[i].DeletedAt.Equal(*out[j].DeletedAt) {
			return out[i].DeletedAt.After(*out[j].DeletedAt)
		}
		return out[i].ID > out[j].ID
	})
	var next string
	if len(out) > limit {
		last := out[limit-1]
		next = base64.RawURLEncoding.EncodeToString(
			[]byte(fmt.Sprintf("%d:%s", last.DeletedAt.UnixMicro(), last.ID)))
		out = out[:limit]
	}
	return out, next
}

func (d *DB) activeCount() int {
	n := 0
	for _, t := range d.Txns {
		if t.DeletedAt == nil {
			n++
		}
	}
	return n
}

func decodeCursor(s string) (time.Time, string) {
	raw, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return time.Time{}, ""
	}
	parts := strings.SplitN(string(raw), ":", 2)
	if len(parts) != 2 {
		return time.Time{}, ""
	}
	var us int64
	fmt.Sscanf(parts[0], "%d", &us)
	return time.UnixMicro(us).UTC(), parts[1]
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 回收站不是功能，是软删的必要配套")
