	fmt.Println("  但超过 30 天的行「不显示」也「不说明」。")
	fmt.Println("  用户会以为「系统弄丢了我的数据」。")
	fmt.Println("  正确做法：**照常列出，但标注「已超过 30 天，不可恢复」**。")
	fmt.Println("  让用户看到「东西还在，但找不回来了」比「东西不见了」好得多。")

	// -----------------------------------------------------------------
	hdr("2. ★ 回收站的查询：Unscoped 的真实语义")
	// -----------------------------------------------------------------
	fmt.Println("GORM 的 Unscoped 最常见的误解：以为它等于「只要已删除的」。")
	fmt.Println("它的真实语义是「**不要自动加 deleted_at 条件**」—— 两个方向都不管。")
	fmt.Println()
	fmt.Println("```go")
	fmt.Println("// ❌ 错：Unscoped 后没有条件 → 拿到**全部**数据（含未删的）")
	fmt.Println("tx.Unscoped().Where(\"family_id = ?\", famID).Find(&txns)")
	fmt.Println()
	fmt.Println("// ✅ 对：Unscoped + 显式加 deleted_at IS NOT NULL")
	fmt.Println("tx.Unscoped().")
	fmt.Println("   Where(\"family_id = ? AND deleted_at IS NOT NULL\", famID).")
	fmt.Println("   Order(\"deleted_at DESC, id DESC\").")
	fmt.Println("   Find(&txns)")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 注意「对」的写法里有两个 WHERE 条件，缺一不可：")
	fmt.Println("  deleted_at IS NOT NULL → 只要已删的")
	fmt.Println("  （family_id 那个是多租户隔离，S5 的硬约束）")
	fmt.Println()

	db := dryDB()
	sql1 := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Unscoped().
			Where("family_id = ? AND deleted_at IS NOT NULL", famA).
			Order("deleted_at DESC, id DESC").
			Limit(20)
	})
	fmt.Println("GORM DryRun 真实生成的 SQL：")
	fmt.Println("  ", sql1)
	fmt.Println()
	sql2 := db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Txn{}).
			Where("family_id = ?", famA).
			Order("occurred_at DESC").
			Limit(20)
	})
	fmt.Println("对照：普通查询（GORM 自动加过滤）：")
	fmt.Println("  ", sql2)
	fmt.Println()
	fmt.Println("★ 两处差别值得注意：")
	fmt.Println("  ① WHERE 里多了 deleted_at IS NOT NULL（Unscoped 的代价：你要自己写）")
	fmt.Println("  ② ORDER BY 从 occurred_at 变成了 deleted_at（下节展开）")

	// -----------------------------------------------------------------
	hdr("3. ★ 真跑：12 条软删记录的回收站列表")
	// -----------------------------------------------------------------
	d := newDB()
	base := time.Date(2026, 10, 1, 8, 0, 0, 0, time.UTC)
	notes := []struct {
		Amt  int64
		Note string
	}{
		{800000, "2026-10 工资"}, {32500, "买菜 32.50"}, {800, "地铁 8 块"},
		{28000, "超市 280"}, {4500, "咖啡 45"}, {120000, "房租 1200"},
