	sort.Slice(sorted1, func(i, j int) bool { return sorted1[i][1] > sorted1[j][1] })
	for _, r := range sorted1 {
		fmt.Printf("    %s（发生于 %s，删于 %s）\n", r[0], r[1], r[2])
	}
	fmt.Println()
	fmt.Println("  按 deleted_at 排（正确）：")
	sorted2 := append([][]string(nil), rows...)
	sort.Slice(sorted2, func(i, j int) bool { return sorted2[i][2] > sorted2[j][2] })
	for _, r := range sorted2 {
		fmt.Printf("    %s（删于 %s）\n", r[0], r[2])
