	fmt.Println(api)

	// -----------------------------------------------------------------
	hdr("6. ★ 回收站绝不能显示 crid")
	// -----------------------------------------------------------------
	fmt.Println("crid 是**实现细节**，不是用户数据。回收站返回它有三个问题：")
	fmt.Println()
	probs := []string{
		"① 泄露实现：用户看到 UUID 会问「这是什么」，客服要解释「这是幂等键」",
		"② 误导用户：用户可能想「我能不能改这个值」—— 不能，UNIQUE 约束会 23505",
		"③ 契约泄漏：以后要改幂等键方案（比如换成 ULID），前端就依赖了这个字段",
	}
	for _, p := range probs {
		fmt.Printf("  %s\n", p)
	}
	fmt.Println()
	fmt.Println("★ 判据：**返回 DTO，不是实体。**（PRD 22.2 第 9 条的明确要求）")
	fmt.Println("  「展示字段不得挂在实体结构体上由 handler 拼装，一律走 DTO/投影层」")
	fmt.Println()
	fmt.Println("  具体做法：定义独立的 RecycleBinItem，不复用 Txn：")
	fmt.Println("```go")
