	fmt.Println("    AmountCents    int64      `json:\"amount_cents\"`")
	fmt.Println("    Type           string     `json:\"type\"`")
	fmt.Println("    Note           *string    `json:\"note\"`")
	fmt.Println("    AccountID      string     `json:\"account_id\"`")
	fmt.Println("    OccurredAt     time.Time  `json:\"occurred_at\"`")
	fmt.Println("    DeletedAt      time.Time  `json:\"deleted_at\"`")
	fmt.Println("    DeletedByName  string     `json:\"deleted_by_name\"`")
	fmt.Println("    Recoverable    bool       `json:\"recoverable\"`")
	fmt.Println("    DaysLeft       int        `json:\"days_left\"`")
	fmt.Println("    // ★ 没有 CRID、没有 Version、没有 PayloadHash")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("★ 这个「不用什么」比「用什么」更重要：")
	fmt.Println("  DTO 是**白名单**，实体是**黑名单**。")
	fmt.Println("  实体上加一个新字段（比如 password_hash、internal_note），")
	fmt.Println("  直接返回实体就泄露了；DTO 不会。")
	fmt.Println("  这就是为什么 S4 讲「DTO 与领域模型要分开」—— 今天有了具体例子。")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：deleted_at 的时区与精度")
	// -----------------------------------------------------------------
	fmt.Println("Go：")
	fmt.Println("```go")
	fmt.Println("var t *time.Time  // nil = 未删除")
	fmt.Println("if t.DeletedAt != nil {")
	fmt.Println("    age := time.Since(*t.DeletedAt)")
	fmt.Println("    recoverable := age < 30*24*time.Hour")
	fmt.Println("    daysLeft := int((30*24*time.Hour - age).Hours() / 24)")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  ★ `time.Since` 用的是**本机时钟**。如果服务端时钟不准，")
	fmt.Println("    「还能恢复几天」会算错。")
	fmt.Println("    严格做法是同时用两个时间：deleted_at（数据库记录的）与数据库 now()，")
	fmt.Println("    差值才是准确的时间差：")
	fmt.Println("```sql")
	fmt.Println("SELECT deleted_at,")
	fmt.Println("       EXTRACT(DAY FROM (now() - deleted_at))::int AS days_left,")
	fmt.Println("       (now() - deleted_at) < interval '30 days' AS recoverable")
	fmt.Println("  FROM finance_transaction")
	fmt.Println(" WHERE family_id = $1 AND deleted_at IS NOT NULL")
	fmt.Println("   AND deleted_at >= now() - interval '30 days'")
	fmt.Println(" ORDER BY deleted_at DESC, id DESC")
	fmt.Println(" LIMIT $2;")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  ★ 30 天窗口的边界用 `deleted_at >= now() - interval '30 days'` 过滤，")
	fmt.Println("    于是「超期」的行**根本不会出现在结果里**。")
	fmt.Println("    但第 1 节说了要「照常列出并标注」—— 两种做法：")
	fmt.Println("      A. 只列 30 天内的（简单，但用户会以为数据消失了）")
	fmt.Println("      B. 全列出，recoverable=false 标注（更诚实）")
	fmt.Println("    本项目选 **B**，因为「数据进黑洞」正是判据 4 要避免的。")
	fmt.Println("    代价是回收站列表可能很长 → 用分页解决。")
	fmt.Println()
	fmt.Println("TS 侧：")
	fmt.Println("```ts")
	fmt.Println("// deleted_at 在 TS 里是 string | null")
	fmt.Println("const age = txn.deletedAt ? Date.now() - new Date(txn.deletedAt).getTime() : 0")
	fmt.Println("const recoverable = age < 30 * 24 * 3600 * 1000")
	fmt.Println("```")
	fmt.Println("  ★ 但**不要**在客户端算 days_left —— 客户端时区/时钟都可能不准，")
	fmt.Println("    而「还剩 3 天」这种信息如果算错了，用户会在第 4 天发现还能恢复。")
	fmt.Println("    服务端算好，客户端只显示。")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
	// -----------------------------------------------------------------
	checks := []struct {
		OK  bool
		Msg string
	}{
		{true, "先论证「回收站是软删的必要配套」，判据：更可逆"},
		{true, "Unscoped 的真实语义（不要过滤 ≠ 只要已删）+ DryRun 真实 SQL"},
		{true, "真跑：12 条活跃 + 6 条软删，回收站分页翻完不重不漏"},
		{true, "真跑：按 deleted_at 排 vs occurred_at 排的对比与用户视角"},
		{true, "三个列表三个排序键的判据"},
		{true, "接口形状 + recoverable/days_left 由服务端算"},
		{true, "回收站不返回 crid/version/payload_hash，用 DTO 白名单"},
		{true, "时区与时钟偏差：days_left 用数据库 now() 算"},
	}
	allOK := true
	for _, c := range checks {
		mark := "✅"
		if !c.OK {
			mark = "❌"
			allOK = false
		}
		fmt.Printf("  %s %s\n", mark, c.Msg)
	}
	fmt.Println()
	if allOK {
		fmt.Println("★ 今天的落点：")
		fmt.Println("  回收站的三个「容易做错」，第 ③ 个最反直觉 ——")
		fmt.Println("  **按 deleted_at 排，不是 occurred_at**。")
		fmt.Println()
		fmt.Println("  因为用户进回收站是来找「我删过什么」，")
		fmt.Println("  那是一个关于**删除动作**的问题，不是关于业务的问题。")
		fmt.Println()
		fmt.Println("  顺带一个更重要的：回收站的 DTO 里**没有 crid**。")
		fmt.Println("  DTO 是白名单，实体是黑名单 —— 这个区别在安全上是本质的。")
