// =====================================================================
// W42 d28：恢复 —— 30 天内可恢复，恢复后预算与统计怎么重算。
//
// S10 判据 4 的后半句：**软删有、恢复入口也有**。
// d27 做了「能看到」，今天做「能恢复」+ 恢复后的一致性。
//
// 恢复不是「把 deleted_at 置 NULL」这么简单，四个坑：
//   ① 恢复也是**事务**（要改两个账户的余额，d17 讲过）
//   ② 30 天窗口怎么判定（用数据库 now()，不用客户端时间）
//   ③ 恢复后**预算与统计**怎么重算（d2 的不变量回来了）
//   ④ 恢复时如果账户已被归档怎么办（余额回滚到一个不能用的账户）
//
// 第 3 节真跑：恢复一笔转账，两个账户的余额与对账。
// 第 5 节真跑：恢复一笔**超期**的（35 天前删的）→ 拒绝。
// 第 6 节真跑：恢复到一个已归档的账户 → 拒绝或改道。
//
// 本机没有 Postgres。内存模拟，SQL 手写。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const recoveryWindow = 30 * 24 * time.Hour

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

type Acc struct {
	ID       string
	Name     string
	Amount   int64
	Opening  int64
	Archived bool
}

type Txn struct {
	ID        string
	Type      string
	From      string
	To        string
	Amount    int64
	Note      string
	CRID      string
	DeletedAt *time.Time
	DeletedBy string
	Version   int
}

type DB struct {
	Accs []*Acc
	Txns []*Txn
	seq  int
}

func newDB() *DB { return &DB{} }

func (d *DB) acc(name string, amt int64) *Acc {
	d.seq++
	a := &Acc{ID: fmt.Sprintf("acc-%d", d.seq), Name: name, Amount: amt, Opening: amt}
	d.Accs = append(d.Accs, a)
	return a
}

func (d *DB) find(id string) *Acc {
	for _, a := range d.Accs {
		if a.ID == id {
			return a
		}
	}
	return nil
}

func (d *DB) txn(typ, from, to string, amt int64, note, crid string) *Txn {
	d.seq++
	t := &Txn{ID: fmt.Sprintf("txn-%d", d.seq), Type: typ, From: from, To: to,
		Amount: amt, Note: note, CRID: crid, Version: 1}
	d.Txns = append(d.Txns, t)
	return t
}

func (d *DB) computed(accID string) int64 {
	sum := d.find(accID).Opening
	for _, t := range d.Txns {
		if t.DeletedAt != nil {
			continue
		}
		if t.Type == "income" && t.From == accID {
			sum += t.Amount
		}
		if t.Type == "expense" && t.From == accID {
			sum -= t.Amount
		}
		if t.Type == "transfer" {
			if t.From == accID {
				sum -= t.Amount
			}
			if t.To == accID {
				sum += t.Amount
			}
		}
	}
	return sum
}

type BizError struct {
	HTTP int
	Code int
	Msg  string
}

func (d *DB) Restore(fam, id string, expectVer int, by string) (*Txn, *BizError) {
	// 找这一行（要 Unscoped 的效果：软删的也能找到）
	var t *Txn
	for _, x := range d.Txns {
		if x.ID == id {
			t = x
		}
	}
	if t == nil {
		return nil, &BizError{404, 3001, "记录不存在"}
	}
	if t.DeletedAt == nil {
		// 幂等：已经恢复过了
		return t, nil
	}
	// ① 30 天窗口：用「数据库当前时间」
	age := fixedNow.Sub(*t.DeletedAt)
	if age > recoveryWindow {
		return nil, &BizError{410, 40021, fmt.Sprintf(
			"已超过 %d 天恢复窗口（删除于 %s，已过 %d 天）",
			int(recoveryWindow.Hours()/24),
			t.DeletedAt.Format("2006-01-02"), int(age.Hours()/24))}
	}
	// ② 乐观锁
	if expectVer != t.Version {
		return nil, &BizError{409, 40901, fmt.Sprintf(
			"数据已被他人修改，请刷新后重试（当前 version=%d）", t.Version)}
	}
	// ③ 账户必须可写
	from := d.find(t.From)
	if from == nil {
		return nil, &BizError{404, 3001, "原账户不存在"}
	}
	if from.Archived {
		return nil, &BizError{409, 40022, fmt.Sprintf(
			"原账户「%s」已归档，无法恢复到该账户（请先取消归档或改选账户）", from.Name)}
	}
	// ④ 余额不能为负（恢复一笔支出到余额不足的账户）
	if t.Type == "expense" && from.Amount < t.Amount {
		return nil, &BizError{409, 4001, fmt.Sprintf(
			"恢复后「%s」余额将为 %s（不足），请先补足余额", from.Name, yuan(from.Amount-t.Amount))}
	}
	// ---- 事务开始 ----
	t.DeletedAt = nil
	t.DeletedBy = ""
	t.Version++
	from.Amount -= t.Amount // 反向撤销删除时的回滚
	if t.To != "" {
		to := d.find(t.To)
		if to != nil {
			to.Amount += t.Amount
		}
	}
	return t, nil
}

