		fmt.Println("  恢复之后，「存的余额 == 流水聚合」这个不变量**重新成立**。")
		fmt.Println()
		fmt.Println("  这说明软删的三步（软删 / 回滚余额 / 恢复）")
		fmt.Println("  必须**永远同步**执行。漏任何一步，d2 的对账脚本都会报 drift。")
		fmt.Println("  而 d6 说的「所有写流水的路径必须收口到同一个 service 方法」")
		fmt.Println("  在这里的具体含义就是：**删除与恢复要放在一起**（同一个 Txns service）。")
		fmt.Println()
		fmt.Println("W42 d28 通过。明天讲硬删：什么情况下允许物理删。")
	}
}

func okStr(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

// =====================================================================
// W42 d29：硬删 —— 什么情况下允许物理删（30 天冷存后）。
//
// 这是本阶段唯一一个**主动删除数据**的操作，所以门槛最高。
//
// 三层约束，缺一不可：
//   ① 时间：deleted_at 超过 30 天（过了恢复窗口）
//   ② 身份：必须是「自己删的」（deleted_by = 当前成员），且 30 天内没再改
//   ③ 引用：没有其他数据引用它（附件、due 注册项、分摊）
//
// 第 3 节真跑：三种「看起来超期但**不能删**」的情况。
// 第 5 节真跑：DELETE 的 SQL 形态，以及 Unscoped 的正确用法。
// 第 6 节：30 天冷存的替代方案（归档到冷表 vs 直接删）。
//
// 本机没有 Postgres。内存模拟，SQL 手写。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const window = 30 * 24 * time.Hour

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

type Ref struct {
	Kind   string // receipt / due_registration / split
	Target string
}

type Txn struct {
	ID        string
	Type      string
	AccountID string
	Amount    int64
	CRID      string
	DeletedAt *time.Time
	DeletedBy string
	UpdatedAt time.Time
	HasDue    bool
	Refs      []Ref
}

type DB struct {
	Txns []*Txn
	seq  int
}

func newDB() *DB { return &DB{} }

func (d *DB) add(amt int64, typ, accID string, deletedDaysAgo int, by string, updatedDaysAgo int) *Txn {
	d.seq++
	t := &Txn{
		ID: fmt.Sprintf("txn-%04d", d.seq), Type: typ, AccountID: accID,
		Amount: amt, CRID: fmt.Sprintf("crid-%04d", d.seq),
		UpdatedAt: fixedNow.AddDate(0, 0, -updatedDaysAgo),
	}
	if deletedDaysAgo >= 0 {
		del := fixedNow.AddDate(0, 0, -deletedDaysAgo)
		t.DeletedAt = &del
		t.DeletedBy = by
	}
	d.Txns = append(d.Txns, t)
	return t
}

func (d *DB) hardDelete(id string) bool {
	for i, t := range d.Txns {
		if t.ID == id {
			d.Txns = append(d.Txns[:i], d.Txns[i+1:]...)
			return true
		}
	}
	return false
}

type BizError struct {
	HTTP int
	Code int
	Msg  string
}

func (d *DB) Purge(id, by string) (int, *BizError) {
	var t *Txn
	for _, x := range d.Txns {
		if x.ID == id {
			t = x
		}
	}
	if t == nil {
		return 0, &BizError{404, 3001, "记录不存在"}
	}
	if t.DeletedAt == nil {
		return 0, &BizError{400, 40023, "该记录未被删除，无需清理"}
	}
	age := fixedNow.Sub(*t.DeletedAt)
	if age < window {
		return 0, &BizError{409, 40024, "尚未超过 30 天清理窗口，不能物理删除"}
	}
	if t.UpdatedAt.After(*t.DeletedAt) {
		return 0, &BizError{409, 40025, "删除后该记录又被修改过，需人工确认"}
	}
	// ③ 引用检查
	if len(t.Refs) > 0 {
		var names []string
		for _, r := range t.Refs {
			names = append(names, r.Kind)
		}
		return 0, &BizError{409, 40026,
			"该记录仍被引用（" + strings.Join(names, ", ") + "），不能物理删除"}
	}
	if t.HasDue {
		return 0, &BizError{409, 40027,
			"该记录在到期中心有注册项，请先撤销注册（finance.due.revoked）"}
	}
	if !d.hardDelete(id) {
		return 0, &BizError{500, 50000, "删除失败"}
	}
	return 1, nil
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

func main() {
	// -----------------------------------------------------------------
	hdr("1. 硬删的三个前提（缺一个都不能删）")
	// -----------------------------------------------------------------
	conds := []struct{ No, Name, Rule, Why string }{
		{"①", "时间", "deleted_at 超过 30 天", "过了恢复窗口，用户已经无法恢复"},
		{"②", "身份与静止", "deleted_by 明确，且删除后没有被再改过", "「删除后又改」说明有人在关注它，不该静默清掉"},
		{"③", "无引用", "没有附件/due 注册/分摊引用它", "删了会让别处的数据变孤儿"},
	}
	for _, c := range conds {
		fmt.Printf("  %s %s：%s\n", c.No, c.Name, c.Rule)
		fmt.Printf("     %s\n", c.Why)
	}
	fmt.Println()
	fmt.Println("★ 三条都是「**防止误删**」而不是「防止漏删」。")
	fmt.Println("  硬删是唯一不可逆的操作，所以每一道检查都在问：")
	fmt.Println("  「有没有可能用户其实还需要它？」")
	fmt.Println()
	fmt.Println("★ 还要注意：硬删**不应该有面向用户的接口**。")
	fmt.Println("  它是运维/定时任务的行为，不是用户能点的按钮。")
	fmt.Println("  理由：用户说「删掉」的时候，想要的是「我看不到它了」（软删），")
	fmt.Println("  不是「数据真的消失」。真要消失也是 30 天后由系统决定。")
	fmt.Println("  所以 d27 的回收站里**不提供「立即删除」按钮**，只有「恢复」。")

	// -----------------------------------------------------------------
	hdr("2. 清理任务的位置与形态")
	// -----------------------------------------------------------------
	job := `-- scripts/purge_soft_deleted.sql（每天 03:47 跑，避开备份窗口）
-- 一次删一批，不要一次删光（避免长事务锁表）

WITH victims AS (
  SELECT id
    FROM finance.finance_transaction
   WHERE deleted_at IS NOT NULL
     AND deleted_at < now() - interval '30 days'
     AND updated_at <= deleted_at          -- ② 删除后没被再改过
     AND receipt IS NULL                   -- ③ 无附件引用
     AND NOT EXISTS (                     -- ③ 无 due 注册（S9 d9 的级联失效兜底）
            SELECT 1 FROM calendar.calendar_due_registration r
             WHERE r.source_system = 'finance'
               AND r.source_id = finance_transaction.id::text
               AND r.active)
   LIMIT 1000                              -- 每批 1000 行
)
DELETE FROM finance.finance_transaction t
 USING victims v
 WHERE t.id = v.id
 RETURNING t.id;

-- ★ 注意三点：
--   ① 跨 schema 查 calendar 的表 → 违反 22.2 第 2/3 条
--      正确做法：靠事件撤销 + 每日对账（18.6），这个 NOT EXISTS 改成
--      「只查本 schema 的引用表 + 由 S9 的撤销链路保证」
--   ② updated_at <= deleted_at 是一个**便宜**的保护
--   ③ LIMIT 1000 让事务短（d14 讲过事务要短）`
	fmt.Println(job)
	fmt.Println()
	fmt.Println("★ 这里有一个必须承认的取舍：")
	fmt.Println("  「无 due 注册」这个检查跨服务，finance 查不到 calendar 的表。")
	fmt.Println("  两个方案：")
	fmt.Println("    A. 靠事件：软删时发 finance.transaction.deleted → calendar 撤销注册")
	fmt.Println("       （S9 d5/d7 的撤销链路，d9 讲过）")
	fmt.Println("       风险：事件丢了 → 清理时删了它 → calendar 留孤儿（S9 d10 的对账会发现）")
	fmt.Println("    B. 不查，直接删，靠对账兜底")
	fmt.Println("  本项目选 **A**，并且清理任务**只删 finance 自己知道没引用的行**。")
	fmt.Println("  这就是 PRD 22.2 第 3 条「跨服务无物理外键，引用完整性走每日对账」的实践。")

	// -----------------------------------------------------------------
	hdr("3. ★ 真跑：三种「超期但不能删」的情况")
	// -----------------------------------------------------------------
	d := newDB()

	// ① 超期且干净 → 可删
	clean := d.add(32500, "expense", "acc-001", 45, "mem-mom", 45) // 45 天前删，之后没改

	// ② 超期但删除后又被改过
	touched := d.add(8000, "expense", "acc-001", 40, "mem-mom", 35) // 40 天前删，5 天前被改

	// ③ 超期但有附件引用
	att := d.add(12000, "expense", "acc-001", 60, "mem-dad", 60)
	att.Refs = append(att.Refs, Ref{Kind: "receipt", Target: "file-abc.jpg"})

	// ④ 超期但有 due 注册（跨服务）
	due := d.add(50000, "expense", "acc-001", 50, "mem-mom", 50)
	due.HasDue = true

	// ⑤ 未超期
	fresh := d.add(2400, "expense", "acc-001", 10, "mem-mom", 10)

	// ⑥ 未删除
	alive := d.add(1800, "expense", "acc-001", -1, "", 0) // deletedDaysAgo = -1 表示未删

	fmt.Println("  造了 6 条，逐一尝试物理删除：")
	fmt.Println()
	type item struct {
		T    *Txn
		Desc string
	}
	items := []item{
		{clean, "超期 45 天，删除后无改动，无引用"},
		{touched, "超期 40 天，但删除后 5 天前被改过"},
		{att, "超期 60 天，但有票据附件引用"},
		{due, "超期 50 天，但在到期中心有注册项"},
		{fresh, "只删了 10 天，未超期"},
		{alive, "根本没删过"},
	}
	fmt.Printf("  %-34s %-8s %-8s %s\n", "记录", "HTTP", "code", "结果")
	fmt.Println("  " + strings.Repeat("-", 92))
	deleted := 0
	for _, it := range items {
		n, err := d.Purge(it.T.ID, "mem-mom")
		res := "✅ 已物理删除"
		if err != nil {
			res = "❌ " + err.Msg
		} else {
			deleted += n
		}
		code := 0
		status := 200
		if err != nil {
			code, status = err.Code, err.HTTP
		}
		fmt.Printf("  %-34s %-8d %-8d %s\n", it.Desc, status, code, res)
	}
	fmt.Println()
	fmt.Printf("  总行数：删前 %d → 删后 %d（真删了 %d 条）\n", 6, len(d.Txns), deleted)
	fmt.Println()
	fmt.Println("  ★ 六条里只有一条能删，这就是「三个前提」的意义。")
	fmt.Println("    其中第 ③ 条（无引用）最容易被忽略：")
	fmt.Println("    「有票据」听起来只是图片，但它可能已经被用户导出到别处了，")
	fmt.Println("    也可能那笔是报销凭证（PRD 4.5 报销单据）。")
	fmt.Println()
	fmt.Println("★ 值得注意的失败码选择：")
	fmt.Println("  · 「未超期」→ 409 40024（不是 400，因为它随时间自动变合法）")
	fmt.Println("  · 「有引用」→ 409 40026（不是 500，因为不是系统故障）")
	fmt.Println("  · 「根本没删过」→ 400 40023（请求本身不对）")
	fmt.Println("  这些是运维脚本用的接口，所以 message 可以更技术化。")

	// -----------------------------------------------------------------
	hdr("4. ★ 真跑：为什么「删除后被改过」要拦")
	// -----------------------------------------------------------------
	fmt.Println("这一条单拿出来讲，因为它反直觉。")
	fmt.Println()
	d2 := newDB()
	x := d2.add(32500, "expense", "acc-001", 40, "mem-mom", 40)
	fmt.Println("  记录：45 天前删，删除后又有人改过它（updated_at > deleted_at）")
	fmt.Printf("    deleted_at = %s\n", x.DeletedAt.Format("2006-01-02"))
	fmt.Printf("    updated_at = %s  ← **晚于** deleted_at\n", x.UpdatedAt.Format("2006-01-02"))
	fmt.Println()
	fmt.Println("  直觉：「已经 40 天了，用户早忘了，清掉吧」")
	fmt.Println("  但如果删掉，丢的不只是这一行数据 ——")
	fmt.Println("    它是「**有人在删除之后还回来找过这笔**」这个事实的唯一记录。")
	fmt.Println()
	fmt.Println("  真实场景：")
	fmt.Println("    ① 用户删了一笔，40 天后突然想起来「我删的那笔是不是这个？」")
	fmt.Println("       他打开了详情页（能看，因为软删行仍可按 id 访问）")
	fmt.Println("       → 说明他在意这笔钱 → 不该被静默清掉")
	fmt.Println("    ② 客服在排查一个纠纷，发现这笔被删过但又改过")
	fmt.Println("       → 这是关键线索")
	fmt.Println()
	fmt.Println("  ★ 所以 updated_at <= deleted_at 这个条件的含义是：")
	fmt.Println("    「删除之后没人再看过/改过它」")
	fmt.Println("  这是一个**兴趣度**信号，而不是技术上的完整性要求。")
	fmt.Println()
	fmt.Println("  代价：这种行永远清不掉，要靠人工处理。")
	fmt.Println("  本项目的口径：清理脚本跳过它们，")
	fmt.Println("  并在月度报告里列出「有 N 条超期待清理但被跳过」的清单给运维。")
	fmt.Println("  —— 不自动清，但也不假装它不存在。")

	// -----------------------------------------------------------------
	hdr("5. DELETE 的 SQL 形态与 Unscoped")
	// -----------------------------------------------------------------
	sql := `-- GORM 里 Unscoped().Delete() 才是真删
res := tx.Unscoped().
    Where("id = ? AND family_id = ? AND deleted_at IS NOT NULL AND deleted_at < ?",
          id, famID, cutoff).      // ★ 三个条件缺一不可
    Delete(&Txn{})

// res.RowsAffected == 0 → 没有符合条件的行（已删过 / 不存在 / 未超期）

-- 手写 SQL 版本（定时任务用这个，可控性更好）
DELETE FROM finance.finance_transaction t
 WHERE t.id = $1
   AND t.family_id = $2
   AND t.deleted_at IS NOT NULL
   AND t.deleted_at < now() - interval '30 days'
   AND t.updated_at <= t.deleted_at;`
	fmt.Println(sql)
	fmt.Println()
	fmt.Println("★ 三个必须记住的点：")
	fmt.Println()
	fmt.Println("  ① Unscoped().Delete() 是**物理删除**，不可逆")
	fmt.Println("     而 tx.Delete(&Txn{...}) 是软删（因为有 DeletedAt 字段）")
	fmt.Println("     ★ 两者只差一个 Unscoped()，但后果完全不同。")
	fmt.Println("     这是 GORM 里**最危险的一个 API 差异**。")
	fmt.Println()
	fmt.Println("  ② WHERE 里的条件必须包含 deleted_at IS NOT NULL")
	fmt.Println("     漏掉它 → DELETE 会删掉**所有**行（不管删没删过）")
	fmt.Println("     生产事故的经典形态：「我只是想清理回收站，结果流水全没了」")
	fmt.Println()
	fmt.Println("  ③ 所以清理任务**不应该走 HTTP 接口**")
	fmt.Println("     走定时任务 / 运维脚本，代码在版本控制里，review 得到")
	fmt.Println("     不暴露成一个可能被前端误调的 endpoint")

	// -----------------------------------------------------------------
	hdr("6. 30 天冷存的三个替代方案")
	// -----------------------------------------------------------------
	fmt.Println("在决定「真删」之前，值得先问：真的要删吗？")
	fmt.Println()
	alts := []struct{ Name, How, Pros, Cons string }{
		{"① 直接删", "DELETE 掉",
			"最简单；空间立刻回收",
			"不可逆；无法满足任何审计/合规要求"},
		{"② 归档到冷表", "INSERT 到 finance_transaction_archive，然后 DELETE 原表",
			"主表小 → 查询快；数据还在，需要时可查",
			"两套 schema 要同步；查询要 UNION（复杂）"},
		{"③ 备份后删", "先 dump 到备份文件，再 DELETE",
			"空间回收；数据在备份里可恢复",
			"恢复要 DBA 介入；备份也有保留期"},
	}
	for _, a := range alts {
		fmt.Printf("  %s\n", a.Name)
		fmt.Printf("     做法：%s\n", a.How)
		fmt.Printf("     优点：%s\n", a.Pros)
		fmt.Printf("     代价：%s\n\n", a.Cons)
	}
	fmt.Println("  本项目选 **③ 备份后删**：")
	fmt.Println("    · 家庭记账的数据量很小（每家庭一年几千行，1 万家庭 = 千万级）")
	fmt.Println("      单表千万行对 Postgres 完全不算大，**清理的动力不足**")
	fmt.Println("    · 每天的数据库备份（PRD 11.2）天然就是冷存")
	fmt.Println("    · 恢复路径存在（从备份重建），虽然慢但可行")
	fmt.Println("    · 所以「30 天后清理」的本意不是省空间，是**控制表膨胀**")
	fmt.Println()
	fmt.Println("  ★ 判据：清理数据之前先算一笔账。")
	fmt.Println("    「这些数据占多少空间？」 vs 「维护清理任务的复杂度 + 出错风险」")
	fmt.Println("    后者往往更贵。")
	fmt.Println("    很多系统的数据清理任务每年出一次事故，而它省下的空间不到 1%。")
	fmt.Println()
	fmt.Println("  ★ 另一个角度：保留 30 天的软删数据还有一个隐性价值 ——")
	fmt.Println("    它让「用户说『我 40 天前删了一笔，能找回来吗』」这类请求有解。")
	fmt.Println("    超过 30 天才真的没了，而这个时间窗口是**产品承诺**，")
	fmt.Println("    所以它应该写进接口文档和错误提示（d28 的 410 里已经写了）。")

	// -----------------------------------------------------------------
	hdr("7. Go 与 TypeScript：危险 API 的写法")
	// -----------------------------------------------------------------
	fmt.Println("Go：把「真删」封装成一个只有定时任务会调用的函数")
	fmt.Println("```go")
	fmt.Println("// internal/purge/purge.go —— 不在 api 包里，任何 HTTP handler 都碰不到")
	fmt.Println("func Purge(ctx context.Context, cutoff time.Time, limit int) (int, error) {")
	fmt.Println("    res := db.WithContext(ctx).Unscoped().")
	fmt.Println("        Where(\"deleted_at IS NOT NULL AND deleted_at < ?\", cutoff).")
	fmt.Println("        Limit(limit).")
	fmt.Println("        Delete(&model.Txn{})")
	fmt.Println("    return int(res.RowsAffected), res.Error")
	fmt.Println("}")
	fmt.Println("```")
	fmt.Println()
	fmt.Println("  ★ 关键：`Limit` 在 GORM 的 Delete 里会转成 `DELETE ... WHERE id IN (subquery)`，")
	fmt.Println("    这样一次只删一批，事务短（d14）。")
	fmt.Println("    没有 Limit 的话，一次删 10 万行会持锁很久。")
	fmt.Println()
	fmt.Println("TS：前端永远不该有「立即删除」的按钮")
	fmt.Println("```ts")
	fmt.Println("// ❌ 千万别提供这种接口")
	fmt.Println("// DELETE /api/finance/transactions/:id?force=true")
	fmt.Println()
	fmt.Println("// ✅ 只有软删（用户可见）与恢复（30 天内）")
	fmt.Println("await api.softDelete(txn)")
	fmt.Println("await api.restore(txn)")
	fmt.Println("```")
	fmt.Println("  理由：用户点「删除」时想要的是「我看不到了」，")
	fmt.Println("  不是「数据永远消失」。把不可逆的操作用一个可逆的按钮承载，")
	fmt.Println("  是产品设计的常识。")
	fmt.Println()
	fmt.Println("★ 那「永久删除」的需求怎么满足？")
	fmt.Println("  GDPR 那种「用户要求删除我的全部数据」的合规需求 →")
	fmt.Println("  那是一个**独立的、需管理员审批的**流程（P2），")
	fmt.Println("  不是日常的「删除」按钮。本项目 P1 不做。")

	// -----------------------------------------------------------------
	hdr("8. 今天的判据")
