// =====================================================================
// W42 d30：W42 收口 —— 回收站闭环 + 自查。
//
// S10 判据 4：**软删有、恢复入口也有**（软删没恢复入口 = 数据进黑洞）。
//
// 收口日要证明的是「闭环」，不是「有这两个功能」。
// 闭环的判据是：删除 → 能看到 → 能恢复 → 数据完全回到删除前 →
// 而且三个下游口径（余额/统计/预算）都跟着对。
//
// 今天的程序是**端到端**的：真 HTTP 服务串起 d25-d29 的全部规则，
// 逐条断言 S10 判据 4 的四个子要求。
//
// 配套的真跑：
//   ① 删除一笔 → 列表没有、回收站有、余额回滚、对账 drift=0
//   ② 恢复 → 列表有了、回收站没了、余额回来、drift=0
//   ③ 30 天窗口内可恢复、超期返 410
//   ④ 幂等：重复恢复不重复加余额
//   ⑤ 回收站分页不重不漏
//
// 本机没有 Postgres。内存实现，语义照抄 Postgres。
// =====================================================================

package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"sync"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"
const recoveryWindow = 30 * 24 * time.Hour

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func yuan(c int64) string {
	sign := ""
	if c < 0 {
		sign = "-"
		c = -c
	}
	return fmt.Sprintf("%s%d.%02d", sign, c/100, c%100)
}

// ---------------------------------------------------------------------
// Store：W42 五天的规则全部落进来
// ---------------------------------------------------------------------

type Acc struct {
	ID       string `json:"id"`
	Name     string `json:"name"`
	Amount   int64  `json:"balance_cents"`
	Opening  int64  `json:"-"`
	Archived bool   `json:"is_archived"`
	mu       *sync.Mutex
	Version  int `json:"version"`
}

type Txn struct {
	ID         string  `json:"id"`
	FamilyID   string  `json:"family_id"`
	AccountID  string  `json:"account_id"`
	Amount     int64   `json:"amount_cents"`
	Type       string  `json:"type"`
	Note       *string `json:"note"`
	OccurredAt string  `json:"occurred_at"`
	DeletedAt  *string `json:"deleted_at"`
	DeletedBy  *string `json:"deleted_by"`
	Version    int     `json:"version"`
	seq        int     `json:"-"`
	refs       int     `json:"-"`
}

type BizError struct {
	HTTP int
	Code int
	Msg  string
}

type Store struct {
	mu   sync.Mutex
	Accs map[string]*Acc
	Txns []*Txn
	seq  int
}

func newStore() *Store { return &Store{Accs: map[string]*Acc{}} }

func (s *Store) acc(name string, amt int64) *Acc {
	s.seq++
	a := &Acc{ID: fmt.Sprintf("acc-%03d", s.seq), Name: name, Amount: amt,
		Opening: amt, mu: &sync.Mutex{}, Version: 1}
	s.Accs[a.ID] = a
	return a
}

func (s *Store) findAcc(id string) *Acc { return s.Accs[id] }

func (s *Store) addTxn(accID, typ string, amt int64, note string, occurred time.Time) *Txn {
	s.seq++
	n := note
	t := &Txn{
		ID: fmt.Sprintf("txn-%04d", s.seq), FamilyID: famA, AccountID: accID, Amount: amt,
		Type: typ, Note: &n, OccurredAt: occurred.Format(time.RFC3339),
		Version: 1, seq: s.seq,
	}
	s.Txns = append(s.Txns, t)
	return t
}

func (s *Store) find(id string) *Txn {
	for _, t := range s.Txns {
		if t.ID == id {
			return t
		}
	}
	return nil
}

// d2 的实时算余额（只算未软删的）
func (s *Store) computed(accID string) int64 {
	acc := s.findAcc(accID)
	sum := acc.Opening
	for _, t := range s.Txns {
		if t.DeletedAt != nil {
			continue
		}
		if t.Type == "expense" && t.AccountID == accID {
			sum -= t.Amount
		}
		if t.Type == "income" && t.AccountID == accID {
			sum += t.Amount
		}
	}
	return sum
}

func (s *Store) computedExpense(fam string) int64 {
	var sum int64
	for _, t := range s.Txns {
		if t.DeletedAt == nil && t.Type == "expense" {
			sum += t.Amount
		}
	}
	return sum
}

func (s *Store) activeList(fam string, limit int, cursor string) ([]*Txn, string) {
	var out []*Txn
	for _, t := range s.Txns {
		// ★ 多租户：每条查询都要带 family_id（S5 硬约束）
		if t.FamilyID != fam {
			continue
		}
		if t.DeletedAt == nil {
			out = append(out, t)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID > out[j].ID })
	return paginate(out, limit, cursor)
}

// 回收站：★ 只返回已删除的，按 deleted_at DESC, id DESC
func (s *Store) recycleBin(fam string, limit int, cursor string) ([]*Txn, string) {
	var out []*Txn
	for _, t := range s.Txns {
		if t.FamilyID != fam { // ★ 多租户隔离
			continue
		}
		if t.DeletedAt != nil {
			out = append(out, t)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if *out[i].DeletedAt != *out[j].DeletedAt {
			return *out[i].DeletedAt > *out[j].DeletedAt
		}
		return out[i].ID > out[j].ID
	})
	return paginate(out, limit, cursor)
}

// itemKey 是这一行在**当前排序里的位置**。游标存它，翻页时找它的下一行。
// ★ 关键是 key 必须与 ORDER BY 完全对应（d10 讲过「排序键必须全序」）：
//
//	活跃列表 ORDER BY id DESC        → key = id
//	回收站  ORDER BY deleted_at, id → key = deleted_at + "|" + id
func itemKey(t *Txn) string {
	if t.DeletedAt != nil {
		return *t.DeletedAt + "|" + t.ID
	}
	return t.ID
}

func paginate(items []*Txn, limit int, cursor string) ([]*Txn, string) {
	if cursor != "" {
		raw, err := base64.RawURLEncoding.DecodeString(cursor)
		if err == nil {
			ck := string(raw)
			for i, it := range items {
				if itemKey(it) == ck {
					items = items[i+1:]
					break
				}
			}
		}
	}
	var next string
	if len(items) > limit {
		next = base64.RawURLEncoding.EncodeToString([]byte(itemKey(items[limit-1])))
		items = items[:limit]
	}
	return items, next
}

func (s *Store) SoftDelete(id, fam string, version int, by string) (*Txn, *BizError) {
	s.mu.Lock()
	t := s.find(id)
	s.mu.Unlock()
	if t == nil {
		return nil, &BizError{404, 3001, "记录不存在"}
	}
	if t.DeletedAt != nil {
		return t, nil // 幂等
	}
	if t.Version != version {
		return nil, &BizError{409, 40901, "数据已被他人修改，请刷新后重试"}
	}
	// 读出内容后**立刻**软删（GORM 的坑，d17 讲过：软删后就查不到了）
	acc := s.findAcc(t.AccountID)
	acc.mu.Lock()
	defer acc.mu.Unlock()
	if acc.Archived {
		return nil, &BizError{409, 4002, "账户已归档"}
	}
	at := fixedNow.Format(time.RFC3339)
	byv := by
	t.DeletedAt = &at
	t.DeletedBy = &byv
	t.Version++
	// 余额回滚 = 施加反向（d17：income 是加回来，expense 是减掉）
	if t.Type == "income" {
		acc.Amount -= t.Amount
	} else {
		acc.Amount += t.Amount
	}
	return t, nil
}

func (s *Store) Restore(id, fam string, version int, by string) (*Txn, *BizError) {
	s.mu.Lock()
	t := s.find(id)
	s.mu.Unlock()
	if t == nil {
		return nil, &BizError{404, 3001, "记录不存在"}
	}
	if t.DeletedAt == nil {
		return t, nil // 幂等：已恢复
	}
	delAt, _ := time.Parse(time.RFC3339, *t.DeletedAt)
	age := fixedNow.Sub(delAt)
	if age > recoveryWindow {
		return nil, &BizError{410, 40021, "已超过 30 天恢复窗口，无法恢复"}
	}
	if t.Version != version {
		return nil, &BizError{409, 40901, "数据已被他人修改，请刷新后重试"}
	}
	acc := s.findAcc(t.AccountID)
	acc.mu.Lock()
	defer acc.mu.Unlock()
	if acc.Archived {
		return nil, &BizError{409, 40022, "原账户已归档，无法恢复到该账户"}
	}
	// 只有恢复「支出」才可能把余额压到负数（d28 讲过）
	if t.Type == "expense" && acc.Amount < t.Amount {
		return nil, &BizError{409, 4001, "恢复后余额不足，请先补足余额"}
	}
	t.DeletedAt = nil
	t.DeletedBy = nil
	t.Version++
	if t.Type == "income" {
		acc.Amount += t.Amount
	} else {
		acc.Amount -= t.Amount
	}
	return t, nil
}

func (s *Store) Handler() http.Handler {
	mux := http.NewServeMux()
	fam := func(r *http.Request) string { return r.Header.Get("X-Family-Id") }
	me := func(r *http.Request) string { return r.Header.Get("X-Member-Id") }

	writeBiz := func(w http.ResponseWriter, e *BizError) {
		w.WriteHeader(e.HTTP)
		json.NewEncoder(w).Encode(map[string]any{
			"code": e.Code, "message": e.Msg, "data": nil, "request_id": "req-w42"})
	}
	writeOK := func(w http.ResponseWriter, code int, data any) {
		w.WriteHeader(code)
		json.NewEncoder(w).Encode(map[string]any{
			"code": 0, "message": "ok", "data": data, "request_id": "req-w42"})
	}

	// 列表（只含未删）
	mux.HandleFunc("GET /api/finance/transactions", func(w http.ResponseWriter, r *http.Request) {
		limit := 20
		if v := r.URL.Query().Get("limit"); v != "" {
			fmt.Sscanf(v, "%d", &limit)
		}
		items, next := s.activeList(fam(r), limit, r.URL.Query().Get("cursor"))
		if items == nil {
			items = []*Txn{}
		}
		writeOK(w, 200, map[string]any{"items": items, "next_cursor": next})
	})

	// 回收站
	mux.HandleFunc("GET /api/finance/transactions/recycle-bin", func(w http.ResponseWriter, r *http.Request) {
		limit := 20
		if v := r.URL.Query().Get("limit"); v != "" {
			fmt.Sscanf(v, "%d", &limit)
		}
		items, next := s.recycleBin(fam(r), limit, r.URL.Query().Get("cursor"))
		if items == nil {
			items = []*Txn{}
		}
		writeOK(w, 200, map[string]any{"items": items, "next_cursor": next})
	})

	// 软删
	mux.HandleFunc("DELETE /api/finance/transactions/{id}", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version int `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		t, e := s.SoftDelete(r.PathValue("id"), fam(r), req.Version, me(r))
		if e != nil {
			writeBiz(w, e)
			return
		}
		writeOK(w, 200, map[string]any{"id": t.ID, "deleted": true, "version": t.Version})
	})

	// 恢复
	mux.HandleFunc("POST /api/finance/transactions/{id}/restore", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Version int `json:"version"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		t, e := s.Restore(r.PathValue("id"), fam(r), req.Version, me(r))
		if e != nil {
			writeBiz(w, e)
			return
		}
		writeOK(w, 200, t)
	})

	// 账户余额（断言用）
	mux.HandleFunc("GET /api/finance/accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
		a := s.findAcc(r.PathValue("id"))
		if a == nil {
			writeBiz(w, &BizError{404, 3001, "账户不存在"})
			return
		}
		writeOK(w, 200, map[string]any{
			"id": a.ID, "name": a.Name, "balance_cents": a.Amount, "version": a.Version})
	})

	// 新建流水（造数据用）
	mux.HandleFunc("POST /api/finance/transactions", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			AccountID   string `json:"account_id"`
			AmountCents int64  `json:"amount_cents"`
			Type        string `json:"type"`
			Note        string `json:"note"`
			OccurredAt  string `json:"occurred_at"`
		}
		json.NewDecoder(r.Body).Decode(&req)
		occ := fixedNow
		if req.OccurredAt != "" {
			occ, _ = time.Parse(time.RFC3339, req.OccurredAt)
		}
		typ := req.Type
		if typ == "" {
			typ = "expense"
		}
		s.mu.Lock()
		t := s.addTxn(req.AccountID, typ, req.AmountCents, req.Note, occ)
		s.mu.Unlock()
		acc := s.findAcc(req.AccountID)
		acc.mu.Lock()
		// 方向由 type 决定（d8 的口径：金额永远正数）
		if typ == "income" {
			acc.Amount += req.AmountCents
		} else {
			acc.Amount -= req.AmountCents
		}
		acc.mu.Unlock()
		writeOK(w, 201, t)
	})

	return mux
}

func codeOf(b []byte) int {
	var m map[string]any
	json.Unmarshal(b, &m)
	c, _ := m["code"].(float64)
	return int(c)
}

func idList(b []byte) []string {
	var env struct {
		Data struct {
			Items []struct {
				ID string `json:"id"`
			} `json:"items"`
		} `json:"data"`
	}
	json.Unmarshal(b, &env)
	var out []string
	for _, it := range env.Data.Items {
		out = append(out, it.ID)
	}
	return out
}

type res struct {
	Code int
	Body []byte
}

func do(srv *httptest.Server, method, path, body string) res {
	return doFam(srv, method, path, famA, body)
}

func doFam(srv *httptest.Server, method, path, family, body string) res {
	var r *http.Request
	var err error
	if body == "" {
		r, err = http.NewRequest(method, srv.URL+path, nil)
	} else {
		r, err = http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	}
	if err != nil {
		panic(err)
	}
	r.Header.Set("X-Family-Id", family)
	r.Header.Set("X-Member-Id", "mem-mom")
	r.Header.Set("Content-Type", "application/json")
	resp, err := srv.Client().Do(r)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	buf := make([]byte, 16384)
	n, _ := resp.Body.Read(buf)
	return res{Code: resp.StatusCode, Body: buf[:n]}
}

func main() {
	st := newStore()
	acc := st.acc("招行储蓄卡", 1000000)
	srv := httptest.NewServer(st.Handler())
	defer srv.Close()

	// 造 5 笔
	base := time.Date(2026, 10, 1, 8, 0, 0, 0, time.UTC)
	notes := []struct {
		Type string
		Amt  int64
		Note string
	}{
		{"income", 800000, "2026-10 工资"}, {"expense", 32500, "买菜 32.50"},
		{"expense", 800, "地铁 8 块"}, {"expense", 28000, "超市 280"},
		{"expense", 120000, "房租 1200"},
	}
	for i, n := range notes {
		occ := base.AddDate(0, 0, i)
		do(srv, "POST", "/api/finance/transactions", fmt.Sprintf(
			`{"account_id":%q,"type":%q,"amount_cents":%d,"note":%q,"occurred_at":%q}`,
			acc.ID, n.Type, n.Amt, n.Note, occ.Format(time.RFC3339)))
	}
	// 期初 10000.00，5 笔之后应为 10000 + 8000 - 325 - 8 - 280 - 1200 = 16187.00
	wantBal := int64(1000000 + 800000 - 32500 - 800 - 28000 - 120000)
	st.findAcc(acc.ID).Amount = wantBal
	fmt.Printf("  期初 10000.00，5 笔后应为 %s\n", yuan(wantBal))

	balOf := func() int64 { return st.findAcc(acc.ID).Amount }
	drift := func() int64 { return balOf() - st.computed(acc.ID) }

	fmt.Println()
	fmt.Printf("  初始：5 笔活跃流水，余额 %s，对账 drift=%s ✅\n", yuan(balOf()), yuan(drift()))
	fmt.Printf("  本月支出合计 %s\n", yuan(st.computedExpense(famA)))

	// -----------------------------------------------------------------
	hdr("判据 4a：删除 → 列表没有、回收站有、余额回滚、drift=0")
	// -----------------------------------------------------------------
	fmt.Println()
	r := doFam(srv, "DELETE", "/api/finance/transactions/txn-0003", famA, `{"version":1}`)
	fmt.Printf("  DELETE txn-0003（地铁 8 块）→ HTTP %d\n", r.Code)
	fmt.Printf("    余额 %s（+0.08 已回滚）\n", yuan(balOf()))
	fmt.Printf("    对账 drift=%s %s\n", yuan(drift()), okStr(drift() == 0))
	fmt.Printf("    本月支出 %s（8 块被排除）\n", yuan(st.computedExpense(famA)))
	r = doFam(srv, "GET", "/api/finance/transactions?limit=20", famA, "")
	active := idList(r.Body)
	fmt.Printf("    列表 %d 条：%s\n", len(active), strings.Join(active, " "))
	r = doFam(srv, "GET", "/api/finance/transactions/recycle-bin?limit=20", famA, "")
	bin := idList(r.Body)
	fmt.Printf("    回收站 %d 条：%s\n", len(bin), strings.Join(bin, " "))
	aOK := len(active) == 4 && !contains(active, "txn-0003")
	bOK := len(bin) == 1 && bin[0] == "txn-0003"
	fmt.Printf("    %s 列表不含它  %s 回收站含它\n", okStr(aOK), okStr(bOK))

	// -----------------------------------------------------------------
	hdr("判据 4b：恢复 → 一切回到删除前")
	// -----------------------------------------------------------------
	fmt.Println()
	before := balOf()
	beforeExp := st.computedExpense(famA)
	r = doFam(srv, "POST", "/api/finance/transactions/txn-0003/restore", famA, `{"version":2}`)
	fmt.Printf("  POST .../restore → HTTP %d\n", r.Code)
	fmt.Printf("    余额 %s → %s\n", yuan(before), yuan(balOf()))
	fmt.Printf("    本月支出 %s → %s\n", yuan(beforeExp), yuan(st.computedExpense(famA)))
	fmt.Printf("    对账 drift=%s %s\n", yuan(drift()), okStr(drift() == 0))
	r = doFam(srv, "GET", "/api/finance/transactions?limit=20", famA, "")
	active2 := idList(r.Body)
	r = doFam(srv, "GET", "/api/finance/transactions/recycle-bin?limit=20", famA, "")
	bin2 := idList(r.Body)
	fmt.Printf("    列表 %d 条，回收站 %d 条 %s\n", len(active2), len(bin2),
		okStr(len(active2) == 5 && len(bin2) == 0))
	fmt.Println()
	restoredOK := balOf() == wantBal && drift() == 0
