func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

func okStr(b bool) string {
	if b {
		return "✅"
	}
	return "❌"
}

// =====================================================================
// W43 d31：附件 —— finance_attachment 不建表，用 Transaction.receipt 存 file_id。
//
// S10 判据 5：**附件超 3 张或超 5MB 被服务端拒绝**。
//
// 今天的核心问题不是「怎么上传」，而是「**为什么不上传**」：
// 一个「一笔流水最多 3 张票据」的需求，需要几张表？
//
// 答案：不建表。三种方案对比：
//   ① 独立的 finance_attachment 表      ← 最直觉，也最贵
//   ② receipt 里存 file_id 字符串     ← 本项目采用
//   ③ receipt 里存 JSONB 数组
//
// 第 3 节真跑：三种方案在「查询/删除/级联/约束」四个维度上的差异。
// 第 5 节真跑：3 张 / 5MB 两条限制的拒绝演示（判据 5）。
// 第 6 节：孤儿票据怎么处理（跨服务无外键的后果）。
//
// 本机没有 Postgres。内存模拟，SQL 手写。
// =====================================================================

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

// 铁律 6 的三条限制
const (
	MaxAttachments = 3
	MaxFileSize    = 5 * 1024 * 1024 // 5MB
	AllowedTypes   = "jpg/png/webp"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// ---------------------------------------------------------------------
// 方案 ②：receipt 存 file_id（一个字符串）
// ---------------------------------------------------------------------

type FileRef struct {
	FileID   string
	Filename string
	SizeByte int
	MimeType string
}

type Txn struct {
	ID        string
	AccountID string
	Amount    int64
	Note      string
	Receipt   *string // ★ 只存一个 file_id
	Version   int
}

type BizError struct {
	HTTP int
	Code int
	Msg  string
}

// 模拟 files 服务（S4 建的 homeos_files）
type FileSvc struct {
	Files map[string]FileRef
	seq   int
}

func newFileSvc() *FileSvc { return &FileSvc{Files: map[string]FileRef{}} }

func (f *FileSvc) Upload(fam, filename string, size int, mime string) (string, *BizError) {
	if size > MaxFileSize {
		return "", &BizError{413, 40031, fmt.Sprintf(
			"文件 %s（%.1f MB）超过单张上限 5 MB", filename, float64(size)/1024/1024)}
	}
	// 类型白名单：认 mime 的**子类型**，不认前缀
	sub := strings.ToLower(strings.TrimPrefix(mime, "image/"))
	switch sub {
	case "jpg", "jpeg", "png", "webp":
		// 通过
	default:
		return "", &BizError{415, 40032, fmt.Sprintf(
			"不支持的类型 %s，只允许 jpg/png/webp（PRD 铁律 6）", mime)}
	}
	ext := sub
	if ext == "jpeg" {
		ext = "jpg" // 统一成 jpg 后缀
	}
	// file_id = uploads/{family_id}/{yyyymm}/{hash}.jpg
	h := sha256.Sum256([]byte(fam + filename + fmt.Sprint(size)))
	f.seq++
	id := fmt.Sprintf("uploads/%s/202610/%s-%d.%s",
		fam[:8], hex.EncodeToString(h[:])[:12], f.seq, ext)
	f.Files[id] = FileRef{FileID: id, Filename: filename, SizeByte: size, MimeType: mime}
	return id, nil
}

func (f *FileSvc) Get(id string) (FileRef, bool) {
	r, ok := f.Files[id]
	return r, ok
}

func (f *FileSvc) Delete(id string) { delete(f.Files, id) }

func (f *FileSvc) Count() int { return len(f.Files) }

// ---------------------------------------------------------------------
// 流水：只有一个 receipt 字段
// ---------------------------------------------------------------------

type Store struct {
	Txns  []*Txn
	Files *FileSvc
	seq   int
}

func newStore() *Store { return &Store{Files: newFileSvc()} }

func (s *Store) addTxn(accID string, amt int64, note string) *Txn {
	s.seq++
	t := &Txn{ID: fmt.Sprintf("txn-%04d", s.seq), AccountID: accID,
		Amount: amt, Note: note, Version: 1}
	s.Txns = append(s.Txns, t)
	return t
}

func (s *Store) find(id string) *Txn {
	for _, t := range s.Txns {
		if t.ID == id {
			return t
		}
	}
	return nil
}

// Attach 绑定一个附件到流水
func (s *Store) Attach(txnID, filename string, size int, mime string) (*Txn, *BizError) {
	t := s.find(txnID)
	if t == nil {
		return nil, &BizError{404, 3001, "流水不存在"}
	}
	// 限制 ①：最多 3 张
	// ★ 方案 ②的代价：这是**应用层**检查，因为一个字符串装不下 3 个 file_id
	if t.Receipt != nil {
		return nil, &BizError{409, 40033,
			"该流水已绑定一张票据，每笔流水最多 1 张（P1 口径，d31 第 6 节展开）"}
	}
	id, err := s.Files.Upload(famA, filename, size, mime)
	if err != nil {
		return nil, err // 413 / 415 直接透传
	}
	t.Receipt = &id
	t.Version++
	return t, nil
}

func attachWord(t *Txn, e *BizError) string {
	if e != nil {
		return fmt.Sprintf("HTTP %d code=%d", e.HTTP, e.Code)
	}
	return "✅ 成功 " + *t.Receipt
}

