	fmt.Println("Go：流式上传 + 边写边计数（不能先 ReadAll 再判大小）")
	fmt.Println("```go")
	fmt.Println("func (h *FileHandler) Upload(c *gin.Context) {")
	fmt.Println("    fh, err := c.FormFile(\"file\")")
