	fmt.Println("    if fh.Size > MaxFileSize {          // ① 头里就有大小，先拒")
	fmt.Println("        413")
	fmt.Println("    }")
	fmt.Println("    f, _ := fh.Open()")
	fmt.Println("    defer f.Close()")
	fmt.Println("")
	fmt.Println("    // ② 落盘到临时文件，同时数真实字节数")
	fmt.Println("    tmp, _ := os.CreateTemp(\"\", \"upload-*\")")
	fmt.Println("    n, _ := io.Copy(tmp, io.LimitReader(f, MaxFileSize+1))")
	fmt.Println("    tmp.Close()")
	fmt.Println("    if n > MaxFileSize {                // ③ 声明的长度可能是假的")
	fmt.Println("        os.Remove(tmp.Name())")
	fmt.Println("        413")
	fmt.Println("    }")
	fmt.Println("")
