// =====================================================================
// W43 d32：★ due_at 注册到 S9 的到期中心 —— S9 的注册契约在流水上的真实应用。
//
// S10 判据 6：**一笔带 due_at 的流水能被注册到 calendar，并在到期中心看到**。
//
// 这是 S9 学的注册契约（`{code}.due.registered`）的**第一次真实使用**。
// S9 学的是「契约长什么样」，今天要回答三个更难的问题：
//   ① finance 侧怎么在**同一事务**里登记注册意图（d14 讲的 outbox）
//   ② due_at 改期时是「撤销 + 重新注册」还是「原地更新」
//   ③ 哪些流水**不该**注册（S9 d11 讲过不注册清单，要落到具体字段上）
//
// 第 3 节真跑：一笔带 due_at 的流水 → outbox → 消费者 → 到期中心可见
// 第 4 节真跑：改期（d13 展开）→ 两个注册项并存的问题
// 第 5 节真跑：软删 → 级联撤销（S9 d9 讲过的钩子）
// 第 6 节：不注册清单在流水上的具体判据
//
// 本机没有 Postgres / NATS。事件总线与两个 schema 都内存模拟，
// 语义照抄 PRD 10.4 的 outbox + JetStream。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

var fixedNow = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

const famA = "aaaaaaaa-0000-4000-8000-000000000001"

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 事件信封：PRD 10.4 的 13 字段（今天只用其中 7 个）
// =====================================================================

type Envelope struct {
	EventID       string    `json:"event_id"`
	EventType     string    `json:"event_type"`
	Source        string    `json:"source"`
	SourceID      string    `json:"source_id"`
	OccurredAt    time.Time `json:"occurred_at"`
	TraceID       string    `json:"trace_id"`
	FamilyID      string    `json:"family_id"`
	SchemaVersion int       `json:"schema_version"`
	Payload       any       `json:"payload"`
}

// 幂等键三元组（S9 d3）
type RegKey struct {
	Source   string // "finance"
	SourceID string
	Kind     string // "reminder" | "event" | "todo"
}

func (k RegKey) String() string { return fmt.Sprintf("(%s,%s,%s)", k.Source, k.SourceID, k.Kind) }

// =====================================================================
// finance 侧：outbox + 业务表
// =====================================================================

type FinanceTxn struct {
	ID        string
	AccountID string
	Amount    int64
	Type      string
	Note      string
	DueAt     *time.Time // ★ 本阶段新增字段
	Version   int
	Deleted   bool
	DelAt     *time.Time
}

type FinanceDB struct {
	Txns   []*FinanceTxn
	Outbox []*Envelope
	seq    int
	inTx   bool
	txBuf  []*FinanceTxn
	obBuf  []*Envelope
}

func newFinanceDB() *FinanceDB { return &FinanceDB{} }

func (f *FinanceDB) add(accID string, amt int64, note string, due *time.Time) *FinanceTxn {
	f.seq++
	t := &FinanceTxn{ID: fmt.Sprintf("txn-%04d", f.seq), AccountID: accID,
		Amount: amt, Type: "expense", Note: note, DueAt: due, Version: 1}
	if f.inTx {
		f.txBuf = append(f.txBuf, t)
	} else {
		f.Txns = append(f.Txns, t)
	}
	return t
}

func (f *FinanceDB) find(id string) *FinanceTxn {
	for _, t := range f.Txns {
		if t.ID == id && !t.Deleted {
			return t
		}
	}
	return nil
}

func (f *FinanceDB) Begin() { f.inTx = true; f.txBuf = nil; f.obBuf = nil }
func (f *FinanceDB) Commit() {
	f.Txns = append(f.Txns, f.txBuf...)
	f.Outbox = append(f.Outbox, f.obBuf...)
	f.inTx = false
	f.txBuf, f.obBuf = nil, nil
}
func (f *FinanceDB) Rollback() { f.inTx = false; f.txBuf, f.obBuf = nil, nil }

// putOutbox：在事务内登记注册意图（d14 的铁律）
func (f *FinanceDB) putOutbox(evType string, sourceID string, payload map[string]any) {
	f.seq++
	e := &Envelope{
		EventID: fmt.Sprintf("ev-%04d", f.seq), EventType: evType,
		Source: "finance", SourceID: sourceID, OccurredAt: fixedNow,
		TraceID: "trace-w43-01", FamilyID: famA, SchemaVersion: 1,
		Payload: payload,
	}
	if f.inTx {
		f.obBuf = append(f.obBuf, e)
	} else {
		f.Outbox = append(f.Outbox, e)
	}
}

// =====================================================================
// calendar 侧：注册表 + 到期中心
// =====================================================================

type RegRow struct {
	Key      RegKey
	Title    string
	DueAt    time.Time
	Active   bool
	Revoked  string // 撤销原因
	SourceTx string
}

type CalendarDB struct {
	Rows []*RegRow
	seq  int
	// 消费者去重表（S9 d3：幂等键三元组）
	Seen map[RegKey]bool
	// 降级词
	Unreachable bool
}

func newCalendarDB() *CalendarDB {
	return &CalendarDB{Seen: map[RegKey]bool{}}
}

type BizError struct {
	HTTP int
	Code int
	Msg  string
}

func (c *CalendarDB) consume(e *Envelope) (string, *BizError) {
	if c.Unreachable {
		return "", &BizError{503, 50001, "calendar 不可达"}
	}
	switch e.EventType {
	case "finance.due.registered", "finance.due.revoked":
	default:
		return "忽略（不属于到期事件）", nil
	}
	p, _ := e.Payload.(map[string]any)
	kind, _ := p["kind"].(string)
	if kind == "" {
		kind = "reminder"
	}
	key := RegKey{Source: e.Source, SourceID: e.SourceID, Kind: kind}

	if e.EventType == "finance.due.registered" {
		if c.Seen[key] {
			return fmt.Sprintf("幂等命中：%s 已存在，跳过", key), nil
		}
		dueStr, _ := p["due_at"].(string)
		due, _ := time.Parse(time.RFC3339, dueStr)
		c.seq++
		c.Rows = append(c.Rows, &RegRow{
			Key: key, Title: p["title"].(string), DueAt: due, Active: true, SourceTx: e.SourceID})
		c.Seen[key] = true
		return fmt.Sprintf("已落库 %s：%s（due %s）", key, p["title"], due.Format("01-02 15:04")), nil
	}

	// revoked
	reason, _ := p["reason"].(string)
	n := 0
	for _, r := range c.Rows {
		if r.Key == key && r.Active {
			r.Active = false
			r.Revoked = reason
			n++
		}
	}
	// ★★ 关键实现细节（S9 d7 讲过，这里落到代码）：
	//   reason=rescheduled → **必须清掉 Seen**，否则紧接着的 registered
	//                        会被当重复挡掉 → 到期中心永远停在旧日期
	//   其他 reason         → **不清**，那个 key 永久封禁
	switch reason {
	case "rescheduled":
		delete(c.Seen, key)
		return fmt.Sprintf("撤销 %s：%d 行 inactive（reason=%s，**已清幂等表**允许重注册）", key, n, reason), nil
	default:
		return fmt.Sprintf("撤销 %s：%d 行 inactive（reason=%s，幂等表**保留**封禁此 key）", key, n, reason), nil
	}
}

// 到期中心视图（只列 active 的，按 due_at 升序）
func (c *CalendarDB) dueCenter() []*RegRow {
	var out []*RegRow
	for _, r := range c.Rows {
		if r.Active {
			out = append(out, r)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].DueAt.Before(out[j].DueAt) })
	return out
}

